  "lede": "世界変異体対策総本部（SVH）の隊員が、どのように選ばれ、訓練され、情報を管理され、退役するのか。GIIR値で人を選ばず、炎を使う判断を学び、退役時には記憶処理を受ける。SVHは隊員の記憶まで守る組織である。",
