      "text": "Meltは、短い文章を投稿するSNSである。ニュースへの反応、社会問題についての議論、趣味の話題、日常的な雑談まで、投稿の内容は幅広い。匿名性の高いアカウントが多く、Lumoよりも率直な意見が投稿されやすい。"
