  "title": "世界の気候",
  "updated": "2026.10.24",
  "lede": "各国の気候帯と、気候が安定化されているかどうかの一覧。氷河期を越えた世界では、気象の安定化技術によって多くの国の気候が管理されている一方、ガルヒューラとマイモックは、いまも安定化されていない。チリルド・アイルツアでは、建国以来続いていた降雪が止まるという異変が起きている。",
