      { t: 'p', text: 'これらの発掘では、当時の記録と一致する施設が確認される場合もあれば、既存の資料からは存在が知られていなかった施設が見つかる場合もある。なぜ地上に残らなかったのか、地域によって残り方がどう違うのかは、近代文明の発掘と遺構の項目にまとめている。' }
