/* ============================================================================
   ARTICLES-EXPAND — 2026.10.26（3）
   各国の「観光と名物」と、旅行と観光（新規記事）。
   名物料理は既存の設定にあるものだけを載せている（新しい料理は未採用）。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.26';
  function sec(title, rows, paras){
    var b = [];
    (paras.before||[]).forEach(function(t){ b.push({ t:'p', text:t }); });
    if(rows && rows.length) b.push({ t:'table', headers:['名所・体験','内容'], rows:rows });
    (paras.after||[]).forEach(function(t){ b.push({ t:'p', text:t }); });
    if(paras.quote) b.push({ t:'quote', text:paras.quote });
    return { id:'sec-tourism', title:title, blocks:b };
  }
  var T = '観光と名物';
  var PATCH = [
  { id:'belnea', op:'addSection', after:'sec-longdao', section: sec(T, [
      ['オーシャンドーム', '浅瀬から深海までを再現した巨大水中ドーム。夜には発光生物が幻想的な景色を作り、ベルネアで最も人気のある観察地になっている。'],
      ['テンペレートドーム', 'ベルネア人が最初に生命へ触れる教育用ドーム。落葉樹林や草原が広がり、初めての観光客にも歩きやすい。'],
      ['デザートドームとアークティックドーム', '砂丘と氷原という正反対の環境を、同じ国の中で見比べられる。どちらも夜に生物の動きが変わる。'],
      ['大ドームの日（11月16日）', 'セントラルドームを中心に、ふだん公開されない区画の観察会が開かれる。この日を目当てに訪れる研究者や観光客も多い。']
    ], {
      before:['ベルネアの観光は「観察」である。六つの環境ドームは研究施設であると同時に、世界中の生態系を一つの国で見て回れる場所でもある。'],
      after:['見学者には、触らない、追わない、待つという観察の作法が求められる。トロピカルドームは危険度が高く、夜間の立ち入りは厳しく制限されている。','食事は培養肉が中心で、生物を殺して食べる文化は一般的ではない。ベルネアならではの名物料理は、まだ広く知られていない。']
    })},
  { id:'chiriludo-ailtsua', op:'addSection', after:'sec-facilities', section: sec(T, [
      ['天界氷廊群（東海岸地域）', '数百年分の氷彫刻が残る、チリルド最大の景観遺産。夜は雪明かりに照らされ、世界中から観光客が訪れる。'],
      ['白景回廊（東海岸地域）', '氷彫刻とホテルが並ぶ観光の中心。国外からの観光客が最も多い。'],
      ['西海岸の氷像の街', '大小さまざまな氷像が街中にある、職人と愛好家の街。静かな創作の空気を味わえる。'],
      ['北海岸の伝統文化', '犬ぞり祭りや氷海漁など、古くからの暮らしが残る。'],
      ['氷彫刻祭（11月3日）', '都市各地に氷の建築物や彫刻が並ぶ、チリルド最大の祭り。']
    ], {
      before:['チリルド・アイルツアは、世界でも有数の観光国である。古い作品を壊さずに残す文化が、数百年分の白景を一つの景色にした。'],
      after:['名物は、解凍した魚にニンニクの効いたアシマヤソースをかけるナントッカナッチャルノ。寒い土地で働く人々の活力源として親しまれてきた。','いま、建国以来続いていた雪が止まっている。訪れる人の中には、この白景がいつまで変わらずにいるのかを確かめに来る人もいる。'],
      quote:'雪が止んでも、積み重ねた白は、まだそこにある。'
    })},
  { id:'fumora-skypill', op:'addSection', after:'sec-wingmark', section: sec(T, [
      ['外周展望リング（スカイラリス）', '成層圏から地上を見下ろせる展望施設。国家全体が回転しているため、立っているだけで景色が少しずつ移り変わる。'],
      ['空中市場（スカイラリス）', '世界中から集まった人々の文化が混ざり合う市場。フーモラに統一された文化がないことを、最もよく感じられる場所。'],
      ['スカイアロー', '空や地上、ほかの都市を見渡すための景観特化型の都市。'],
      ['リング観光パッケージ', '円環状に並ぶ複数の都市を巡る、フーモラ独自の観光ルート。'],
      ['空中散歩の日（11月11日）', '空中都市を歩きながら景色を楽しむ日。ふだんとは違う経路や高所を歩く。'],
      ['天翼紋の日（8月8日）', '都市各地に天翼紋が掲げられ、その意味を語り合う日。']
    ], {
      before:['フーモラ・スカイピルは、観光そのものが国の顔になっている数少ない国である。都市間の移動は自動航行の空路ネットワークが担い、観光客は操縦することなく、空の上を巡ることができる。'],
      after:['名物は、塔型の構造とリング状の装飾を持つスカイラリスパフェと、空の色や都市の光を再現した空景ドリンクである。空景ドリンクは都市ごとに種類が違い、巡りながら飲み比べるのが定番になっている。'],
      quote:'同じ場所に立っていても、空は同じ景色を二度見せない。'
    })},
  { id:'garhyura', op:'addSection', after:'sec-four-dark', section: sec('観光', [], {
      before:['ガルヒューラには、観光という考え方が存在しない。観光客を迎えるための施設も制度もなく、国外の人々がこの国の景色を見ることはほとんどない。','他国の人々にとって最も身近なガルヒューラは、四暗都市を題材にしたフルダイブゲームの中にある。そこで体験できるのは、安全に作り直された四暗都市であり、本当のガルヒューラではない。ガルヒューラの人々は、そのことを知らない。']
    })},
  { id:'hubert', op:'addSection', after:'sec-ethics', section: sec(T, [
      ['ハーネンス中央都市', '白を基調とした未来建築が広がる巨大研究都市。研究塔、医療施設、住宅、商業施設が一体になった街並みそのものが見どころになっている。'],
      ['猫と歩く街', '街中を猫が自由に歩いている。猫カフェや猫専門施設、猫と共存する住宅設計が一般的で、猫を目当てに訪れる人も多い。'],
      ['猫の記念日', '猫の日（2月22日）、猫感謝の日（6月6日）、猫の再誕の日（9月22日）、猫の健康の日（10月10日）、猫祭り（11月11日）。猫の再誕の日には、猫と暮らす住宅や施設が公開される。'],
      ['生命共生祭（6月6日）', '研究成果の公開や、生命倫理について考える催しが行われる。']
    ], {
      before:['ヒューバートを訪れる人の多くは、観光客というより、医療や研究を目的とした人々である。医療技術発祥の国として、治療を受けるために訪れる人も少なくない。'],
      after:['一方で、ヒューバートの中心であるハーネンス研究所は、所在地すら明かされていない。訪れる人が見られるのは、この国のごく表側だけである。','ヒューバートならではの名物料理は、まだ広く知られていない。効率を重んじる国らしく、食事は手早く済ませる人が多いとも言われる。']
    })},
  { id:'kyuma', op:'addSection', after:'sec-facilities', section: sec(T, [
      ['体験区', '蒸気機関街や古代様式住宅、歴史体験街が並ぶ地区。蒸気鉄道に乗り、当時の街並みの中で実際に暮らしを体験できる。'],
      ['国家考古学博物館', '首都エータル最大の博物館。世界中の研究者と観光客が訪れる。'],
      ['古代料理店', '復元された調理法で、過去の時代の料理を出す店。キューマでは観光向けではなく、日常の外食の一つである。'],
      ['天翼区', '天翼紋の遺物や古代文明の関連施設が集まる地区。最高機密級の天翼保管庫は公開されていない。'],
      ['疑問の日（10月4日）', '身近な疑問から未知の知識へ目を向ける日。「なぜ？」を大切にするキューマの文化を象徴する。']
    ], {
      before:['キューマは、歴史を見る国ではなく、歴史を体験する国である。観光客が目にする蒸気機関車や歴史衣装は、観光のための演出ではなく、キューマの人々の日常の一部になっている。'],
      after:['キューマで建設中に遺構が見つかると、工事は止められ、発掘が優先される。運がよければ、観光客も発掘の現場に立ち会えることがある。'],
      quote:'過去は展示ケースの中ではなく、通りの向こうを走っている。'
    })},
  { id:'larliafrus', op:'addSection', after:'sec-facilities', section: sec(T, [
      ['リアン', '森体験と癒しのツーリズムが盛んな祭礼の都市。ヒカリタケの光る回廊や発光小道が、夜の森を幻想的に照らす。'],
      ['リフィネスの神殿', '森の奥にある信仰の中心。誰でも立ち入ることができ、8メートルの抽象的なリフィネス像がある。'],
      ['リフランの月脈樹', '首都の居住区の中心にある月脈樹。森と都市が半分ずつ溶け合った街並みが見られる。'],
      ['収穫祭（9月20日）', '森の恵みに感謝する年に一度の祭り。地域によっては成人の儀式も行われる。']
    ], {
      before:['ラリアフルスの観光は、森の中で過ごす時間そのものである。移動は徒歩が多く、速く巡るより、森の流れに合わせて歩くことが勧められる。'],
      after:['訪れる人にも、森を壊さないこと、森をけなさないことが求められる。採集の体験では、地元の人々と同じようにリフィネスへ祈ってから採る。','名物は、根菜や山菜を串に刺して焼き、森の果実のソースをかけるファラサバ。辛いものが好きな人には、死辛草と辛味鳥の培養肉を使ったオーバーキル串焼きがある。ラリアフルスの植物は、培養肉を食べる意味がないと言われるほど美味しい。']
    })},
  { id:'maimok', op:'addSection', after:'sec-svh', section: sec('観光', [], {
      before:['マイモックは観光の対象ではない。霧は空気、食品、水に広がっており、立ち入るだけで影響を受けるおそれがある。SVHでさえ、飲食禁止、昼間の活動禁止、接触回避を原則としている。','マルネアに大量に残るホテルや娯楽施設は、国家が崩壊する前の滞在施設の名残である。かつてのマイモックは、人が楽しみを求めて訪れる場所だったことになる。いまも管理者のいないホテルを、ロボットだけが整え続けている。'],
      quote:'迎える準備だけが、いまも続いている。'
    })},
  { id:'niporan', op:'addSection', after:'sec-life', section: sec(T, [
      ['京都', '長い歴史を持つ文化と、未来の都市機能が共存する巨大都市。'],
      ['東京', '関西変異災害の後に国家中枢となった首都。日本文化と未来技術が融合した街並みを持つ。'],
      ['お茶の日（10月10日）', '各地でさまざまなお茶が楽しまれ、茶にまつわる催しが行われる。'],
      ['米菓の日（11月11日）', '地域ごとの米菓や、家庭で親しまれてきた味が紹介される。'],
      ['関西変異災害追悼日（12月20日）', '災害の犠牲者を追悼し、その教訓を後世へ伝える日。']
    ], {
      before:['ニポランは、広大な地域を一つの都市として扱う八つの大都市からなる。旧時代の都市の名前を受け継ぎながら、規模も構造も大きく変わっている。'],
      after:['旧日本の地であるニポランには、近代文明の遺構や記録が他の地域より多く残っている。','大阪の封鎖区は観光地ではない。ニポランでは、平和は誰かが守っているものだという意識が強く、封鎖区の存在もその一部として受け止められている。']
    })},
  { id:'orgaron', op:'addSection', after:'sec-relations', section: sec(T, [
      ['フォルネータ', '巨大劇場群と運河沿いの美術館群が並ぶ首都。都市全体が舞台のような景観を持つ。'],
      ['バルベルクの塔', '戦時中の監視塔を改修した芸術建築。戦争資料と芸術作品を保存する、国の象徴。'],
      ['フォルテ', '巨大壁画と野外ステージの街。ライブや路上芸術が夜まで続く。'],
      ['ピアニッシモ', 'VR芸術や光学芸術など、最先端の表現が集まる都市。夜は青白い光に包まれる。'],
      ['バルベルク（10月24日）・作品交換の日（11月11日）', '街中が作品や装飾で彩られる祭典と、自分の作品を誰かと交換する日。観光客も参加できる。']
    ], {
      before:['オルガロンでは、街そのものが作品である。九つの都市がそれぞれ違う芸術を担っており、静けさを味わう街もあれば、熱気にあふれる街もある。'],
      after:['オルガロンの食事は、味だけでなく色彩や香り、空間や会話まで含めた表現である。生演奏付きの食事は、観光客にも人気が高い。','訪れる人に求められるのは一つだけである。芸術を汚してはならない。'],
      quote:'見るだけでは終わらない。持ち帰るのは、何かを作りたいという気持ちである。'
    })},
  { id:'sanrudo', op:'addSection', after:'sec-festival', section: sec(T, [
      ['ヴォルグレン', '世界最大級のカジノ街と幻想娯楽市場を持つ黄金区域最大の都市。GRKの統合型リゾートには、世界中から富豪や観光客が集まる。'],
      ['双輝祭大劇場・世界競売場（ヴォルグレン）', '双輝祭の舞台となる大劇場と、世界中の品が競り落とされる競売場。'],
      ['静寂回廊（クレディア）', '白金区域を代表する静寂都市の回廊。ヴォルグレンの熱狂とは正反対の、白く静かな街並みを歩ける。'],
      ['ラルウォットの旧市街', '古い石造銀行や歴史ある取引所が並ぶ首都。派手さより、重厚な価値の歴史を感じさせる。'],
      ['仮面の日（10月5日）・双輝祭（12月31日）', '仮面が街を彩る日と、一年の終わりに黄金と白金がぶつかり合うサンルド最大の祭典。']
    ], {
      before:['サンルドの観光は、黄金と白金のどちらを見るかで、まったく違う旅になる。'],
      after:['観光客向けの仮面も売られている。仮面は正体を隠すものではなく、役割を示すものであるため、何の仮面を選ぶかが、その旅で自分がどう振る舞うかを示すことになる。','土産物には人工黄金の装飾品が多い。天然黄金を名乗る品には、高度な鑑定がつきものである。'],
      quote:'価値があるかどうかは、君次第だ。'
    })},
  { id:'sertcity', op:'addSection', after:'sec-relations', section: sec('観光', [
      ['セルトタワーを見上げる', '都市を覆う巨大な施設のさらに上へそびえる、黒と白のガラスの塔。現実のセルトシティで一般の人が見られるのは、ほとんど外から見るこの姿だけである。'],
      ['サイバーセルトシティ', '世界中の誰もがアクセスできる仮想都市。多くの人にとっての「セルトシティ観光」は、こちらを指す。']
    ], {
      before:['現実のセルトシティには、観光で入ることができない。立ち入りは研究者や関係者に限られ、子どもの居住や一般的な立ち入りも制限されている。'],
      after:['世界で最も多くの人に使われている都市でありながら、その本当の姿を見たことのある人は、ごくわずかである。']
    })},
  { id:'tasumenio', op:'addSection', after:'sec-culture', section: sec(T, [
      ['世界接続塔・中央転送広場（タハルン）', 'ほぼすべての国際転送が経由する、世界最大級のテレポート集合塔。世界中の旅人が行き交う「世界の交差点」。'],
      ['ルハータの多国籍市場', '高床式建築と空中回廊が並ぶ生活都市の市場。世界中の品が集まる。'],
      ['硝子海', '年に数回だけ風が完全に止まり、海面が鏡のようになる現象。空と海の境界が消える。'],
      ['夜の海', '海面は場所によって濃い青、エメラルド色、群青色に変わり、夜には微弱な発光が見られる。'],
      ['旅の日（9月27日）・遠くへ行く日（11月11日）', 'テレポート中継網を使った旅や、遠く離れた土地を訪れることを楽しむ日。']
    ], {
      before:['タスメニオは、世界で最も多くの旅人が通る国である。国際転送のほとんどがタハルンを経由するため、旅人の多くは、この国に降り立つことなく通り過ぎていく。'],
      after:['海底都市は立入禁止区域であり、観光地ではない。','名物は、貝の殻の中で米や魚介類を蒸し上げる大貝蒸し飯。保存食のしらすもちは、独特の風味で好みが分かれる。'],
      quote:'誰もが通る国で、立ち止まる人は少ない。だからこそ、立ち止まった人だけが硝子海を見る。'
    })},
  { id:'wonhead', op:'addSection', after:'sec-facilities', section: sec(T, [
      ['百層屋台街（イーテスタ）', '首都イーテスタを代表する屋台街。世界中の料理が集まる。'],
      ['最初の共鍋炉', '鍋文化発祥の地とされる歴史的施設。'],
      ['ログナの共火広場', '見せかけの炎を灯す巨大炉の周りで、「火を囲む時間」を味わえる。夜は赤く暖かな光に包まれる。'],
      ['グリザの長机', '屋台と長机が街を埋め尽くし、知らない者同士でも自然に食卓を囲む。'],
      ['スモルの燻香', '火を使わない燻香の再現技術によって、街全体に静かな燻香が漂う職人の街。'],
      ['世界料理祭（12月25日）', '世界各地の料理と食文化が集まる、ヲンヘード最大級の食文化行事。']
    ], {
      before:['ヲンヘードの観光は、食べることに尽きる。九つの都市がそれぞれ違う食文化を担っており、都市を巡ることが、そのまま食べ歩きになる。'],
      after:['ヲンヘードには、食べ物の記念日が数えきれないほどある。いつ訪れても、どこかの街で何かの日を祝っている。','「空腹は最高のスパイス」という考え方から、ヲンヘードを旅する人の中には、あえて食事の間隔を空けて次の街へ向かう人もいる。'],
      quote:'おきやすに。'
    })},
  { id:'yuretsuea', op:'addSection', after:'sec-life', section: sec(T, [
      ['ツェンタル・ネヘタ（ミレタッツァ）', '数百年前に建てられ、いまも正確に動き続ける巨大時計塔。新人職人が訪れることが伝統になっている。'],
      ['時計工房街・工匠博物館（ツァンタルコッタ）', '数百年以上使われ続ける工房が残る歴史都市。職人の仕事を間近で見られる。'],
      ['修理工房（フツァンッタイナ）', '交易都市に数多くある修理工房。'],
      ['古いものの日（10月1日）・古道具の日（10月10日）', '使われ続けてきた道具や機械に目を向ける日。古道具の展示や修理、使い方の紹介が行われる。']
    ], {
      before:['ユーレツェアは、物の時間に会いに行く国である。'],
      after:['ユーレツェアを訪れる人の中には、長く使ってきた物を持って来る人がいる。修理は故障への対応ではなく、再会の機会だと考えられているからである。直った物を受け取った旅人は、職人から「この子は丈夫ですからね」と声をかけられることが多い。','ユーレツェアならではの名物料理は、まだ広く知られていない。'],
      quote:'物を直しに来た人は、物と過ごした時間も一緒に持ち帰る。'
    })}
  ];

  var NEW = [{
    id:'travel', cat:'life', title:'旅行と観光', updated:UPDATED,
    lede:'テレポーターによって、世界のどこへでも短い時間で行けるようになった未来世界の旅。荷物を持たず、言葉も通貨も変わらない。それでも人は、わざわざ遠回りをして旅に出る。旅を支える技術と、その中で変わったもの、変わらなかったものをまとめる。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        { t:'p', text:'未来世界の旅は、移動にかかる時間がほとんどない。各国の首都には転送港があり、国際転送の多くはタスメニオのタハルンを経由して、世界中の都市と都市を結んでいる。' },
        { t:'p', text:'言葉は世界のほぼ全域で通じ、多くの国で円が使われている。本人確認は電子的な認証で済み、荷物はインベントリから受け取れる。旅の準備に必要なことの多くは、技術が引き受けている。' },
        { t:'info', items:[
          { label:'主な移動手段', value:'テレポーター（転送港）・鉄道・自動車・航空機・空路' },
          { label:'国際転送の中継', value:'タスメニオ（タハルン）' },
          { label:'言葉', value:'世界共通（訛りの違いのみ）' },
          { label:'荷物', value:'インベントリによる受け取り' },
          { label:'旅の記念日', value:'旅の日（9月27日）・遠くへ行く日（11月11日）' }
        ]},
        { t:'quote', text:'どこへでも行けるようになって、人は「どこへ行きたいか」を考えるようになった。' }
      ]},
      { id:'sec-move', title:'移動', blocks:[
        { t:'p', text:'国と国のあいだの移動は、転送港から転送港へのテレポートが基本である。各国の転送はタハルンの中継施設を経由するため、旅人の多くは、気づかないうちにタスメニオを通っている。' },
        { t:'p', text:'テレポーターは建設と維持に莫大な費用がかかるため、どこにでもあるわけではない。首都から地方へ向かう旅では、鉄道や自動車、航空機が今も使われている。フーモラ・スカイピルでは自動航行の空路ネットワークが、ラリアフルスでは徒歩が、旅の足になる。' },
        { t:'p', text:'転送のあとに頭痛やめまいを感じる「テレポート酔い」は、今も完全にはなくなっていない。転送港では対策薬が売られており、旅慣れた人は自分に合った薬を持ち歩いている。' }
      ]},
      { id:'sec-luggage', title:'手ぶらの旅', blocks:[
        { t:'p', text:'インベントリを使えば、自宅の保管庫に置いた物を、旅先の転送装置から呼び出すことができる。着替えも仕事道具も、必要になったときに取り出せばよいため、大きな荷物を持って旅をする人は少ない。' },
        { t:'p', text:'ただし、インベントリは生き物を転送できず、登録していない物は呼び出せない。旅先で買った物を保管庫へ送り、帰ってから受け取るという使い方も一般的である。' }
      ]},
      { id:'sec-words', title:'言葉と通貨', blocks:[
        { t:'p', text:'未来世界の言葉は日本語をもとにしており、国が違っても意味は通じる。違うのは話し方である。ヲンヘードでは「おきやすに」と言って食事を始め、チリルド・アイルツアでは「急がんでもええろ」と声をかけられる。訛りを聞き分けることは、旅の楽しみの一つになっている。' },
        { t:'p', text:'通貨は多くの国で円が使われている。両替の手間はほとんどなく、支払いは電子的な認証や指輪型の補助デバイスで済むことが多い。' }
      ]},
      { id:'sec-entry', title:'入国と本人確認', blocks:[
        { t:'p', text:'入国の手続きは、ニューロシンクや携帯型情報端末による電子的な本人認証で行われる。電子的な認証を使わない人や使えない場面のために、従来型の身分証も残されている。' },
        { t:'table', headers:['国・地域','旅行者の扱い'], rows:[
          ['セルトシティ','現実の都市への立ち入りは、研究者や関係者に限られる。一般の人が訪れるのは、仮想都市のサイバーセルトシティである。'],
          ['ガルヒューラ','観光客を迎える制度がない。国外の人がこの国を訪れることはほとんどない。'],
          ['マイモック','霧による危険があり、観光の対象ではない。'],
          ['ニポラン（大阪）','関西変異災害の封鎖区は、観光で立ち入ることはできない。']
        ]},
        { t:'p', text:'物理的な入国とは別に、情報環境へのアクセスはAccess Levelで管理されている。旅先で使える情報サービスの範囲も、この制度に従う。' }
      ]},
      { id:'sec-weather', title:'天気の心配が少ない旅', blocks:[
        { t:'p', text:'気象安定システムによって、多くの国の気候は安定している。旅の予定が大雨や嵐で崩れることは少ない。' },
        { t:'p', text:'その一方で、ガルヒューラとマイモックは気候が安定化されておらず、チリルド・アイルツアでは、建国以来続いた降雪が止まるという異変が起きている。天気が読めない土地は、それだけで特別な旅先になった。' }
      ]},
      { id:'sec-virtual', title:'行かずに行く旅', blocks:[
        { t:'p', text:'現地へ行かずに旅をする方法もある。Veloには360度映像や立体映像、ニューロシンク対応の旅の映像が数多く投稿されており、その場にいるような感覚で各地の景色を楽しめる。' },
        { t:'p', text:'フルダイブの体験型作品やゲームでは、海底のような、現実には行けない場所を歩くこともできる。ただし、フルダイブにはニューロシンクと対応機器が必要であり、誰もが使えるわけではない。' },
        { t:'p', text:'現実の都市に入れないセルトシティは、多くの人にとって「行かずに行く」都市そのものである。' }
      ]},
      { id:'sec-slow', title:'移動を楽しむ旅', blocks:[
        { t:'p', text:'どこへでもすぐに行けるようになった結果、移動そのものを楽しむ旅が、かえって贅沢なものになった。あえて鉄道を乗り継ぐ旅、キューマの蒸気鉄道に揺られる旅、フーモラの空路をゆっくり巡る旅などがその例である。' },
        { t:'p', text:'転送では、出発地と目的地のあいだにある景色を見ることがない。窓の外を流れていく景色を見たくて、何日もかけて移動する人もいる。' },
        { t:'quote', text:'転送は、目的地へ連れて行ってくれる。けれど、旅には連れて行ってくれない。' }
      ]},
      { id:'sec-life', title:'長い人生と旅', blocks:[
        { t:'p', text:'平均寿命が約200年の世界では、同じ場所を何十年も間を空けて訪れることができる。若いころに見た景色を、百年後にもう一度見に行く人もいる。Lumoには数十年前の旅の写真が残っており、同じ場所で撮り直した写真と並べて投稿することも楽しまれている。' },
        { t:'p', text:'景色が変わったのか、自分が変わったのか。長く生きる人々にとって、旅は時間を確かめる方法でもある。' }
      ]},
      { id:'sec-guide', title:'国ごとの観光', blocks:[
        { t:'p', text:'各国の名所や名物は、それぞれの国家の記事の「観光と名物」にまとめている。' },
        { t:'table', headers:['旅の目的','向いている国'], rows:[
          ['景色','チリルド・アイルツア、フーモラ・スカイピル、タスメニオ'],
          ['食べ歩き','ヲンヘード'],
          ['芸術','オルガロン'],
          ['歴史の体験','キューマ'],
          ['生き物の観察','ベルネア'],
          ['森で過ごす','ラリアフルス'],
          ['娯楽と祭り','サンルド'],
          ['物を直す','ユーレツェア'],
          ['猫','ヒューバート']
        ]}
      ]}
    ],
    related:['transportation','teleporter','inventory','tasumenio','language','identity-and-address','access-level','weather-control','world-climate','future-games','velo','lumo','cyber-sertcity','captain-of-the-sea']
  }];

  NEW.forEach(function(a){ if(!ARTICLES.some(function(x){return x.id===a.id;})) ARTICLES.push(a); });
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  var REL = ['belnea','chiriludo-ailtsua','fumora-skypill','garhyura','hubert','kyuma','larliafrus','maimok','niporan','orgaron','sanrudo','sertcity','tasumenio','wonhead','yuretsuea','transportation','teleporter'];
  REL.forEach(function(id){ PATCH.push({ id:id, op:'related', add:['travel'] }); });
  PATCH.forEach(function(p){
    var a = art(p.id); if(!a){ console.warn('patch: no article', p.id); return; }
    if(p.op==='addSection'){
      var idx=-1; (a.sections||[]).forEach(function(x,i){ if(x.id===p.after) idx=i; });
      if(idx<0) console.warn('patch: no anchor', p.id, p.after);
      if((a.sections||[]).some(function(x){return x.id===p.section.id;})) return;
      a.sections.splice(idx>=0?idx+1:a.sections.length, 0, p.section); a.updated = UPDATED;
    } else if(p.op==='related'){
      a.related = a.related || [];
      p.add.forEach(function(r){ if(a.related.indexOf(r)<0 && r!==a.id) a.related.push(r); });
    }
  });
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.26（4）
   各国の名物料理（料理集・collection:['recipe']）と、観光の節・食文化への反映。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.26';
  function R(id, title, nation, lede, secs, related, quote){
    var sections = secs.map(function(s){
      return { id:s[0], title:s[1], blocks:s[2].map(function(t){ return (typeof t==='string') ? { t:'p', text:t } : t; }) };
    });
    if(quote){ sections[sections.length-1].blocks.push({ t:'quote', text:quote }); }
    return { id:id, cat:'culture', collection:['recipe'], title:title, updated:UPDATED, lede:lede, sections:sections, related:related };
  }
  var NEW = [
  R('belnea-dome-mori','ベルネアドーム盛り','ベルネア',
    'ベルネアの六つの環境ドームを、一枚の皿に並べた料理。ドームごとの植物と培養肉を小さな器に分けて盛り、ひと皿で六つの生態系を食べ比べる。',
    [['sec-overview','概要',['ベルネアドーム盛りは、ベルネアを代表する名物料理である。セントラル、テンペレート、トロピカル、デザート、アークティック、オーシャンの六つのドームをかたどった小さな器に、それぞれの環境で育った食材を盛りつける。',
       { t:'info', items:[{label:'国',value:'ベルネア'},{label:'分類',value:'盛り合わせ料理'},{label:'主な食材',value:'各ドームの植物・培養肉・培養魚肉・海藻'},{label:'特徴',value:'六つの生態系の食べ比べ'}]}]],
     ['sec-ingredients','食材',[
       { t:'table', headers:['器','食材の例'], rows:[
         ['セントラル','人工森林で育つきのこや木の実'],
         ['テンペレート','草原の野草と、穏やかな味の培養肉'],
         ['トロピカル','香りの強い果実と、熱帯の葉で包んだ料理'],
         ['デザート','乾燥に強い多肉の植物。水分を閉じ込めた独特の食感'],
         ['アークティック','寒冷地の木の実や、冷たく締めた培養肉'],
         ['オーシャン','海藻と培養魚肉。器の底がわずかに光るように作られることもある']
       ]},
       'ベルネアでは生物を殺して食べる文化が一般的ではないため、肉や魚はすべて培養によるものである。植物も、ドームの生態系を乱さない範囲で育てられたものだけが使われる。']],
     ['sec-eating','食べ方',['決まった順番はないが、ベルネアの人々は、一つ食べるごとに味や香りの違いを言葉にしながら食べることが多い。ベルネア流の「観察」は、食卓でも続いている。','子どもたちは、どの器がどのドームの味かを当てる遊びをする。最初に生命へ触れる場所がテンペレートドームであるように、最初に覚える味もテンペレートの器であることが多い。']],
     ['sec-culture','食文化として',['ベルネアドーム盛りは、世界中の環境を一つの国に再現したベルネアそのものを、ひと皿に縮めた料理である。観光客にとっては、六つのドームを巡る前の予習であり、巡った後の答え合わせにもなっている。']]],
    ['belnea','taiki-mochi','travel'],
    'なんて素晴らしい生命なんだ。'),
  R('taiki-mochi','待機餅','ベルネア',
    '出されてから時間がたつにつれて、色と食感が少しずつ変わっていく餅。食べる人は、好みの状態になるまで待ち、その変化を見届けてから食べる。ベルネアの「待つ」文化を象徴する菓子。',
    [['sec-overview','概要',['待機餅は、ベルネアで親しまれている餅菓子である。生地に練り込まれたドームの植物の色素が空気に触れて変化し、出されたときの淡い色が、時間とともに深い色へ移り変わっていく。','色が変わるにつれて、食感もやわらかいものから、もっちりとしたものへ変わる。どの段階で食べるかは、食べる人が決める。',
       { t:'info', items:[{label:'国',value:'ベルネア'},{label:'分類',value:'餅菓子'},{label:'特徴',value:'時間とともに色と食感が変わる'},{label:'食べごろ',value:'食べる人が決める'}]}]],
     ['sec-taste','味・香り・食感',['出されてすぐは、ほのかな甘みと青い草の香りがある。時間がたつと甘みが深まり、香りは果実に近いものへ変わっていく。食べごろを過ぎると、少し硬くなる。']],
     ['sec-eating','食べ方',['ベルネアの子どもたちは、幼いころから「見る・待つ・比較する・記録する・変化を読む」ことを教わる。待機餅は、その最初の練習でもある。家族で同じ餅を前にして、それぞれが自分の食べごろを選び、なぜそこで食べたのかを話し合う。','急いで食べる人を、ベルネアの人々は責めない。ただ、「もう少し待つと、もっと面白いのに」と言う。']],
     ['sec-culture','食文化として',['すぐに手に入ることが当たり前になった未来世界で、待機餅は、待つことでしか得られない味があることを教えてくれる。']]],
    ['belnea','belnea-dome-mori'],
    '待つあいだにも、餅は生きているように変わっていく。'),
  R('hayameshi-plate','早飯プレート','ヒューバート',
    'ヒューバートの研究者たちが、短い時間で食事を済ませるために生まれた一皿。必要な栄養を過不足なく整え、食べやすさまで計算されている。合理性を重んじるヒューバートらしい名物。',
    [['sec-overview','概要',['早飯プレートは、ハーネンス中央都市の食堂で最もよく注文される料理である。研究と生活の距離が近いヒューバートでは、昼食を短く済ませて研究へ戻る人が多く、その要望に応えるために形が整えられていった。',
       { t:'info', items:[{label:'国',value:'ヒューバート'},{label:'分類',value:'定食・ワンプレート'},{label:'特徴',value:'栄養と食べやすさの最適化'},{label:'主な客',value:'研究者・技術者'}]}]],
     ['sec-design','設計',['プレートの上の料理は、すべてひと口か、ふた口で食べられる大きさに切りそろえられている。栄養の配分は利用者の体調や仕事量に合わせて調整でき、同じ早飯プレートでも、人によって中身が少しずつ違う。','完全栄養食を土台にしながらも、味や食感には変化がつけられている。毎日食べても飽きないことも、効率の一部と考えられているためである。']],
     ['sec-culture','食文化として',['ヒューバートの人々は、食事を手早く済ませることを恥ずかしいとは考えない。「それは非効率ですね」と言われないための料理、と冗談めかして呼ばれることもある。','一方で、早飯プレートを猫のいる食堂で食べると、なぜか食べ終わるのが遅くなると言われている。合理的な国にも、合理的に説明できない時間がある。']]],
    ['hubert','hubert-cat-sweets'],
    'この方法の成功率が高いです。'),
  R('hubert-cat-sweets','肉球パンと猫のお菓子','ヒューバート',
    'ヒューバートの猫文化から生まれた菓子の総称。肉球の形をした肉球パンと肉球クッキー、猫のひげのように細長い猫のひげガムがよく知られている。猫カフェや猫の記念日に欠かせない。',
    [['sec-overview','概要',['ハーネンス家が猫を再誕させて以来、ヒューバートでは猫が暮らしの中心にある。その文化は食べ物にも広がり、猫をかたどった菓子がいくつも生まれた。',
       { t:'info', items:[{label:'国',value:'ヒューバート'},{label:'分類',value:'菓子・パン'},{label:'主な品',value:'肉球パン・肉球クッキー・猫のひげガム'},{label:'売られる場所',value:'猫カフェ・猫専門施設・猫の記念日の催し'}]}]],
     ['sec-items','主な品',[
       { t:'table', headers:['名前','特徴'], rows:[
         ['肉球パン','肉球の形をしたやわらかいパン。肉球の部分だけが薄い桃色で、ほんのり甘い。猫カフェの定番。'],
         ['肉球クッキー','肉球の形に焼いたクッキー。猫の日や猫祭りには、模様の違う限定品が出る。'],
         ['猫のひげガム','猫のひげのように細く長いガム。一本ずつ引き抜いて食べる。口の中で、ひげが一本ずつ溶けていくような食感がある。']
       ]}]],
     ['sec-cats','猫のために',['これらの菓子は人間のためのものである。猫には、猫の体に合わせて作られた、同じ形の専用品が用意されている。猫と同じ形のものを並んで食べることが、ヒューバートの猫好きのささやかな楽しみになっている。']],
     ['sec-culture','食文化として',['猫の日（2月22日）、猫の再誕の日（9月22日）、猫祭り（11月11日）には、街中の店に肉球の形が並ぶ。ヒューバートを訪れた観光客が最もよく買って帰る土産物も、肉球クッキーである。']]],
    ['hubert','cat-culture','hayameshi-plate']),
  R('gear-cookie','歯車クッキー','ユーレツェア',
    '歯車の形をした二枚一組のクッキー。二枚の歯がきちんと噛み合うように焼かれており、噛み合わせの精度そのものが職人の腕の見せどころになっている。',
    [['sec-overview','概要',['歯車クッキーは、ユーレツェアの時計工房街から広まった焼き菓子である。歯の数や大きさの違う二枚が一組になっており、並べると歯がぴたりと噛み合う。',
       { t:'info', items:[{label:'国',value:'ユーレツェア'},{label:'分類',value:'焼き菓子'},{label:'特徴',value:'二枚一組で噛み合う'},{label:'由来',value:'時計職人の工房街'}]}]],
     ['sec-make','作り方',['生地は焼くと縮むため、焼き上がりで歯が噛み合うように、型の段階で縮み方を計算しておく必要がある。これは時計職人が微細な誤差を調整する考え方と同じである。焼き上がった二枚が噛み合わなければ、売り物にはならない。']],
     ['sec-custom','贈り物として',['歯車クッキーは、二枚のうち一枚を自分で、もう一枚を大切な人に渡して食べるものとされる。一緒に時間を過ごす相手への贈り物として、古いものの日や古道具の日によく買われる。']],
     ['sec-culture','食文化として',['ユーレツェアでは、物は共に時間を過ごす存在である。食べればなくなってしまう菓子にまで「噛み合うこと」を求めるところに、この国の人々の物への向き合い方が表れている。']]],
    ['yuretsuea','touro-nabe'],
    'どちらか一枚だけでは、歯車は回らない。'),
  R('touro-nabe','灯籠鍋','ユーレツェア',
    '灯籠の形をした鍋で、長い時間をかけて煮込む鍋料理。鍋の中に灯りがともり、煮えていく様子が外から透けて見える。鍋は家ごとに代々受け継がれ、名前を付けて大切に使われている。',
    [['sec-overview','概要',['灯籠鍋は、ユーレツェアの家庭や古い食堂で受け継がれてきた鍋料理である。鍋そのものが灯籠の形をしており、薄い金属の窓越しに、中の灯りと煮えていく具材が見える。',
       '名前に灯籠とあるが、火は使わない。昔は灯籠の火で温めていたとも伝わるが、現在は鍋の底に組み込まれた加熱装置と灯りで、ゆっくりと煮込む。',
       { t:'info', items:[{label:'国',value:'ユーレツェア'},{label:'分類',value:'鍋料理'},{label:'特徴',value:'灯籠の形の鍋・中の灯りが透けて見える'},{label:'鍋',value:'家ごとに代々受け継がれる'}]}]],
     ['sec-pot','鍋',['灯籠鍋の鍋は、職人が一つずつ作る。精密な加工で窓や継ぎ目が作られ、何十年、何百年と使えるように設計されている。多くの家では鍋に名前を付け、傷やへこみも鍋の歴史として残している。','鍋が傷めば、修理工房へ持ち込まれる。ユーレツェアでは、灯籠鍋を直してもらいに来る旅人も珍しくない。']],
     ['sec-taste','味・香り・食感',['具材は根菜や培養肉が中心で、長時間かけて煮込むため、どれもやわらかく、汁には深いうまみが出る。家ごとに味が違い、「うちの鍋の味」という言い方がそのまま家の味を指す。']],
     ['sec-culture','食文化として',['夜、灯籠鍋の灯りを囲んで食卓につく時間は、ユーレツェアの人々にとって一日の終わりの合図である。灯りが鍋の中で揺れて見えるのは、鍋が長く使われてきた証だと言われている。']]],
    ['yuretsuea','gear-cookie','fire-alternatives'],
    'この子は丈夫ですからね。'),
  R('hachito-arare','八都あられ','ニポラン',
    'ニポランの八つの大都市ごとに味の違うあられの詰め合わせ。米菓の日（11月11日）には、八つの味をそろえて食べ比べるのが定番になっている。',
    [['sec-overview','概要',['八都あられは、東京、大阪、札幌、仙台、名古屋、京都、広島、福岡の八つの大都市の味を一つの箱に詰めた米菓である。ニポランで最も広く知られた土産物の一つでもある。',
       { t:'info', items:[{label:'国',value:'ニポラン'},{label:'分類',value:'米菓'},{label:'構成',value:'八つの都市の味'},{label:'記念日',value:'米菓の日（11月11日）'}]}]],
     ['sec-flavors','八つの味',[
       { t:'table', headers:['都市','味'], rows:[
         ['東京','醤油。最も基本の味とされる。'],['大阪','甘辛いソース。'],['札幌','昆布とバター。'],['仙台','枝豆の甘み。'],
         ['名古屋','濃い味噌。'],['京都','抹茶と白味噌。'],['広島','牡蠣のだし。'],['福岡','辛子の効いた魚卵の風味。']
       ]},
       '味は都市ごとに旧時代から受け継がれたものとされるが、実際にどこまで旧時代の味と同じなのかは分かっていない。']],
     ['sec-osaka','大阪の味',['大阪は関西変異災害によって封鎖区となった。それでも八都あられから大阪の味が外されたことはない。現在の大阪の味は、災害で街を離れた人々とその家族が、東京や他の都市で作り続けている。','箱の中の大阪のあられは、失われた都市が今もニポランの一部であることを示すものとして、特別な思いを込めて食べられている。']],
     ['sec-culture','食文化として',['八都あられは、八つの都市を一つの国としてまとめるニポランの姿を、そのまま小さな箱に詰めた菓子である。お茶の日（10月10日）には、龍茶と一緒に出されることも多い。']]],
    ['niporan','tatsu-cha','kansai-disaster'],
    '一つの箱に、八つの街がある。'),
  R('tatsu-cha','龍茶','ニポラン',
    '人生の節目に飲まれる、ニポランのお茶。一杯目は淡く明るく、二杯目は濃く深い色に出る。二杯を続けて飲むことで「二つにして一つ」となる、龍教の考え方に結びついたお茶である。',
    [['sec-overview','概要',['龍茶は、ニポランで誕生、成人、婚礼、そして死という人生の節目に飲まれるお茶である。同じ茶葉から淹れても、一杯目は光のように淡く、二杯目は闇のように濃い色に出るよう、茶葉が配合されている。',
       { t:'info', items:[{label:'国',value:'ニポラン'},{label:'分類',value:'茶'},{label:'飲む場面',value:'人生の節目'},{label:'特徴',value:'淡い一杯目と、濃い二杯目'}]}]],
     ['sec-meaning','二杯で一つ',['龍の書には、龍は光であり闇であり、「二つにして一つ」であると記されている。龍茶の二杯は、この言葉になぞらえたものとされる。一杯目だけ、二杯目だけで終えるのは、縁起がよくないと考える人もいる。','龍教には明確な教祖や宗教組織がないため、飲み方の作法は家ごとに少しずつ違う。それでも「二杯で一つ」という点だけは、ほとんどの家で共通している。']],
     ['sec-taste','味・香り',['一杯目はすっきりとした香りで、ほとんど苦みがない。二杯目は深いうまみと苦みがあり、香りも重くなる。続けて飲むと、二杯目の苦みのあとに、一杯目の香りがもう一度戻ってくるように感じられる。']],
     ['sec-culture','食文化として',['葬儀の席では、龍茶は故人を送る茶でもある。龍教では、死は終わりではなく帰郷とされる。悲しみの席で淡い一杯目と濃い二杯目を飲み終えたとき、人々は故人が還る場所を思う。','日常でも飲まれるが、龍茶を淹れると、人はふと何かの節目を思い出すという。']]],
    ['niporan','dragon-religion','dragon-book','hachito-arare'],
    '死は終わりにあらず。それは帰郷なり。'),
  R('kasetsu-soup','仮説スープ','キューマ',
    '古い記録をもとに、過去の料理を再現したスープ。研究が進んで新しい資料が見つかるたびにレシピが改訂され、店では「第何版」かが表示される。キューマの古代料理店の看板料理。',
    [['sec-overview','概要',['仮説スープは、キューマの古代料理店で出される復元料理である。過去の時代の記録に残る断片的な手がかりから、材料や作り方を推定して作られる。名前のとおり、このスープは「たぶんこうだった」という仮説そのものである。',
       { t:'info', items:[{label:'国',value:'キューマ'},{label:'分類',value:'復元料理・スープ'},{label:'特徴',value:'研究が進むとレシピが変わる'},{label:'表示',value:'版数（第何版か）'}]}]],
     ['sec-version','版の改訂',['新しい資料が発掘されたり、記録の読み方が変わったりすると、仮説スープのレシピも改訂される。店のメニューには「第十二版」のように版数が書かれ、前の版との違いも説明されている。','古い版のほうが美味しかったと言う客もいる。キューマの人々はそれを否定しない。ただ、「美味しいかどうかと、正しいかどうかは別の問題だね」と答える。']],
     ['sec-eating','食べ方',['仮説スープを飲んだ客は、店に感想を残していく。味の感想だけでなく、「この香りは記録のあの記述と合わない」といった指摘が届くこともあり、それが次の版のきっかけになることもある。疑問の日（10月4日）には、版ごとの飲み比べが行われる。']],
     ['sec-culture','食文化として',['キューマにとって、歴史は暗記するものではなく、体験し検証するものである。仮説スープは、その考え方をいちばん身近な形で味わえる料理である。']]],
    ['kyuma','joki-kamameshi','modern-excavation'],
    'なぜだろう？　試してみよう。'),
  R('joki-kamameshi','蒸気釜飯','キューマ',
    'キューマの体験区で、蒸気機関時代を再現した厨房で炊き上げる釜飯。蒸気鉄道の旅とともに楽しまれ、駅ごとに具の違う釜飯が売られている。',
    [['sec-overview','概要',['蒸気釜飯は、キューマの体験区に再現された蒸気機関時代の厨房で作られる釜飯である。釜は当時の様式を復元したもので、蒸気の力で米を炊き上げる。','当時の蒸気は燃料を燃やして作られていたが、現在の体験区では、燃焼を使わない加熱で蒸気を作っている。音も湯気も当時のままだが、火だけがない。',
       { t:'info', items:[{label:'国',value:'キューマ'},{label:'分類',value:'釜飯'},{label:'作られる場所',value:'体験区の復元厨房'},{label:'楽しみ方',value:'蒸気鉄道の旅とともに'}]}]],
     ['sec-ekiben','駅ごとの釜飯',['体験区の蒸気鉄道の駅では、それぞれ具の違う蒸気釜飯が売られている。乗客は駅に着くたびに釜飯を買い、車窓を眺めながら食べる。全部の駅の釜飯をそろえる旅は、キューマを訪れる観光客の定番になっている。']],
     ['sec-taste','味・香り・食感',['蒸気で一気に炊き上げるため、米はふっくらと立ち、釜の底にはほどよいおこげができる。具材のうまみが米に染みこみ、ふたを開けた瞬間の湯気の香りが、何よりのごちそうとされる。']],
     ['sec-culture','食文化として',['キューマの人々にとって、蒸気鉄道も蒸気釜飯も、観光のための演出ではなく、日常の一部である。昼休みに体験区まで釜飯を買いに行く研究者も多い。']]],
    ['kyuma','kasetsu-soup','travel']),
  R('gosenfu-plate','五線譜プレート','オルガロン',
    '料理を五線譜のように並べた一皿。一つひとつの料理が音符にあたり、同じ「曲」を演奏者がその場で奏でる。味わうことと聴くことを一つにした、オルガロンの料理。',
    [['sec-overview','概要',['五線譜プレートは、オルガロンの生演奏付きの食事から生まれた料理である。細長い皿に五本の線が引かれ、その上に小さな料理が音符のように並べられている。料理の並びは一つの曲になっており、食べる順に、演奏者が同じ曲を奏でる。',
       { t:'info', items:[{label:'国',value:'オルガロン'},{label:'分類',value:'コース・盛り合わせ'},{label:'特徴',value:'料理の並びが一つの曲になっている'},{label:'提供',value:'生演奏付き'}]}]],
     ['sec-score','譜面としての料理',['高い音にあたる料理は軽く酸味のあるものが、低い音にあたる料理は重くうまみの強いものが置かれることが多い。長い音符は大きな一品、休符は口を休める水や小さな果実で表される。','どの曲を料理にするかは料理人と演奏者が決める。ピアノの街ではゆっくりとした曲が、フォルテの街では激しい曲が選ばれやすい。']],
     ['sec-eating','食べ方',['五線譜プレートは、左から右へ、譜面を読むように食べる。演奏に合わせて食べ進めると、最後のひと口と最後の音が重なるように作られている。急いで食べると、曲が置いていかれる。']],
     ['sec-culture','食文化として',['オルガロンでは、料理は味だけでなく、色彩や香り、空間や会話まで含めた表現である。五線譜プレートは、その考え方を最もはっきりと形にした料理である。']]],
    ['orgaron','iro-course'],
    '美しい。この皿には、音がある。'),
  R('iro-course','色のコース','オルガロン',
    '一品ごとに一つの色だけで作られるコース料理。白から始まり、色が移り変わっていく。その順番と色の選び方に、料理人の表現が込められている。',
    [['sec-overview','概要',['色のコースは、オルガロンのメゾピアノを中心に広まったコース料理である。それぞれの皿が一つの色だけで作られ、食材も器もその色にそろえられる。',
       { t:'info', items:[{label:'国',value:'オルガロン'},{label:'分類',value:'コース料理'},{label:'特徴',value:'一皿一色'},{label:'中心地',value:'メゾピアノ（視覚芸術の都市）'}]}]],
     ['sec-order','色の順番',['多くの店では白から始まり、淡い色から濃い色へ進んで、最後に再び白へ戻る。どの色を何皿目に置くか、どの色を使わないかは料理人が決める。客は、食べ終えたあとに「今日のコースは何を表していたのか」を考える。','オルガロンの人々は、料理を「色がある」「濁っている」という言葉で評価する。色のコースでは、その言葉がそのまま料理の感想になる。']],
     ['sec-taste','味',['同じ色の食材でも、味はまったく違うことがある。白い皿に甘いものと苦いものが並ぶこともあり、見た目の静けさと味の驚きの差を楽しむ料理でもある。']],
     ['sec-culture','食文化として',['色のコースは、芸術を日常の延長として扱うオルガロンらしい料理である。バルベルク（10月24日）の時期には、各店が特別な色の順番を競い合う。']]],
    ['orgaron','gosenfu-plate']),
  R('ougon-tsutsumi','黄金包み','サンルド',
    '人工黄金の箔で包んだ点心。黄金区域のヴォルグレンを代表する料理で、ひと口ごとに金色が光る。白金区域には、白い生地で包んだ対の料理もある。',
    [['sec-overview','概要',['黄金包みは、サンルドの黄金区域で生まれた点心である。具を包んだ生地の外側を、食べられる人工黄金の箔で覆っている。サンルドでは人工黄金が広く流通しているため、金色の料理は特別なものではなく、日常の華やかさの一部になっている。',
       { t:'info', items:[{label:'国',value:'サンルド'},{label:'分類',value:'点心'},{label:'特徴',value:'人工黄金の箔で包む'},{label:'中心地',value:'ヴォルグレン（黄金区域）'}]}]],
     ['sec-pair','白金包み',['白金区域のクレディアには、白い生地を何層にも重ねて包んだ「白金包み」がある。黄金包みが派手で濃い味であるのに対し、白金包みは静かで繊細な味である。','双輝祭（12月31日）には、黄金包みと白金包みを一つずつ並べて出すのが習わしとなっている。どちらから食べるかで、その人が黄金派か白金派かが分かると言われる。']],
     ['sec-taste','味',['中の具は肉や海産物、甘いものまでさまざまである。箔そのものには味がほとんどなく、口に入れるとすぐに溶ける。見た目の豪華さと、すっと消える口当たりの差が楽しまれている。']],
     ['sec-culture','食文化として',['黄金は人類が価値を与え続けてきたものの象徴である。黄金包みは、その価値を「食べて消してしまう」料理でもある。価値とは流し続けるものだ、というサンルドの考え方が、皿の上にも表れている。']]],
    ['sanrudo','kake-manju','grk'],
    'それ、本当に信用していいのかい？'),
  R('kake-manju','賭けまんじゅう','サンルド',
    'いくつかのまんじゅうのうち、一つだけに小さな金貨が入っている菓子。金貨を引き当てた人は、その日の幸運を手にしたとされる。GRKのカジノや双輝祭で人気がある。',
    [['sec-overview','概要',['賭けまんじゅうは、サンルドの黄金区域で親しまれている菓子である。同じ見た目のまんじゅうが何個か並べられ、そのうち一つにだけ、薄い包みに入った小さな金貨が入っている。どれに金貨が入っているかは、食べてみるまで分からない。',
       { t:'info', items:[{label:'国',value:'サンルド'},{label:'分類',value:'菓子'},{label:'特徴',value:'一つだけ金貨入り'},{label:'人気の場所',value:'GRKのカジノ・双輝祭'}]}]],
     ['sec-coin','金貨',['中に入っているのは人工黄金の小さな金貨で、口に入れる前に気づけるよう包みに収められている。金貨を引き当てた人は、それを持ち帰ってお守りにする。','金貨はただの人工黄金であり、金額としての価値はほとんどない。それでも、引き当てたという事実に価値がある、とサンルドの人々は考える。']],
     ['sec-eating','食べ方',['家族や友人で一つずつ取り、同時に割るのが定番の遊び方である。GRKのカジノでは、ゲームの合間の菓子として配られることもある。誰が金貨を引くかで、その夜の運を占う人もいる。']],
     ['sec-culture','食文化として',['GRKは「幸運もまた価値の一つである」という理念を掲げている。賭けまんじゅうは、その理念をいちばん小さく、いちばん甘く表した菓子である。']]],
    ['sanrudo','ougon-tsutsumi','grk'],
    '価値があるかは、君次第だ。'),
  R('teikoku-box','定刻ボックス','セルトシティ',
    'セルトシティのオフエリアで、アンドロイドが決まった時刻に研究者へ届ける食事の箱。中身は研究者ごとに調整されている。外の人が食べる機会はほとんどないため、「見たことはあるが食べたことはない」料理として知られている。',
    [['sec-overview','概要',['定刻ボックスは、セルトシティの研究者に福利厚生として提供される食事である。決まった時刻になると、アンドロイドが研究棟やオフエリアへ箱を届ける。',
       { t:'info', items:[{label:'国',value:'セルトシティ'},{label:'分類',value:'弁当・食事箱'},{label:'提供',value:'アンドロイドによる定刻の配達'},{label:'対象',value:'セルトシティの研究者・関係者'}]}]],
     ['sec-content','中身',['箱の中身は、研究者の仕事量や体調に合わせて調整されている。同じ日の同じ時刻に届く箱でも、隣の研究者とは中身が違うことが多い。','セルトシティの内部では天気も季節も変わらないため、定刻ボックスには季節の食材が意識して入れられる。研究者にとっては、箱の中身が季節を知らせる数少ない手がかりになっている。']],
     ['sec-outside','外から見た定刻ボックス',['現実のセルトシティに入れる人は限られているため、外の人々が定刻ボックスを口にすることはほとんどない。それでも、サイバーセルトシティでその見た目は広く知られており、似せて作った「定刻ボックス風」の弁当が他国で売られることもある。']],
     ['sec-culture','食文化として',['決まった時刻に、決まった形で、必要なものが届く。定刻ボックスは、無駄を省き安全を優先するセルトシティそのものである。それでも研究者たちは、箱を開けるときに少しだけ中身を予想して楽しむという。']]],
    ['sertcity','cyber-sertcity'],
    '確認しました。今日は、季節の味です。'),
  R('kumowata','雲綿','フーモラ・スカイピル',
    '雲のようにふわりとした綿菓子。口に入れるとすぐに溶ける。空景ドリンクと一緒に売られ、フーモラ・スカイピルを訪れた観光客の定番になっている。',
    [['sec-overview','概要',['雲綿は、フーモラ・スカイピルのスカイラリスで生まれた菓子である。細い糖の糸を空気と一緒に巻き取り、雲のような形にまとめている。',
       { t:'info', items:[{label:'国',value:'フーモラ・スカイピル'},{label:'分類',value:'菓子'},{label:'特徴',value:'雲のように軽く、すぐに溶ける'},{label:'一緒に',value:'空景ドリンク'}]}]],
     ['sec-eating','食べ方',['雲綿は、空景ドリンクの上に浮かべて食べることが多い。ドリンクに触れたところから少しずつ溶け、色が混ざっていく様子は、空に雲が溶けていくように見える。外周展望リングで、本物の雲を見下ろしながら食べるのが定番である。']],
     ['sec-culture','食文化として',['フーモラには統一された文化がなく、雲綿も、世界中から来た人々がそれぞれの国の菓子をもとに作り変えていった結果だとされる。味も色も店ごとに違い、どれが本来の雲綿なのかは誰も気にしていない。まあ空だからね、とフーモラの人々は言う。']]],
    ['fumora-skypill','travel'],
    '雲は、食べられる。ただし、すぐに消える。'),
  R('himuro-zuke','氷室漬け','チリルド・アイルツア',
    'チリルド・アイルツアの家庭の地下氷保管庫で、魚や肉をじっくり寝かせた保存食。低い温度で長く置くことで、うまみが深まる。保管庫の大きさが豊かさの象徴とされる国の、家庭の味。',
    [['sec-overview','概要',['氷室漬けは、チリルドの多くの家庭にある地下氷保管庫で作られる。雪を加工した氷ブロックで囲まれた保管庫の中で、塩をした魚や培養肉を何か月も寝かせる。',
       { t:'info', items:[{label:'国',value:'チリルド・アイルツア'},{label:'分類',value:'保存食'},{label:'作る場所',value:'家庭の地下氷保管庫'},{label:'期間',value:'数か月から数年'}]}]],
     ['sec-taste','味・香り・食感',['長く寝かせた氷室漬けは、身が締まり、うまみが濃くなる。薄く切って、そのまま食べることが多い。年数を重ねたものほど味が深く、家によっては何年も前に漬けたものを、祝いの席のために取っておく。']],
     ['sec-eating','食べ方',['北海岸地域では、氷海漁で獲れた魚の氷室漬けが特に好まれる。寒い土地で働く人々は、ナントッカナッチャルノと並んで、氷室漬けを活力源にしてきた。']],
     ['sec-now','いまの氷室漬け',['チリルドの氷は、降り積もった雪を加工して作られる。建国以来続いた雪が止まったいま、人々は保管庫の氷がこの先も足りるのかを気にし始めている。それでも多くの家庭は、「そのうち何とかなるろ」と言いながら、いつもどおり氷室に漬けている。']]],
    ['chiriludo-ailtsua','nantokkanatcharuno'],
    '急がんでもええろ。氷室の中は、ゆっくりやから。'),
  R('susu-hoshiniku','煤干し肉','ガルヒューラ',
    'ガルヒューラの家々で、ボイラー室に吊るして煤と熱で干した肉。火の禁忌が通じないこの国では、ボイラーの火そのものが調理道具である。硬く、煤の匂いが強い。',
    [['sec-overview','概要',['煤干し肉は、ガルヒューラで最も広く食べられている保存食である。肉をボイラー室の天井近くに吊るし、ボイラーの熱と煙、煤で長い時間をかけて干し上げる。',
       { t:'info', items:[{label:'国',value:'ガルヒューラ'},{label:'分類',value:'保存食'},{label:'作る場所',value:'家庭や集落のボイラー室'},{label:'特徴',value:'本物の火の煙と煤で干す'}]}]],
     ['sec-fire','本物の火',['他国では、燻製の香りは火を使わない技術で再現される。ガルヒューラの煤干し肉は、本物の火の煙と煤で作られる、世界でもほとんど唯一の料理である。他国の人々にとって、それは禁忌そのものの味でもある。']],
     ['sec-taste','味・香り・食感',['煤干し肉は非常に硬く、噛み切るのに力がいる。表面は黒く、煤と煙の匂いが強い。味つけは塩だけのことが多い。美味しさのためというより、冬を越えるための食べ物である。']],
     ['sec-life','暮らしの中で',['ガルヒューラの部屋には生活感がほとんどない。その中で、ボイラー室に吊るされた肉だけが、そこに人が暮らしていることを示している。','この国には観光客がいないため、他国の人が煤干し肉を口にすることはほとんどない。']]],
    ['garhyura','fire-taboo','frostan-civilization'],
    '弱いやつは、冬を越えられない。')
  ];

  /* 観光の節への反映（テキスト差し替え） */
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function tour(id){ var a=art(id); if(!a) return null; return (a.sections||[]).filter(function(s){return s.id==='sec-tourism';})[0]; }
  function swap(id, oldText, newText){
    var s=tour(id); if(!s){ console.warn('food: no tourism', id); return; }
    var hit=false; s.blocks.forEach(function(b){ if(b.text===oldText){ b.text=newText; hit=true; } });
    if(!hit) console.warn('food: text not found', id);
  }
  function addP(id, text){ var s=tour(id); if(!s){ console.warn('food: no tourism', id); return; }
    var qi=-1; s.blocks.forEach(function(b,i){ if(b.t==='quote') qi=i; });
    if(qi>=0) s.blocks.splice(qi,0,{t:'p',text:text}); else s.blocks.push({t:'p',text:text}); }

  NEW.forEach(function(a){ if(!ARTICLES.some(function(x){return x.id===a.id;})) ARTICLES.push(a); });

  swap('belnea','食事は培養肉が中心で、生物を殺して食べる文化は一般的ではない。ベルネアならではの名物料理は、まだ広く知られていない。',
    '名物は、六つのドームの食材を小さな器に分けて盛るベルネアドーム盛りと、時間とともに色と食感が変わっていく待機餅である。どちらも、見て、待って、比べるというベルネアの観察の作法が、そのまま食べ方になっている。肉や魚はすべて培養によるもので、生物を殺して食べる文化は一般的ではない。');
  swap('hubert','ヒューバートならではの名物料理は、まだ広く知られていない。効率を重んじる国らしく、食事は手早く済ませる人が多いとも言われる。',
    '名物は、研究者が短い時間で食事を済ませるための早飯プレートと、猫文化から生まれた肉球パン、肉球クッキー、猫のひげガムである。観光客が最もよく買って帰る土産物は、肉球クッキーだと言われる。');
  swap('yuretsuea','ユーレツェアならではの名物料理は、まだ広く知られていない。',
    '名物は、二枚一組で歯がぴたりと噛み合う歯車クッキーと、代々受け継がれる灯籠の形の鍋で煮込む灯籠鍋である。灯籠鍋の鍋を修理工房へ持ち込む旅人もいる。');
  addP('niporan','名物は、八つの大都市の味を一つの箱に詰めた八都あられと、人生の節目に飲まれる龍茶である。八都あられには、封鎖区となった大阪の味も今も入っている。');
  addP('kyuma','名物は、古い記録から再現され、研究が進むたびに改訂される仮説スープと、体験区の蒸気鉄道の駅ごとに具が違う蒸気釜飯である。');
  addP('orgaron','名物は、料理を五線譜のように並べ、同じ曲を生演奏で奏でる五線譜プレートと、一皿ごとに一つの色だけで作る色のコースである。');
  addP('sanrudo','名物は、人工黄金の箔で包んだ黄金包みと、一つだけに小さな金貨が入った賭けまんじゅうである。双輝祭には、黄金包みと白金包みを並べて出すのが習わしになっている。');
  addP('sertcity','セルトシティの食事として知られるのは、アンドロイドが決まった時刻に研究者へ届ける定刻ボックスである。外の人が食べる機会はほとんどなく、「見たことはあるが食べたことはない」料理として有名になっている。');
  swap('fumora-skypill','名物は、塔型の構造とリング状の装飾を持つスカイラリスパフェと、空の色や都市の光を再現した空景ドリンクである。空景ドリンクは都市ごとに種類が違い、巡りながら飲み比べるのが定番になっている。',
    '名物は、塔型の構造とリング状の装飾を持つスカイラリスパフェと、空の色や都市の光を再現した空景ドリンク、そして雲のように軽い綿菓子の雲綿である。空景ドリンクは都市ごとに種類が違い、雲綿を浮かべて飲み比べるのが定番になっている。');
  swap('chiriludo-ailtsua','名物は、解凍した魚にニンニクの効いたアシマヤソースをかけるナントッカナッチャルノ。寒い土地で働く人々の活力源として親しまれてきた。',
    '名物は、解凍した魚にニンニクの効いたアシマヤソースをかけるナントッカナッチャルノと、家庭の地下氷保管庫で魚や肉を寝かせる氷室漬けである。どちらも寒い土地で働く人々の活力源として親しまれてきた。');
  addP('garhyura','この国で最も広く食べられているのは、ボイラー室に吊るして本物の火の煙と煤で干した煤干し肉である。他国の人々がそれを口にすることは、ほとんどない。');

  /* 関連項目 */
  var REL = { belnea:['belnea-dome-mori','taiki-mochi'], hubert:['hayameshi-plate','hubert-cat-sweets'], 'cat-culture':['hubert-cat-sweets'],
    yuretsuea:['gear-cookie','touro-nabe'], niporan:['hachito-arare','tatsu-cha'], kyuma:['kasetsu-soup','joki-kamameshi'],
    orgaron:['gosenfu-plate','iro-course'], sanrudo:['ougon-tsutsumi','kake-manju'], grk:['kake-manju'], sertcity:['teikoku-box'],
    'fumora-skypill':['kumowata'], 'chiriludo-ailtsua':['himuro-zuke'], garhyura:['susu-hoshiniku'], 'food-culture':['travel'] };
  Object.keys(REL).forEach(function(id){ var a=art(id); if(!a) { console.warn('food: no article', id); return; }
    a.related=a.related||[]; REL[id].forEach(function(r){ if(a.related.indexOf(r)<0) a.related.push(r); }); a.updated=UPDATED; });

  /* 食文化の郷土料理の表へ */
  var fc = art('food-culture');
  if(fc){ var s=(fc.sections||[]).filter(function(x){return x.id==='sec-regional';})[0];
    var tb = s && s.blocks.filter(function(b){return b.t==='table';})[0];
    if(tb){ [['ベルネアドーム盛り','ベルネア','六つのドームの食材を小さな器に分けて盛る。'],['待機餅','ベルネア','時間とともに色と食感が変わる餅。食べごろは自分で決める。'],
      ['早飯プレート','ヒューバート','研究者が短い時間で食べるための、栄養と食べやすさを整えた一皿。'],['肉球パン・肉球クッキー・猫のひげガム','ヒューバート','猫文化から生まれた菓子。'],
      ['歯車クッキー','ユーレツェア','二枚一組で歯が噛み合うクッキー。'],['灯籠鍋','ユーレツェア','代々受け継がれる灯籠の形の鍋で煮込む鍋料理。'],
      ['八都あられ','ニポラン','八つの大都市の味をそろえた米菓。'],['龍茶','ニポラン','人生の節目に飲む、淡い一杯目と濃い二杯目のお茶。'],
      ['仮説スープ','キューマ','古い記録から再現し、研究が進むと改訂される復元料理。'],['蒸気釜飯','キューマ','体験区の蒸気鉄道の駅で売られる釜飯。'],
      ['五線譜プレート','オルガロン','料理を譜面のように並べ、生演奏とともに食べる。'],['色のコース','オルガロン','一皿ごとに一つの色だけで作るコース料理。'],
      ['黄金包み','サンルド','人工黄金の箔で包んだ点心。'],['賭けまんじゅう','サンルド','一つだけに小さな金貨が入ったまんじゅう。'],
      ['定刻ボックス','セルトシティ','アンドロイドが定刻に届ける研究者向けの食事箱。'],['雲綿','フーモラ・スカイピル','雲のように軽く、すぐに溶ける綿菓子。'],
      ['氷室漬け','チリルド・アイルツア','家庭の地下氷保管庫で寝かせた魚や肉。'],['煤干し肉','ガルヒューラ','ボイラーの火の煙と煤で干した肉。本物の火を使う。']
    ].forEach(function(r){ if(!tb.rows.some(function(x){return x[0]===r[0];})) tb.rows.push(r); }); fc.updated=UPDATED; }
    else console.warn('food: no regional table'); }
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.26（5）
   火の禁忌の整合（禁忌が固まるまで・葬儀の火）と、スポーツ（新規記事）。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.26';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }

  /* ---- 火の禁忌：再始動後も燃焼に頼った時代があったこととの整合 ---- */
  var ft = art('fire-taboo');
  if(ft){
    if(!ft.sections.some(function(s){return s.id==='sec-settle';})){
      var i=-1; ft.sections.forEach(function(s,k){ if(s.id==='sec-warming') i=k; });
      ft.sections.splice(i>=0?i+1:ft.sections.length,0,{ id:'sec-settle', title:'禁忌が固まるまで', blocks:[
        { t:'p', text:'燃焼の記憶は、コールドスリープから目覚めた人々にも伝わっていた。しかし、目覚めたばかりの世界で、それはまだ禁忌ではなかった。生き延びること、文明を立て直すことが先だったからである。' },
        { t:'p', text:'スチームパンク時代から戦後復興期にかけて、人類は再び燃焼に頼った。蒸気機関や工業は大規模な燃焼に支えられて発展し、その結果、大気の悪化や自然環境への負荷が各地で問題になった。' },
        { t:'p', text:'人類は、一度世界を追い詰めたのと同じ道を、もう一度歩きかけていた。この反省から、統合暦820年の世界環境協定で、大規模な燃焼技術が規制された。燃焼を使わない加熱技術が広まり、日常から火が消えていくにつれて、「火は世界を壊す」という記憶は、避けるべき禁忌として固まっていった。' },
        { t:'table', headers:['時期','火の扱い'], rows:[
          ['再始動期','燃焼の記憶は伝わっていたが、暮らしの再建が優先された。'],
          ['スチームパンク時代〜戦後復興期','蒸気機関と工業が大規模な燃焼に支えられ、環境の悪化が問題になる。'],
          ['統合暦820年','世界環境協定。大規模な燃焼技術が規制される。'],
          ['その後','燃焼を使わない技術が日常へ広がり、火は禁忌として定着する。']
        ]},
        { t:'quote', text:'一度目は、知らなかった。二度目は、知っていたのに、繰り返しかけた。' }
      ]});
    }
    var ov=(ft.sections||[]).filter(function(s){return s.id==='sec-overview';})[0];
    if(ov){ ov.blocks.forEach(function(b){ if(b.t==='info'){ b.items.forEach(function(it){ if(it.label==='例外' && it.value.indexOf('葬儀')<0){ it.value = it.value + '／葬儀の火葬（専用施設で厳格に管理）'; } }); } }); }
    var lf=(ft.sections||[]).filter(function(s){return s.id==='sec-life';})[0];
    if(lf && !lf.blocks.some(function(b){return b.text && b.text.indexOf('火葬')>=0;})){
      lf.blocks.splice(1,0,{ t:'p', text:'例外として、葬儀の火葬は今も広く行われている。火を生きる者のためではなく、死者を送るためにだけ使うという考え方から、日常の火とは区別され、専用の施設で厳格に管理されている。詳しくは死と葬儀の項目を参照。' });
    }
    ft.related=ft.related||[]; ['world-environment-agreement','steam-punk-era','death-and-funeral'].forEach(function(r){ if(ft.related.indexOf(r)<0) ft.related.push(r); });
    ft.updated=UPDATED;
  }

  /* ---- スポーツ ---- */
  var NEW = [{
    id:'sports', cat:'life', title:'スポーツ', updated:UPDATED,
    lede:'身体を治すことも、作り替えることもできるようになった世界のスポーツ。生身の身体で競う部門、拡張した身体で競う部門、仮想空間で競う部門に分かれ、選手は何十年も現役を続ける。それでも人々は、勝ち負けの向こうに「人間とは何か」を見ようとしている。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        { t:'p', text:'未来世界でも、スポーツは最も広く親しまれている娯楽の一つである。近代文明の記録から受け継がれた競技の多くが今も行われており、そこに未来世界ならではの競技や部門が加わっている。' },
        { t:'p', text:'未来世界のスポーツの特徴は、身体の扱いにある。再生医療、人工臓器、ナノマシン、身体改造、アニマルボディ技術によって、人は身体を治すことも、変えることもできる。そのため、どの身体で競うのかを決めることが、競技のいちばんの前提になっている。' },
        { t:'info', items:[
          { label:'世界の記念日', value:'世界スポーツの日（10月12日・統合暦1526年制定）' },
          { label:'主な部門', value:'生身の部・拡張の部・仮想の部' },
          { label:'選手生命', value:'数十年に及ぶことが多い' },
          { label:'観戦', value:'競技場・Velo・立体映像・フルダイブ' }
        ]},
        { t:'quote', text:'何を測っているのか。人間の限界か、技術の限界か。' }
      ]},
      { id:'sec-history', title:'歴史', blocks:[
        { t:'p', text:'近代文明には、さまざまなスポーツが存在していたことが記録から分かっている。再始動後の人々は、残された記録をもとに、いくつもの競技を復活させた。競技の名前や規則の多くは、近代文明のものをそのまま受け継いでいる。' },
        { t:'p', text:'統合暦1526年、世界規模でスポーツ文化を共有する世界スポーツの日が制定された。国家間の競争を、戦争ではなく文化や技術、競技によって行う時代への移行を象徴する出来事とされている。歯車戦争を経験した人類にとって、競い合う場所を戦場から競技場へ移すことには、大きな意味があった。' }
      ]},
      { id:'sec-divisions', title:'三つの部門', blocks:[
        { t:'p', text:'多くの競技は、選手の身体によって三つの部門に分けられている。' },
        { t:'table', headers:['部門','認められる身体','特徴'], rows:[
          ['生身の部','治療のための再生医療や人工臓器は認められる。能力を高めるための改造や拡張機器は認められない。','近代文明から続く競技の多くが行われる。最も観客が多く、「人間の競技」として特別に扱われる。'],
          ['拡張の部','ナノマシンによる身体能力の補助、身体改造、アニマルボディ、補助腕や翼型の拡張機器などが認められる。改造の内容によって細かな階級に分かれる。','生身では不可能な動きや記録が生まれる。新しい競技も多い。'],
          ['仮想の部','フルダイブで仮想空間に入って競う。現実の身体は問われない。','痛みはなく、しびれで衝撃が伝えられる。ニューロシンクと対応機器が必要。']
        ]},
        { t:'p', text:'生身の部で問題になるのは、どこまでが治療で、どこからが強化なのかという線引きである。人工臓器を入れた選手が、元の臓器よりも高い性能を得ている場合、それは治療なのか、強化なのか。この議論は、競技団体ごとに今も続いている。' }
      ]},
      { id:'sec-giir', title:'生まれ持った差', blocks:[
        { t:'p', text:'GIIRの型の中には、反応速度や運動能力に影響するものがある。生まれ持ったGIIRの違いによって、同じ努力をしても結果に差が出ることがある。' },
        { t:'p', text:'それでも、ほとんどの競技はGIIR値で選手を分けていない。生まれ持った性質によって、人間の価値を決めないという考え方が、未来世界の多くの場所で共有されているからである。身体を作り替えた差は部門で分け、生まれ持った差は分けない。この線の引き方そのものに、未来世界の価値観が表れている。' }
      ]},
      { id:'sec-career', title:'長い選手生命', blocks:[
        { t:'p', text:'平均寿命が約200年の世界では、選手が現役を続ける期間も長い。一つの競技を何十年も続ける選手は珍しくなく、同じ選手が世代の違う相手と戦い続けることになる。' },
        { t:'p', text:'若い選手がなかなか頂点に立てないという問題もある。その一方で、一つの競技を極めたあと、まったく別の競技で二度目の選手生活を始める人も多い。長い人生の中で、いくつもの競技を生きることができる。' }
      ]},
      { id:'sec-light', title:'競技の灯', blocks:[
        { t:'p', text:'近代文明の大きな競技大会では、開会のときに炎を灯していたことが記録に残っている。火を禁忌とする未来世界では、この炎は光で作られた「競技の灯」に置き換えられている。世界スポーツの日には、各地の競技場で同じ時刻に灯がともされる。' },
        { t:'p', text:'灯は熱を持たず、燃え広がることもない。それでも人々は、その光を炎と同じように見つめる。' }
      ]},
      { id:'sec-watch', title:'観戦', blocks:[
        { t:'p', text:'大きな競技場の近くには転送港が設けられ、世界中の観客が試合の直前に到着し、終わればすぐに帰ることができる。' },
        { t:'p', text:'競技場へ行かずに観戦する人も多い。Veloでは試合の生配信や360度映像が見られ、立体映像や、選手の視点に近い映像を体験できるコンテンツもある。仮想の部の試合は、観客もフルダイブで同じ空間に入り、すぐそばで観戦することができる。' }
      ]},
      { id:'sec-nations', title:'国ごとのスポーツ', blocks:[
        { t:'table', headers:['国','特色'], rows:[
          ['フーモラ・スカイピル','空を使う競技が盛ん。飛行できる翼型の拡張機器を使う競技は、利用条件が厳しいため、ごく限られた選手だけが出場できる。'],
          ['チリルド・アイルツア','犬ぞりレース。犬ぞり祭りの伝統を受け継ぐ。'],
          ['ユーレツェア','時計技術を生かした計時で知られる。多くの国際大会で、記録の計測をユーレツェアの職人と機器が担う。'],
          ['キューマ','近代文明の記録から、忘れられた競技を復元して実際に行う。規則が分からない部分は、仮説を立てて試す。'],
          ['オルガロン','身体芸術の都市フォルティッシモを中心に、競技と表現の境目にある演技系の競技が盛ん。'],
          ['ベルネア','アニマルボディの選手が多く、拡張の部で強い。'],
          ['サンルド','試合の勝敗そのものに価値が与えられ、観戦と賭けの文化が結びついている。'],
          ['ガルヒューラ','四暗都市競技。命を懸けた勝負であり、世界の競技団体はこれをスポーツとして認めていない。']
        ]},
        { t:'p', text:'世界スポーツの日は、競い合う場所を戦場から競技場へ移すための日である。その同じ月の終わり、10月31日に、ガルヒューラでは四暗都市競技が開かれる。' }
      ]},
      { id:'sec-meaning', title:'何を競うのか', blocks:[
        { t:'p', text:'身体をいくらでも作り替えられるなら、記録は技術の進歩とともに伸び続ける。拡張の部の世界記録は、選手の努力と同じくらい、改造の質と費用によって決まるとも言われる。' },
        { t:'p', text:'それでも、生身の部の観客は減っていない。人々は、技術が何でもできる世界で、人間の身体だけでどこまで行けるのかを見たいのかもしれない。' },
        { t:'quote', text:'速く走る機械はいくらでもある。それでも人は、人が走るのを見に来る。' }
      ]}
    ],
    related:['daily-life','future-games','body-modification','animal-body','cyborg','nanomachine','giir-linktin','velo','fire-taboo','yonan-cities','travel','calendar-eras']
  }];
  NEW.forEach(function(a){ if(!ARTICLES.some(function(x){return x.id===a.id;})) ARTICLES.push(a); });
  ['daily-life','future-games','body-modification','animal-body','cyborg'].forEach(function(id){ var a=art(id); if(!a){ console.warn('sports: no article', id); return; } a.related=a.related||[]; if(a.related.indexOf('sports')<0) a.related.push('sports'); });
  var de=art('daily-life'); if(de){ var s=(de.sections||[]).filter(function(x){return x.id==='sec-entertainment';})[0];
    if(s && !s.blocks.some(function(b){return b.text && b.text.indexOf('スポーツの項目')>=0;})){ s.blocks.push({ t:'p', text:'スポーツについては、スポーツの項目を参照。' }); de.updated=UPDATED; } }
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.26（6）
   特殊物質三種（アナザニウム・フラマニウム・ドゥルスニウム）と子陽炉の深掘り。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.26';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  function add(id, after, sec){ var a=art(id); if(!a){ console.warn('subst: no article', id); return; }
    if(a.sections.some(function(s){return s.id===sec.id;})) return;
    var i=-1; a.sections.forEach(function(s,k){ if(s.id===after) i=k; }); if(i<0) console.warn('subst: no anchor', id, after);
    a.sections.splice(i>=0?i+1:a.sections.length,0,sec); a.updated=UPDATED; }
  function rel(id, list){ var a=art(id); if(!a) return; a.related=a.related||[]; list.forEach(function(r){ if(a.related.indexOf(r)<0 && r!==id) a.related.push(r); }); }

  /* ---------------- アナザニウム ---------------- */
  add('anazanium','sec-overview',{ id:'sec-discovery', title:'発見', blocks:[
    P('アナザニウムは、統合暦1790年、地上に落ちていた隕石の内部から発見された。隕石を割った研究者たちは、灰色の結晶が、電気を通すと青く光り、硬くなっていくことに気づいた。それまで知られていたどの元素とも違う性質だった。'),
    P('発見から十年ほどのうちに、アナザニウムの研究は特殊素材工学という新しい分野を生み、のちのエネルギー技術の土台となった。'),
    { t:'info', items:[{label:'発見',value:'統合暦1790年'},{label:'発見された場所',value:'地上に落ちていた隕石の内部'},{label:'その後',value:'特殊素材工学の成立（1800年頃）'}]}
  ]});
  add('anazanium','sec-discovery',{ id:'sec-supply', title:'供給', blocks:[
    P('地上でアナザニウムが見つかるのは、隕石が落ちた跡のわずかな岩場だけである。世界で使われているアナザニウムのほとんどは、ヒューバートが出荷しているものである。'),
    P('ヒューバートは、発見の直後からまとまった量のアナザニウムを世界へ出荷し始めた。長いあいだ産地を明かさなかったが、本格的な宇宙開発が始まってからは、地球外の天体で採掘したものだと公表している。発見以来、アナザニウムの供給が途絶えたことは一度もない。'),
    P('人類が宇宙へ出る手段を持たなかった時代に、ヒューバートはどこから大量のアナザニウムを得ていたのか。この疑問を口にする研究者もいるが、ヒューバートは答えていない。世界中の国が、その答えを知らないまま、ヒューバートのアナザニウムで暮らしている。'),
    P('アナザニウムは、一度手に入れれば何度でも使える。放電して灰色に戻せば、再び加工できるからである。古い設備のアナザニウムは回収され、新しい設備へ作り直される。')
  ]});
  add('anazanium','sec-usage',{ id:'sec-life', title:'暮らしの中のアナザニウム', blocks:[
    P('アナザニウムは蓄電が進むほど青白く光るため、色を見れば残りの電気の量が分かる。家庭の配電盤や玄関先の充電スポット、乗り物の蓄電部には、外から色が見える小窓が付けられていることが多い。'),
    P('夜の住宅街に灯るぼんやりとした青い光は、未来世界のありふれた景色である。「家が青い」と言えば、電気が十分に蓄えられている、という意味になる。'),
    { t:'table', headers:['色','暮らしの中での意味'], rows:[
      ['灰色','電気が空。充電が必要。加工や修理ができる状態でもある。'],
      ['青','電気が蓄えられている。強く光るほど量が多い。'],
      ['赤','過充電。すぐに離れ、専門の担当者を呼ぶ。']
    ]},
    P('子どもたちは、言葉より先に「赤いアナザニウムには近づくな」を教わる。未来世界の安全教育は、色の意味を覚えることから始まる。'),
    { t:'quote', text:'夜の青は、蓄えの色である。' }
  ]});
  rel('anazanium',['energy-tech','daily-life','material-engineering','jelly-moss']);

  /* ---------------- フラマニウム ---------------- */
  add('framanium','sec-overview',{ id:'sec-origin', title:'供給と由来', blocks:[
    P('フラマニウムは、ヒューバートが世界へ出荷している。アナザニウムの発見と前後して世に出始め、ヒューバートは長く産地を明かさなかったが、宇宙開発が本格化してからは、地球外の天体で採掘したものだと公表している。地球上で天然のフラマニウムが見つかったことはない。'),
    P('その耐熱性能を正しく扱えるようになったのは、統合暦1800年頃に特殊素材工学が成立してからである。'),
    P('フラマニウムの供給は、これまで一度も途絶えたことがない。')
  ]});
  add('framanium','sec-weakness',{ id:'sec-handling', title:'扱いの難しさ', blocks:[
    P('フラマニウムは、熱に強いのに、冷えることに弱い。高温の設備を止めるときは、何日もかけて少しずつ温度を下げなければならない。急いで冷やせば、結晶が傷み、耐熱性能が大きく落ちる。'),
    P('そのため、フラマニウムを使う設備では「止める技術」が「動かす技術」と同じくらい重視される。子陽炉の起動と停止に時間がかかるのも、この性質のためである。')
  ]});
  add('framanium','sec-usage',{ id:'sec-fire', title:'火に最も近い素材', blocks:[
    P('火を禁忌とする未来世界で、フラマニウムは、火に最も近い場所で使われる素材である。子陽炉の炉心のほか、例外として認められている葬儀の火葬炉にも、フラマニウムが使われている。火葬炉の炎が通常の炎よりも白く澄んだ青みを帯びるのは、フラマニウムの内壁の中で安定して燃えるためである。'),
    P('火を使わない加熱調理器や工業炉など、燃焼の代わりに高い熱を生み出す技術も、フラマニウムなしには成り立たない。人々が火から離れて暮らせるのは、火の代わりに熱を受け止める素材があるからでもある。'),
    { t:'quote', text:'火を遠ざけた世界で、熱だけはフラマニウムが預かっている。' }
  ]});
  rel('framanium',['death-and-funeral','fire-alternatives','fire-taboo','ancient-civilization','material-engineering']);

  /* ---------------- ドゥルスニウム ---------------- */
  add('dulsnium','sec-overview',{ id:'sec-origin', title:'供給と由来', blocks:[
    P('ドゥルスニウムも、フラマニウムと同じくヒューバートが出荷している。ヒューバートは、地球外の天体で採掘したものだと説明している。地球上で天然のドゥルスニウムが見つかったことはない。'),
    P('出荷が始まった当初、ドゥルスニウムは硬すぎて加工できず、「割れない石」と呼ばれて使い道がなかった。低温で加工しやすくなる性質が見つかったことで、ようやく素材として使えるようになった。')
  ]});
  add('dulsnium','sec-special',{ id:'sec-cold', title:'冷やして加工する', blocks:[
    P('ドゥルスニウムの加工は、適切な低温に保った加工室の中で行われる。冷やすと結晶構造が変わり、切る、曲げる、繊維にするといった加工ができるようになる。加工を終えて常温に戻すと、再び極めて硬い状態に戻る。'),
    P('冷やしすぎると、今度はかえって加工できなくなる。ドゥルスニウムの職人に求められるのは、加工しやすい温度の幅を見極めて保つ技術である。'),
    P('低温での加工技術が確立してからは、ドゥルスニウムは「軽くて加工しやすい素材」として広く知られるようになった。常温では割れないほど硬く、冷やせば思いどおりの形にできる。この二つの顔が、ドゥルスニウムの使いやすさを生んでいる。'),
    { t:'table', headers:['温度','状態'], rows:[
      ['常温','極めて硬く、軽い。完成品として使われる状態。'],
      ['適切な低温','結晶構造が変わり、加工しやすくなる。'],
      ['過度な低温','かえって加工が難しくなる。'],
      ['高温','結晶構造が崩れ始め、強度が下がる。']
    ]}
  ]});
  add('dulsnium','sec-weakness',{ id:'sec-life', title:'暮らしの中のドゥルスニウム', blocks:[
    P('ドゥルスニウムは、未来世界の「丈夫さ」を支えている。超高層建築の骨組み、SVHの制服、乗り物の外装、工具など、軽さと強さが同時に求められる場所には、たいていドゥルスニウムが使われている。'),
    P('硬い素材を切る道具としても欠かせない。巨大な甲殻を持つ生物の殻を割るときや、蓄電したアナザニウムを切るときなど、ほかの道具では歯が立たない場面で使われる。'),
    { t:'quote', text:'割れないものを割るために、割れない石を使う。' }
  ]});
  rel('dulsnium',['svh','architecture','giant-crab','ancient-civilization','material-engineering','solar-core']);

  /* ---------------- 子陽炉の歴史 ---------------- */
  add('solar-core','sec-overview',{ id:'sec-history', title:'歴史', blocks:[
    P('子陽炉が実用化されたのは、統合暦1860年頃である。フラマニウム、ドゥルスニウム、アナザニウムという三つの特殊物質が出そろい、特殊素材工学によってそれぞれの扱い方が確立したことで、極小の恒星反応を設備の中に保つことが初めて可能になった。'),
    P('開発は世界科学連盟を中心とした各国の共同研究として進められた。ただし、反応の基本となる設計図はヒューバートの研究機関から示されたものとされ、その設計図がどのように生まれたのかには、今も分からない部分がある。'),
    { t:'table', headers:['統合暦','出来事'], rows:[
      ['1790年','アナザニウム発見'],
      ['1800年頃','特殊素材工学の成立'],
      ['1840年頃','特殊素材による建築技術の発展'],
      ['1860年頃','子陽炉の実用化'],
      ['1870年代〜','セルトシティ建設計画やフーモラ・スカイピルの空中都市機能の確立など、大量の電力を必要とする都市が生まれる']
    ]},
    P('子陽炉は、世界環境協定のもとで大規模な燃焼から離れていった人類が、ようやく手にした「燃やさない大きな熱」だった。')
  ]});
  rel('solar-core',['world-science-federation','calendar-eras']);

  /* ---------------- 整合：宇宙資源・ゼリーゴケ・特殊素材工学 ---------------- */
  function swapText(id, oldT, newT){ var a=art(id); if(!a){ console.warn('subst: no', id); return; } var hit=false;
    a.sections.forEach(function(s){ s.blocks.forEach(function(b){
      if(b.text && b.text.indexOf(oldT)>=0){ b.text=b.text.replace(oldT,newT); hit=true; }
      if(b.items) b.items.forEach(function(it){ if(it && it.value && it.value.indexOf(oldT)>=0){ it.value=it.value.replace(oldT,newT); hit=true; } });
    }); }); if(!hit) console.warn('subst: text not found', id, oldT); }
  swapText('space-resources','アナザニウム・ドゥルスニウム・アキュタニウムなど','アナザニウム・フラマニウム・ドゥルスニウム・アキュタニウムなど');
  swapText('space-resources','アナザニウムやドゥルスニウムは、宇宙開発で確保される重要な資源として扱われている。','アナザニウム、フラマニウム、ドゥルスニウムは、ヒューバートが地球外の天体で採掘し、出荷しているとされる重要な資源である。');
  swapText('jelly-moss','アナザニウムを含む岩場では','隕石が落ちた跡の、アナザニウムを含む岩場では');
  add('material-engineering','sec-materials',{ id:'sec-three', title:'三つの特殊物質', blocks:[
    { t:'table', headers:['素材','供給','得意なこと','弱点'], rows:[
      ['アナザニウム（An）','ヒューバートが出荷（地球外の天体で採掘と公表）。1790年に隕石の中から発見','電気を蓄える','過充電（赤色化）'],
      ['フラマニウム（Fa）','ヒューバートが出荷（地球外の天体で採掘と公表）','熱に耐える','急冷・衝撃'],
      ['ドゥルスニウム（Du）','ヒューバートが出荷（地球外の天体で採掘と公表）','軽く、極めて硬い','高温・過冷却']
    ]},
    P('三つの素材は、得意なことと弱点がそれぞれ違う。特殊素材工学は、一つの素材にすべてを求めず、それぞれを得意な場所に置くという考え方で発展してきた。')
  ]});
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.26（8）
   ヒルロンド（新規）・スティルストーン（新規）と関連記事の接続。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.26';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var NEW = [
  { id:'hillronde', cat:'history', title:'ヒルロンド', updated:UPDATED,
    lede:'統合暦028年から1000年まで存在した科学研究国家。現在のヒューバートの前身。数や富ではなく技術で立つことを選び、近代文明の遺構から掘り出したロストテクノロジーを解析して、歯車戦争ではラロネイアの侵攻を退けた。その全期間を「黒い猫」フェーレース・ニグラが率いたとされる。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        P('ヒルロンドは、人類文明再始動から間もない統合暦028年に成立した国家である。科学研究を国の中心に置き、のちに世界最高水準の科学技術国家となるヒューバートの基盤を築いた。'),
        P('ヒルロンドの約千年の歴史は、ほとんどが一人の人物の名と結びついている。創立から改称まで国を率いたとされる、フェーレース・ニグラである。'),
        { t:'info', items:[
          {label:'存在した期間',value:'統合暦028年〜1000年'},{label:'国柄',value:'科学研究国家'},{label:'指導者',value:'フェーレース・ニグラ（「黒い猫」）'},
          {label:'技術の源',value:'近代文明のロストテクノロジー'},{label:'後継',value:'ヒューバート（1000年に改称）'},{label:'象徴',value:'黒い猫（現在のヒューバートの国旗に残る）'}
        ]},
        { t:'quote', text:'数では勝てない。だから、一つずつ確かめる。' }
      ]},
      { id:'sec-founding', title:'成立', blocks:[
        P('ヒルロンドは、ニポラン（001年）、ラロネイア（010年）に続いて成立した、最も古い国家の一つである。目覚めたばかりの世界で多くの共同体が暮らしの再建を急ぐなか、ヒルロンドは最初から「理解すること」を国の柱に据えた。'),
        P('建国の経緯を記した資料はほとんど残っていない。分かっているのは、創立の時点からフェーレース・ニグラが国を率いていたこと、そして早くから近代文明の遺構の調査が行われていたことである。')
      ]},
      { id:'sec-lost-tech', title:'ロストテクノロジー', blocks:[
        P('ヒルロンドの技術の源は、近代文明の遺構から掘り出されたロストテクノロジーだった。地中に埋まった施設や機械、記録を掘り出し、仕組みを解き明かし、自分たちの技術として作り直していった。'),
        P('近代文明の遺構を組織的に調べた国としては、ヒルロンドが最も古い。キューマが考古学の国として歩み始めるより、ずっと前のことである。ただし、ヒルロンドがどこを掘り、何を見つけたのかを記した記録は、ほとんど公開されていない。'),
        P('ヒルロンドの調査は、狙いを外すことが少なかったと伝えられている。まるでどこに何が埋まっているかを知っていたかのようだった、と後の研究者は書いている。')
      ]},
      { id:'sec-laroneia', title:'ラロネイアとの対比', blocks:[
        P('同じ時代の大国ラロネイアと、ヒルロンドはしばしば対比して語られる。'),
        { t:'table', headers:['','ラロネイア','ヒルロンド'], rows:[
          ['強み','広大な領土、生産力、軍事力','一つ一つの技術の確かさ'],
          ['技術の源','工業と大量生産','近代文明のロストテクノロジーの解析'],
          ['戦い方','数と富で押し切る','技術で守り、退ける'],
          ['その後','敗戦と崩壊、ガルヒューラへ','科学国家ヒューバートへ']
        ]}
      ]},
      { id:'sec-war', title:'歯車戦争', blocks:[
        P('統合暦412年、ラロネイアとオルガロンの対立をきっかけに歯車戦争が始まると、ヒルロンドは参戦し、ラロネイアに対抗する陣営の中心となった。418年にはニポランが加わり、のちにチリルドとヲンヘードもヒルロンド側へ移った。'),
        P('戦争の末期、同盟国の離脱が相次いだラロネイアは、ヒルロンドへの本格的な侵攻に踏み切った。ヒルロンドはロストテクノロジーを用いた防衛でこれを阻み、ラロネイア軍は大きな損害を受けた。463年、歯車戦争はラロネイアの敗北によって終わった。'),
        P('終戦に向けて、ヒルロンドはオルガロンとの交流を深めた。この交流は、のちのヒューバートとオルガロンの友好関係の始まりとなっている。')
      ]},
      { id:'sec-science', title:'科学発展期', blocks:[
        P('戦後、世界が戦時の技術を民間へ転用していくなかで、ヒルロンドでは統合暦520年頃から科学研究が急速に発展した。ロストテクノロジーの解析と、戦争で鍛えられた技術が結びつき、のちのヒューバートの科学の基盤が形づくられた。'),
        P('ヒルロンドの研究は、知識をできるだけ外へ出さない姿勢でも知られていた。成果の多くは国の内側にとどめられ、何が研究されていたのかは、今でも全体が分かっていない。この秘密主義は、現在のヒューバートとハーネンス研究所にも受け継がれている。')
      ]},
      { id:'sec-1000', title:'1000年', blocks:[
        P('統合暦1000年、ヒルロンドは国の名をヒューバートへ改めた。科学国家としての発展を象徴するための改称とされる。'),
        P('同じ時期、ハーネンス家が歴史の表舞台に現れ、フェーレース・ニグラは姿を消した。創立から約千年にわたって国を率いたとされる人物は、改称とともに記録から消え、その後の行方は分かっていない。'),
        P('改称の直後、1020年頃には、歯車戦争時代の技術を平和のために使うオルガロンとの技術協力が始まり、ヒューバートは科学と生命技術の国としての道を歩み始めた。')
      ]},
      { id:'sec-legacy', title:'残したもの', blocks:[
        P('ヒルロンドが現在に残したものは多い。世界最高水準の科学技術、研究を国の中心に置く文化、成果を外へ出さない慎重さ。そして、ヒューバートの国旗に描かれた黒い猫である。'),
        P('フェーレース・ニグラが名乗った「黒い猫」は、彼の時代にはまだ存在しなかった動物の名だった。猫がヒューバートで再誕し、国の象徴となったのは、ヒルロンドが名を変えた後のことである。'),
        { t:'quote', text:'国は名を変えた。黒い猫だけが、旗の上に残った。' }
      ]},
      { id:'sec-unknown', title:'未解明の点', blocks:[
        { t:'list', items:[
          'フェーレース・ニグラは、本当に千年近く国を率いたのか。それとも名前が受け継がれたのか',
          'ヒルロンドは、どの遺構から、どのようなロストテクノロジーを掘り出したのか',
          'なぜヒルロンドの調査は、埋まっている場所を知っていたかのように的確だったのか',
          '1000年の改称と、ハーネンス家の登場、フェーレースの失踪は、どのようにつながっているのか'
        ]}
      ]}
    ],
    related:['ferres-nigra','hubert','gear-war','laroneia','modern-excavation','modern-civilization','orgaron','cat-culture','harnens_institute','kyuma']
  },
  { id:'stillstone', cat:'substance', title:'スティルストーン', updated:UPDATED,
    lede:'タスメニオの巨大隕石島と周辺の海底に眠る、太陽系の外から来た鉱物。周りの水の動きを鎮める性質を持ち、風が止んだ日に海面が鏡のようになる「硝子海」の正体とされる。海民は古くから「波を寝かせる石」と呼んできた。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        P('スティルストーンは、タスメニオの巨大隕石島と、その周辺の海底に分布する鉱物である。島を作った巨大隕石とともに地球へもたらされたもので、地球上ではタスメニオの海域でしか見つかっていない。'),
        P('最大の特徴は、周りの水の動きを鎮める性質である。スティルストーンの近くでは、波や細かな揺れが弱まり、水がゆっくりと静まっていく。'),
        { t:'info', items:[
          {label:'英名',value:'Stillstone'},{label:'通称',value:'波寝石（なみねいし）'},{label:'由来',value:'太陽系の外から来た隕石'},
          {label:'産地',value:'タスメニオの巨大隕石島と周辺の海底'},{label:'主な性質',value:'周りの水の動きを鎮める'},{label:'関係する現象',value:'硝子海'}
        ]},
        { t:'quote', text:'海を静めたのは、空の向こうから来た石だった。' }
      ]},
      { id:'sec-origin', title:'由来', blocks:[
        P('タスメニオの巨大隕石島は、約一万年前に太平洋中央域へ落下した巨大な隕石によって作られたと考えられている。この落下は、氷河期の寒冷化の要因の一つともされる。'),
        P('スティルストーンを分析すると、その組成は太陽系で見つかるどの物質とも一致しない。そのため、島を作った隕石そのものが、太陽系の外から長い旅をしてきたものだと考えられている。どこの星系から来たのかは、分かっていない。'),
        P('同じく地球外由来とされるアナザニウムとは、まったく別の物質である。')
      ]},
      { id:'sec-property', title:'性質', blocks:[
        P('スティルストーンは、周囲の水の細かな動きを吸い取るように弱める。大きな塊ほど作用が強く、鉱床が広がる海域では、潮の流れや波の形にも影響が出ている。タスメニオ周辺の海流が複雑なのも、海底に散らばるスティルストーンが、場所ごとに水の動きを変えているためだと考えられている。'),
        P('ただし、風そのものを止める力はない。風が強い日には、スティルストーンの上でも海は荒れる。'),
        { t:'table', headers:['条件','海のようす'], rows:[
          ['風が強い','通常の海と同じように荒れる'],
          ['風が弱い','波が早く収まり、海面が穏やかになる'],
          ['風が完全に止まる','海面の揺れがほとんど消え、鏡のようになる（硝子海）']
        ]}
      ]},
      { id:'sec-glass-sea', title:'硝子海', blocks:[
        P('タスメニオでは、年に数回だけ風が完全に止まり、海面が鏡のようになる「硝子海」が起きる。空と海の境界が消えるこの現象は、風が止まった海を、海底のスティルストーンがさらに静めることで生まれると考えられている。'),
        P('同じように風が止む日は他の海にもあるが、ここまで完全な鏡になる海はタスメニオにしかない。')
      ]},
      { id:'sec-history', title:'海民と波寝石', blocks:[
        P('統合暦170年頃から巨大隕石島に住み始めた海民たちは、浅瀬で拾える灰白色の石を、船の底に積むと揺れが減ることに早くから気づいていた。彼らはそれを「波寝石」と呼び、長い航海の守り石として大切にした。'),
        P('波寝石が太陽系の外から来た物質だと分かったのは、ずっと後の時代の研究による。スティルストーンという名は、その研究の中で付けられたものである。')
      ]},
      { id:'sec-use', title:'利用', blocks:[
        { t:'list', items:[
          '船の制振材：船体の揺れを抑え、乗り物酔いを減らす',
          '建物の制振：タスメニオの立体都市や防波設備の揺れを抑える',
          '精密機器の台座：細かな振動を嫌う計測機器や工房の作業台'
        ]},
        P('スティルストーンは、深い海底ほど大きな塊が眠っているとされる。しかし、海底の調査はオルドレンジへの警戒から長く避けられており、採掘されているのは、島と浅い海域のものに限られる。'),
        P('地球上ではタスメニオでしか採れないため、産出量は多くない。タスメニオの人々は、波寝石を必要以上に掘り出すことを好まない。海を静めているものを、海から取り上げすぎることになるからである。')
      ]}
    ],
    related:['tasumenio','tasumenio-foundation','ice-age','seabed','anazanium','material-engineering','transportation']
  }];
  NEW.forEach(function(a){ if(!ARTICLES.some(function(x){return x.id===a.id;})) ARTICLES.push(a); });

  function swapText(id, oldT, newT){ var a=art(id); if(!a){ console.warn('hill: no', id); return; } var hit=false;
    a.sections.forEach(function(s){ s.blocks.forEach(function(b){ if(b.text && b.text.indexOf(oldT)>=0){ b.text=b.text.replace(oldT,newT); hit=true; }
      if(b.rows) b.rows.forEach(function(r){ r.forEach(function(c,i){ if(typeof c==='string' && c.indexOf(oldT)>=0){ r[i]=c.replace(oldT,newT); hit=true; } }); }); }); });
    if(!hit) console.warn('hill: text not found', id, oldT); else a.updated=UPDATED; }
  function rel(id, list){ var a=art(id); if(!a){ console.warn('hill: no', id); return; } a.related=a.related||[]; list.forEach(function(r){ if(a.related.indexOf(r)<0 && r!==id) a.related.push(r); }); }

  /* フェーレース：公開側は性別不明なので「彼が」を外す */
  swapText('ferres-nigra','そして彼が自ら名乗った「黒い猫」に由来する','そしてフェーレースが自ら名乗った「黒い猫」に由来する');
  /* ↑ ヒルロンドの記事の「彼の時代」も性別に触れないよう調整 */
  var h=art('hillronde'); if(h){ h.sections.forEach(function(s){ s.blocks.forEach(function(b){ if(b.text) b.text=b.text.replace('彼の時代には','その時代には'); }); }); }

  /* タスメニオ・隕石 */
  swapText('tasumenio','隕石落下によって形成された影響から、特殊な鉱物資源が眠る海域とも言われている。','隕石落下によって形成された影響から、特殊な鉱物資源が眠る海域でもある。海底には、太陽系の外から来た鉱物スティルストーンが分布している。');
  swapText('tasumenio','年に数回だけ風が完全に止まり、海面が鏡のようになる「硝子海」が発生する。その時、空と海の境界が消える。','年に数回だけ風が完全に止まり、海面が鏡のようになる「硝子海」が発生する。その時、空と海の境界が消える。風の止んだ海を、海底のスティルストーンがさらに静めることで起きると考えられている。');
  swapText('tasumenio-foundation','島と周辺海域には特殊な鉱物が存在するとされ、後のタスメニオの発展にも影響を与えることになる。','島と周辺海域には、太陽系の外から来た鉱物スティルストーンが存在し、後のタスメニオの発展にも影響を与えることになる。');
  swapText('ice-age','この隕石が形成した島は、後に発見され、現在のタスメニオの国土の起点となった。','この隕石が形成した島は、後に発見され、現在のタスメニオの国土の起点となった。島に残る鉱物スティルストーンの組成から、隕石は太陽系の外から来たものと考えられている。');
  rel('tasumenio',['stillstone']); rel('tasumenio-foundation',['stillstone']); rel('ice-age',['stillstone']); rel('material-engineering',['stillstone']);
  rel('ferres-nigra',['hillronde']); rel('hubert',['hillronde']); rel('gear-war',['hillronde']); rel('laroneia',['hillronde']); rel('modern-excavation',['hillronde']);
  /* 近代文明の発掘：ヒルロンドが最古の組織的調査 */
  var me=art('modern-excavation'); if(me){ var s=(me.sections||[]).filter(function(x){return x.id==='sec-method';})[0];
    if(s && !s.blocks.some(function(b){return b.text && b.text.indexOf('ヒルロンド')>=0;})){
      s.blocks.unshift(P('近代文明の遺構を組織的に調べた最初の国は、統合暦028年に成立したヒルロンド（現在のヒューバート）だとされる。ヒルロンドは遺構から掘り出したロストテクノロジーを解析して国の技術とした。ただし、その調査の記録はほとんど公開されていない。')); me.updated=UPDATED; } }
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27
   獣喰い・獣チャレンジ（新規記事。ベルネア発祥、現在流行中）。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function sec(a,id){ return a ? (a.sections||[]).filter(function(s){return s.id===id;})[0] : null; }

  var NEW = [{
    id:'kemonogui', cat:'life', collection:['culture'], title:'獣喰い', aliases:['獣チャレンジ'], updated:UPDATED,
    lede:'野生の獣や家畜の肉を再現した培養肉を、生のまま塊でかぶりつく食べ方。ベルネアで「獣と同じになりたい」という行き過ぎた愛から生まれ、いま世界中で流行している。味付けをしない肉を食べきれるかを競う「獣チャレンジ」も人気を集めている。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        { t:'p', text:'獣喰い（けものぐい）は、生の培養肉を薄く切らず、塊のまま歯で噛みちぎって食べる食べ方である。焼かず、煮ず、温めもしない。皿やナイフをほとんど使わず、手で持って口へ運ぶ。' },
        { t:'p', text:'使われるのは、野生の獣の肉を再現した培養肉と、家畜の肉を再現した培養肉だけである。塩や香草で軽く味をつける「味付き」と、何もつけない「素（す）」の二通りがあり、素のまま食べきれるかを競う遊びは「獣チャレンジ」と呼ばれる。' },
        { t:'info', items:[
          { label:'読み', value:'けものぐい' },
          { label:'発祥', value:'ベルネア' },
          { label:'状況', value:'現在流行中' },
          { label:'使う肉', value:'野生の獣・家畜を再現した培養肉のみ' },
          { label:'食べ方', value:'生・塊のまま・手で持つ' },
          { label:'派生', value:'獣チャレンジ' }
        ]},
        { t:'quote', text:'今日の私は、獣だ。' }
      ]},
      { id:'sec-origin', title:'始まり', blocks:[
        { t:'p', text:'獣喰いは、生命を観察し、理解することを文化の中心に置くベルネアで生まれた。ベルネアの人々は幼いころから環境ドームで生き物を見て育ち、興味を持った生き物の特徴を、アニマルボディ技術で自分の身体に取り入れる人も多い。' },
        { t:'p', text:'その愛は、ときに行き過ぎる。耳や尾や牙を手に入れた人々の中から、「姿だけでなく、食べ方まで獣と同じになりたい」と考える人が現れた。トロピカルドームで捕食の様子を何年も観察してきた研究者たちが、同じ肉を、同じように生のまま噛みちぎって食べてみたのが始まりとされる。' },
        { t:'p', text:'最初は一部の観察者の間だけの習慣だった。しかし、牙を持つアニマルボディの人が肉の塊にかぶりつく映像がSNSで広まると、その豪快さが評判になり、ベルネアの外へも一気に広がった。今では、アニマルボディを持たない人々のあいだでも流行している。' },
        { t:'quote', text:'なんて素晴らしい捕食なんだ。……私も、やってみたい。' }
      ]},
      { id:'sec-meat', title:'使う肉', blocks:[
        { t:'p', text:'獣喰いに使われるのは、再現肉と呼ばれる培養肉である。ふだん食卓に並ぶ培養肉は、加熱して味をつけることを前提に作られており、筋や臭みが少なく、誰でも食べやすいように整えられている。' },
        { t:'p', text:'再現肉は、その調整をあえて行わない。もとの動物の肉を、筋の固さも、血の味も、獣の匂いも、できるだけそのまま再現している。獣喰いでは、この再現肉だけが「本物の獣の肉」として扱われる。' },
        { t:'table', headers:['種類','特徴'], rows:[
          ['家畜の再現肉','牛・豚・羊など、かつて飼育されていた家畜の肉を再現したもの。脂が多く、比較的食べやすい。獣喰いの入門として選ばれることが多い。'],
          ['野生の獣の再現肉','猪・鹿・熊など、野生の獣の肉を再現したもの。筋が固く、血と鉄の味、獣臭さがはっきりしている。獣喰いを好む人ほど、こちらを選ぶ。']
        ]}
      ]},
      { id:'sec-safety', title:'生で食べられる理由', blocks:[
        { t:'p', text:'かつての生肉には、寄生虫や病原菌の危険がつきものだった。そのため、肉を生のまま塊で食べることは、近代文明でもごく限られた料理にとどまっていた。' },
        { t:'p', text:'培養肉は、管理された施設の中で、細胞から作られる。動物の体の中を通らないため、寄生虫や菌が入り込む余地がほとんどない。生の肉に安心してかぶりつけることそのものが、培養肉の時代になって初めて手に入ったものである。' },
        { t:'p', text:'もっとも、安全であることと、食べやすいことは別である。安全な肉であっても、素の再現肉は顎と胃に重い。食べすぎて体調を崩す人は今もおり、医療技術が発達した世界らしく、獣喰いの店の近くには胃腸を整える薬を置く店が増えている。' }
      ]},
      { id:'sec-howto', title:'食べ方', blocks:[
        { t:'p', text:'獣喰いでは、肉の塊を手で持ち、端から歯で噛みちぎって食べる。切り分けることは「人の食べ方」として避けられ、刃物を使わないことが作法とされる。' },
        { t:'list', items:[
          '味付き：塩、香草、果実の汁などを肉の表面に軽くつける。素の肉よりずっと食べやすく、獣喰いの店で最もよく注文される。',
          '素：何もつけない。再現肉の筋、血の味、獣臭さがそのまま口に残る。',
          '骨付き：骨の形まで再現した肉。骨のまわりの肉を噛み取るのが醍醐味とされる。'
        ]},
        { t:'p', text:'獣喰いを出す店は「獣喰い屋」と呼ばれる。店内を薄暗くし、獣の声や森の音を流す店も多い。牙のあるアニマルボディの客のために、特に固い肉を用意している店もある。' }
      ]},
      { id:'sec-challenge', title:'獣チャレンジ', blocks:[
        { t:'p', text:'獣チャレンジは、素の再現肉の塊を、ひとりで最後まで食べきれるかを競う遊びである。味がないぶん、肉そのものの味が逃げ場なく口に広がる。最初の数口は豪快に食べられても、途中から顎が疲れ、血と鉄の味と獣の匂いに耐えられなくなる人が多い。' },
        { t:'p', text:'多くの獣喰い屋が、店ごとに獣チャレンジを用意している。家畜の肉から始まり、野生の獣の肉へ進むほど難しくなる。完食した人は名前と時間が店の壁に掲げられ、完食者が少ない店ほど「本物の獣の店」として名が知られる。' },
        { t:'p', text:'挑戦の様子はSNSで盛んに共有されている。完食の瞬間よりも、途中で手が止まり、肉を見つめて黙り込む場面の方が人気があるとも言われる。' },
        { t:'quote', text:'三口目までは、獣だった。' }
      ]},
      { id:'sec-fire', title:'火を使わない世界で', blocks:[
        { t:'p', text:'未来世界では火が禁忌とされ、料理は燃焼を使わない加熱技術で作られる。「炭火焼き」「炙り」といった名前だけを残し、火から生まれた文化を丁寧に再現してきた世界である。' },
        { t:'p', text:'獣喰いは、その丁寧さの反対側にある。火を使わないどころか、加熱も、味付けも、切り分けることもやめてしまう。何でも整えられる世界だからこそ、何も整えないまま食べることが新鮮に映った、と見る人は多い。' }
      ]},
      { id:'sec-reaction', title:'受け止められ方', blocks:[
        { t:'table', headers:['立場','評価'], rows:[
          ['ベルネアの若い世代','獣の生き方を、自分の身体で知る方法として楽しんでいる。'],
          ['ベルネアの年長の研究者','触らない、追わない、待つという観察の作法と正反対だとして、眉をひそめる人も多い。「獣を見るのではなく、獣になろうとしてどうする」という声がある。'],
          ['他国の若者','豪快さと、獣チャレンジの遊びとしての面白さから広まった。アニマルボディを持たない人も多い。'],
          ['ラリアフルス','森の植物の方がずっと美味しいのに、なぜわざわざ生の肉を噛むのか分からない、という受け止め方が多い。'],
          ['食文化保護団体','食べ方そのものは自由としながら、獣チャレンジで食べきれず残される肉が多いことを問題にしている。']
        ]},
        { t:'p', text:'獣喰いという名前でも、動物を殺して食べているわけではない。使われるのはすべて培養肉であり、「獣のように食べる」という食べ方の名前である。生物を殺して食べる文化が一般的ではないベルネアから生まれたことも、そのことを示している。' }
      ]}
    ],
    related:['belnea','animal-body','industrial-livestock','carpaccio','food-culture','stimulating-food','gaming-full-food','social-media','fire-taboo','larliafrus']
  }];
  NEW.forEach(function(a){ if(!ARTICLES.some(function(x){return x.id===a.id;})) ARTICLES.push(a); });

  /* 関連項目 */
  ['belnea','animal-body','industrial-livestock','carpaccio','food-culture','stimulating-food','gaming-full-food'].forEach(function(id){
    var a=art(id); if(!a){ console.warn('kemono: no article', id); return; }
    a.related=a.related||[]; if(a.related.indexOf('kemonogui')<0) a.related.push('kemonogui');
  });

  /* 食文化：味と流行 */
  var fc=art('food-culture'), ft=sec(fc,'sec-taste');
  if(ft && !ft.blocks.some(function(b){return b.text && b.text.indexOf('獣喰い')>=0;})){
    ft.blocks.push({ t:'p', text:'現在は、ベルネアで生まれた獣喰いが流行している。野生の獣や家畜の肉を再現した培養肉を、生のまま塊でかぶりつく食べ方で、味付けをしない肉を食べきれるかを競う獣チャレンジも人気を集めている。' });
    fc.updated=UPDATED;
  }
  /* ベルネア：暮らしと文化／観光と名物 */
  var be=art('belnea'), bl=sec(be,'sec-life'), bt=sec(be,'sec-tourism');
  if(bl && !bl.blocks.some(function(b){return b.text && b.text.indexOf('獣喰い')>=0;})){
    bl.blocks.push({ t:'p', text:'近年は、生き物への愛が行き過ぎたかたちとして、獣喰いがベルネアから世界へ広まった。獣と同じになりたいという思いから、再現した培養肉を生のまま噛みちぎる食べ方である。年長の研究者の中には、観察の作法と正反対だとして眉をひそめる人も多い。' });
  }
  if(bt && !bt.blocks.some(function(b){return b.text && b.text.indexOf('獣喰い')>=0;})){
    var qi=-1; bt.blocks.forEach(function(b,i){ if(b.t==='quote') qi=i; });
    var p={ t:'p', text:'若い旅行者のあいだでは、発祥の地で獣喰いを体験することも目的の一つになっている。セントラルドームの周辺には獣喰い屋が集まり、獣チャレンジの完食者の名前が並ぶ壁を見に来る人もいる。' };
    if(qi>=0) bt.blocks.splice(qi,0,p); else bt.blocks.push(p);
  }
  if(be) be.updated=UPDATED;
  /* カルパッチョ：培養肉の普及 */
  var ca=art('carpaccio'), cs=sec(ca,'sec-cultured-meat');
  if(cs && !cs.blocks.some(function(b){return b.text && b.text.indexOf('獣喰い')>=0;})){
    cs.blocks.push({ t:'p', text:'生の培養肉を薄く切って上品に味わうカルパッチョに対し、塊のまま噛みちぎる獣喰いは、同じ生の培養肉を正反対の作法で食べる料理として比べられることがある。' });
    ca.updated=UPDATED;
  }
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（2）
   名物料理18品の厚みを、元からある料理記事（カルパッチョ・共鍋など）にそろえる。
   食材・作り方・味・香り・食感・食べ方・由来などの節を追加する。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  /* before：この節の前に入れる（無ければ sec-culture の前、それも無ければ末尾） */
  function ins(id, sec, before){
    var a=art(id); if(!a){ console.warn('recipe: no article', id); return; }
    if(a.sections.some(function(s){return s.id===sec.id;})) return;
    var idx=-1, keys=[before,'sec-culture'];
    for(var k=0;k<keys.length && idx<0;k++){ if(!keys[k]) continue; a.sections.forEach(function(s,i){ if(s.id===keys[k]) idx=i; }); }
    if(idx<0) a.sections.push(sec); else a.sections.splice(idx,0,sec);
    a.updated=UPDATED;
  }
  function addTo(id, secId, blocks){
    var a=art(id); if(!a) return; var s=a.sections.filter(function(x){return x.id===secId;})[0]; if(!s) { console.warn('recipe: no sec', id, secId); return; }
    if(s.blocks.some(function(b){return b.text===blocks[0].text;})) return;
    s.blocks.push.apply(s.blocks, blocks); a.updated=UPDATED;
  }

  /* ---------------- ベルネアドーム盛り ---------------- */
  ins('belnea-dome-mori',{ id:'sec-make', title:'作り方', blocks:[
    P('六つの器は、それぞれのドームの形をかたどった小さな半球の器である。料理人は器ごとに別々の料理を仕上げ、最後に一枚の大きな皿の上へ、ベルネアの地図と同じ配置で並べる。中央にセントラルの器を置き、その周りを五つの器が囲む。'),
    P('器ごとの料理は、そのドームの環境に近い状態で出すことが大切にされる。トロピカルの器は温かく湿り気を残し、アークティックの器はよく冷やし、デザートの器は水気を飛ばして乾いた口当たりに仕上げる。一枚の皿の上に、温度も湿り気も違う六つの環境が並ぶことになる。'),
    P('食材は季節やドームの状態によって入れ替わる。同じ店で同じベルネアドーム盛りを頼んでも、訪れる時期によって中身が違うのはそのためである。')
  ]},'sec-eating');
  ins('belnea-dome-mori',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('セントラルの器は、きのこや木の実の土のような香りが中心で、全体の味の基準になる。テンペレートの器は穏やかで、初めての人にも食べやすい。トロピカルの器は香りが強く甘酸っぱい。デザートの器は、噛むと中から水分があふれる多肉の植物の食感が特徴である。'),
    P('アークティックの器は冷たく締まった培養肉の歯ごたえがあり、オーシャンの器は海藻のぬめりと培養魚肉のやわらかさ、潮の香りを持つ。六つを順に食べていくと、温度、香り、食感が大きく変わり、旅をしているような感覚になると言われる。')
  ]},'sec-eating');
  ins('belnea-dome-mori',{ id:'sec-origin', title:'由来', blocks:[
    P('もとは、ベルネアの研究者たちが各ドームで採れた食材を持ち寄り、一つの卓で食べ比べていた習慣だとされる。研究の場で「この環境の植物はこういう味だった」と報告し合う、観察記録の延長のような食事だった。'),
    P('その後、観光客にもドームの違いを伝えられる料理として器の形が整えられ、現在の盛り合わせになった。ベルネアの食堂では、ドームを巡った観光客が自分の観察と照らし合わせながら食べる姿がよく見られる。')
  ]});
  addTo('belnea-dome-mori','sec-eating',[ P('一つの器を食べ終えるごとに、口を休めるための白湯が出される店も多い。前の器の香りを残さず、次の器の味をまっさらな状態で確かめるためである。') ]);

  /* ---------------- 待機餅 ---------------- */
  ins('taiki-mochi',{ id:'sec-ingredients', title:'材料と作り方', blocks:[
    P('待機餅の生地は、もち米の粉と、ドームで育った植物の色素を練り合わせて作る。色素は空気に触れると少しずつ形を変える性質を持ち、その変化が色と食感の移り変わりを生む。'),
    P('どのドームの植物を使うかで、変わっていく色が違う。テンペレートの植物を使えば淡い若草色から深い緑へ、トロピカルの植物を使えば淡い桃色から濃い紅色へ移る。店ではいくつかの色の待機餅が並び、客は色の行き先を選んで買う。'),
    P('作りたてを密閉した包みに入れておけば、色の変化は止まる。包みを開けた瞬間から、餅の時間が動き出す。')
  ]},'sec-taste');
  addTo('taiki-mochi','sec-taste',[
    P('食感の移り変わりにも段階がある。出されてすぐは水分を多く含んでふるふるとやわらかく、しばらくすると表面に薄い膜ができて、噛むとぷつりと切れる。さらに待つと、全体がもっちりとして、よく伸びるようになる。'),
    P('どの段階がいちばん美味しいかは、人によって答えが違う。ベルネアでは、それを決めるのは食べる人の観察だと考えられている。')
  ]);
  ins('taiki-mochi',{ id:'sec-record', title:'食べごろの記録', blocks:[
    P('ベルネアの家庭では、待機餅を食べた時刻と、そのときの色と食感を記録する子どもが多い。同じ色の餅でも、その日の気温や湿り気によって変わる早さが違うため、記録を重ねるうちに「今日は早く変わる日だ」と読めるようになっていく。'),
    P('観察教育を受けて育ったベルネアの大人の中には、何十年分もの待機餅の記録を持っている人もいる。')
  ]});

  /* ---------------- 早飯プレート ---------------- */
  ins('hayameshi-plate',{ id:'sec-ingredients', title:'一枚の中身', blocks:[
    P('早飯プレートは、仕切りのある一枚の皿に、主菜、副菜、主食、小さな甘いものを並べた形が基本である。どの区画の料理も、箸でもフォークでも一度でつかめるように形が整えられている。'),
    { t:'table', headers:['区画','内容'], rows:[
      ['主菜','培養肉や培養魚肉の料理。骨や筋を取り除き、ひと口大に切ってある。'],
      ['副菜','色の違う野菜を数種類。噛みごたえの違うものを組み合わせ、飽きないようにしている。'],
      ['主食','小さく握った米や、ひと口大のパン。汁物はこぼれにくい、とろみのあるものが選ばれる。'],
      ['甘いもの','最後に口を整えるための小さな菓子。猫のいる食堂では、肉球クッキーが添えられることもある。']
    ]},
    P('皿の端には、その日の栄養の内訳が小さく表示される。研究者の中には、味よりも先にその表示を確認する人も多い。')
  ]},'sec-design');
  ins('hayameshi-plate',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('味付けは全体に穏やかで、主菜だけが少し濃い。強い香りの料理は避けられることが多い。食べ終えたあとに研究室へ戻るとき、匂いが残らないようにするためである。'),
    P('食感は、やわらかいもの、歯ごたえのあるもの、さくっとしたものが一枚の中に必ず入るように組まれている。短い時間で食べても、食事をしたという満足感が残るように設計されている。')
  ]},'sec-culture');
  ins('hayameshi-plate',{ id:'sec-eating', title:'食べ方', blocks:[
    P('早飯プレートは、決まった順番を持たない。手早く食べることが目的のため、どこから食べても栄養と満足感がそろうように作られている。食堂には、プレートを受け取ってから食べ終えるまでの平均時間が掲示されていることもある。'),
    P('ヒューバートでは、立ったまま食べられる台を備えた食堂も多い。一方で、休みの日に早飯プレートをわざとゆっくり食べることを、ささやかな贅沢と呼ぶ人もいる。')
  ]},'sec-culture');
  ins('hayameshi-plate',{ id:'sec-history', title:'由来', blocks:[
    P('ヒューバートの前身であるヒルロンドの時代から、研究者たちは食事の時間を短くする工夫を続けてきたと言われる。ヒューバートとなってから、完全栄養食の普及とともに、栄養を整えた一皿として現在の形にまとまった。'),
    P('名前の「早飯」は、正式な名前ではなく、食堂で使われていた呼び方がそのまま残ったものである。')
  ]},'sec-culture');

  /* ---------------- 肉球パンと猫のお菓子 ---------------- */
  ins('hubert-cat-sweets',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('肉球パンは、ふんわりとやわらかく、軽く押すと肉球のようにへこんでゆっくり戻る。この弾力を出すことが、パン職人の腕の見せどころとされる。桃色の肉球の部分には、ほんのり甘い果実のクリームが入っている。'),
    P('肉球クッキーは、さくっと軽い歯ざわりで、バターの香りが強い。肉球の部分だけを少し厚く焼き、食べたときにそこだけほろりと崩れるように作る店もある。'),
    P('猫のひげガムは、ほのかな甘さとさわやかな香りがある。一本ずつ引き抜くとき、細いのに切れずに長く伸びるところが楽しまれている。')
  ]},'sec-cats');
  ins('hubert-cat-sweets',{ id:'sec-make', title:'作り方', blocks:[
    P('肉球パンは、丸い生地に四つの小さな丸と一つの大きな丸を押し当てて形を作る。肉球の部分にだけ桃色の生地を重ね、焼き色がつかないよう火を使わない加熱で低い温度からじっくり焼き上げる。'),
    P('肉球クッキーの型は、店ごとに実在の猫の足から形を取っていることが多い。猫カフェで暮らす猫の肉球を写した型は、その猫の名前で呼ばれ、猫が代替わりしても型は残され続ける。')
  ]},'sec-cats');
  ins('hubert-cat-sweets',{ id:'sec-eating', title:'食べ方', blocks:[
    P('肉球パンは、猫カフェで猫を眺めながら食べるのが定番である。肉球クッキーは土産物として箱で買われることが多く、猫の日や猫祭りの限定品は、食べずに飾っておく人もいる。'),
    P('猫のひげガムは、一本ずつ引き抜いて食べる。何本続けて切らずに抜けるかを競う子どもたちの遊びもある。')
  ]},'sec-culture');

  /* ---------------- 歯車クッキー ---------------- */
  ins('gear-cookie',{ id:'sec-ingredients', title:'材料', blocks:[
    P('生地は小麦粉、バター、砂糖を基本とした、焼き縮みの少ない硬めの配合である。歯の先が欠けないよう、生地をよく寝かせてから型を抜く。'),
    P('二枚のうち一枚は、香ばしい焼き色をつけた濃い生地で、もう一枚は白っぽい淡い生地で作ることが多い。並べて噛み合わせたとき、二つの色の歯が交互に並んで見える。'),
    P('高級なものでは、歯車の中心に小さな軸の穴が開けられ、本物の歯車のように二枚を軸に通して回せるものもある。')
  ]},'sec-make');
  addTo('gear-cookie','sec-make',[
    P('型は時計職人が作ることもある。工房街の菓子店の中には、時計の部品を作るのと同じ工房で型を作らせている店もあり、型の精度が店の格を表すと言われる。'),
    P('焼き上がると、職人は二枚を一組ずつ実際に噛み合わせて確かめる。わずかでも引っかかるものは組から外され、工房の職人たちのおやつになる。')
  ]);
  ins('gear-cookie',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('濃い生地は香ばしく、ほろ苦さがある。淡い生地はバターの香りが強く、やさしい甘さである。どちらも硬めで、噛むとかりっと音がする。'),
    P('一枚ずつ食べても美味しいが、二枚を交互にかじると、苦さと甘さが噛み合うように感じられる。それもまた、このクッキーが二枚一組である理由だとされている。')
  ]},'sec-custom');

  /* ---------------- 灯籠鍋 ---------------- */
  ins('touro-nabe',{ id:'sec-ingredients', title:'具材', blocks:[
    P('具材は根菜と培養肉が中心で、長い時間煮込んでも崩れにくいものが選ばれる。大根や芋、人参などの根菜に、骨付きの培養肉を合わせるのが基本の形である。'),
    P('汁は、前の日の鍋の汁を少し残して足していく家も多い。こうして何年も続く汁は「種汁」と呼ばれ、鍋と同じように家の財産として扱われる。'),
    { t:'list', items:[
      '根菜：大根・芋・人参など。煮込むほど汁を吸ってやわらかくなる。',
      '培養肉：骨付きのものが好まれる。骨からうまみが出る。',
      '季節の具：寒い時期には葉物、収穫の時期にはきのこなどを加える。',
      '種汁：前の日の汁を残して足していく、家ごとの汁。'
    ]}
  ]},'sec-pot');
  ins('touro-nabe',{ id:'sec-make', title:'作り方', blocks:[
    P('朝のうちに具材を鍋に入れ、鍋の底の加熱装置をごく弱くして、夕方までゆっくり煮込む。窓越しに具材の色が変わっていくのを見て、煮え具合を判断する。'),
    P('灯籠鍋の灯りは、煮込みが進むにつれて色を変えるように作られている鍋が多い。火を使っていた時代に、灯籠の火の色で時間を知った名残だとされる。古い鍋ほど、その色の変わり方に癖があると言われる。')
  ]},'sec-taste');
  ins('touro-nabe',{ id:'sec-eating', title:'食べ方', blocks:[
    P('灯籠鍋は、鍋を食卓の中央に置き、家族で囲んで食べる。最初に汁だけを椀に取って飲み、その日の鍋の出来を確かめるのが習わしである。'),
    P('具材を食べ終えたあと、残った汁に米を入れて雑炊にする家も多い。ただし、種汁にする分だけは必ず鍋に残しておく。')
  ]},'sec-culture');
  ins('touro-nabe',{ id:'sec-history', title:'歴史', blocks:[
    P('灯籠鍋の起こりは、火を使って煮炊きしていた時代にさかのぼるとされる。灯籠の中に火を入れて鍋を温め、明かりと調理を一つの火でまかなっていたという言い伝えが残っている。'),
    P('火が禁忌となった後も、ユーレツェアの人々は鍋を手放さなかった。中の火を加熱装置と灯りに置き換えて使い続けたため、古い灯籠鍋の中には、火を入れていた時代の煤の跡が今も残っているものがある。')
  ]},'sec-culture');

  /* ---------------- 八都あられ ---------------- */
  ins('hachito-arare',{ id:'sec-make', title:'作り方', blocks:[
    P('もち米を蒸してつき、薄くのばして乾かしたものを小さく切り、火を使わない加熱で膨らませる。その後、都市ごとの味を絡めて仕上げる。'),
    P('八つの味は、それぞれの都市の工房が作っている。大手の店は八つの工房から味を集めて一つの箱に詰めるため、同じ箱の中でも、あられの大きさや形が都市ごとに少しずつ違う。それも八都あられの特徴とされている。')
  ]},'sec-flavors');
  ins('hachito-arare',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('どの味も、かりっと軽い歯ざわりが共通している。東京の醤油は香ばしさが強く、大阪のソースは甘さのあとに辛さが来る。札幌の昆布とバターはまろやかで、京都の抹茶と白味噌はほのかな苦みと甘みがある。'),
    P('名古屋の味噌はいちばん味が濃く、福岡の辛子の効いた魚卵の味はいちばん刺激が強い。箱の中で味の強さがばらばらなため、薄い味から濃い味へ進むのがよいとも、好きな順に食べればよいとも言われる。')
  ]},'sec-osaka');
  ins('hachito-arare',{ id:'sec-eating', title:'食べ方', blocks:[
    P('米菓の日には、家族や友人で集まって八つの味を食べ比べ、どの都市の味がいちばん好きかを話す。出身の都市の味を推す人が多く、ちょっとした言い争いになることもある。'),
    P('目を閉じて一粒ずつ口に入れ、どの都市の味かを当てる遊びもよく知られている。八つすべてを当てると、その年は運がよいとされる。')
  ]},'sec-culture');

  /* ---------------- 龍茶 ---------------- */
  ins('tatsu-cha',{ id:'sec-ingredients', title:'茶葉', blocks:[
    P('龍茶の茶葉は、早く味の出る若い葉と、ゆっくり味の出る、よく揉んだ葉を合わせて作られる。一杯目には若い葉の明るい色と香りが、二杯目にはよく揉んだ葉の濃い色とうまみが出る。'),
    P('二種類の葉の割合は茶店ごとに違い、どの店の龍茶がよいかは家ごとの好みで決まる。節目の席で使う茶店を、何代にもわたって変えない家も多い。')
  ]},'sec-meaning');
  ins('tatsu-cha',{ id:'sec-make', title:'淹れ方', blocks:[
    P('一杯目は、少しぬるめの湯で短く淹れる。二杯目は同じ茶葉に熱い湯を注ぎ、長めに待つ。一杯目を淹れた人が、二杯目も淹れるのが作法とされる。'),
    P('一杯目と二杯目は同じ器で飲む家と、白い器と黒い器を使い分ける家がある。白と黒の器を使う家では、二つの器を並べて置いたときの姿も、二つにして一つを表すものとされる。')
  ]},'sec-taste');
  ins('tatsu-cha',{ id:'sec-eating', title:'飲む場面', blocks:[
    { t:'table', headers:['節目','飲み方'], rows:[
      ['誕生','生まれた子の家族が飲む。子が大きくなってから、その日の龍茶の話を聞かせる。'],
      ['成人','本人が初めて自分で二杯を淹れ、家族に出す。'],
      ['婚礼','二人が一杯目と二杯目を分け合う。どちらがどちらを飲むかは家によって違う。'],
      ['葬儀','参列者が故人を送るために飲む。故人の席にも二杯が置かれる。']
    ]}
  ]},'sec-culture');

  /* ---------------- 仮説スープ ---------------- */
  ins('kasetsu-soup',{ id:'sec-ingredients', title:'材料', blocks:[
    P('仮説スープの材料は、版ごとに違う。記録に名前だけが残る食材は、似た性質を持つ現在の食材で置き換えられる。どの食材を何で置き換えたかは、メニューに注として書かれている。'),
    P('店によっては、同じ記録をもとにしていても解釈が違い、まったく別のスープになっていることもある。キューマでは、それぞれの店の仮説を飲み比べることも楽しみの一つになっている。')
  ]},'sec-version');
  ins('kasetsu-soup',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('仮説スープに決まった味はない。ある版はとろみが強く香草の香りが立ち、次の版ではさらりとした塩味のスープに変わる、ということも珍しくない。'),
    P('それでも多くの店の仮説スープには、根菜や豆を長く煮込んだ素朴なうまみがある。資料の少ない部分を、料理人が「当時の人々が手に入れやすかったもの」で埋めていくと、自然と似た味に近づいていくためだと言われる。')
  ]},'sec-eating');
  ins('kasetsu-soup',{ id:'sec-menu', title:'メニューの表示', blocks:[
    P('仮説スープのメニューには、版数のほか、もとにした記録の名前、確かな部分と推定した部分の区別が書かれている。推定の部分には印がつけられ、客はどこまでが記録どおりでどこからが仮説なのかを知った上で飲むことができる。'),
    { t:'info', items:[
      { label:'版数', value:'第何版かと、前の版との違い' },
      { label:'もとの記録', value:'参考にした資料の名前' },
      { label:'確かな部分', value:'記録に書かれていた材料や手順' },
      { label:'推定した部分', value:'印をつけて区別する' }
    ]}
  ]},'sec-culture');

  /* ---------------- 蒸気釜飯 ---------------- */
  ins('joki-kamameshi',{ id:'sec-ingredients', title:'釜と具材', blocks:[
    P('釜は、蒸気機関時代の様式を復元した厚手の小さな釜で、一つの釜で一人分を炊く。食べ終えた釜は駅で回収され、洗って再び使われる。釜を持ち帰りたい人には、別に買える小さな釜も用意されている。'),
    P('具材は駅ごとに違い、その駅の周りの街並みが再現している時代や、近くの工房、市場にちなんだものが入る。'),
    { t:'list', items:[
      '始発駅の釜飯：培養肉と根菜を甘辛く煮た、いちばん基本の釜飯。',
      '工場街の駅の釜飯：濃い味付けの肉がたっぷり入った、働く人向けの釜飯。',
      '港の駅の釜飯：培養魚肉と貝を使った、潮の香りの釜飯。',
      '終着駅の釜飯：季節の具材が入り、時期によって中身が変わる。'
    ]}
  ]},'sec-ekiben');
  ins('joki-kamameshi',{ id:'sec-make', title:'作り方', blocks:[
    P('研いだ米と出汁、具材を釜に入れ、復元厨房の蒸気の通り道に並べて炊き上げる。蒸気の勢いで一気に炊くため、炊き上がりまでの時間は短い。'),
    P('厨房では、蒸気の音と圧力の針を見ながら炊き加減を決める。釜の底のおこげの具合は、この加減で決まる。体験区の厨房は見学でき、炊き上がりの瞬間に一斉に湯気が上がる様子を見に来る観光客も多い。')
  ]},'sec-taste');
  ins('joki-kamameshi',{ id:'sec-eating', title:'食べ方', blocks:[
    P('蒸気釜飯は、車内で釜のふたを開け、湯気が立っているうちに食べるのがよいとされる。まず上の具材と米を食べ、最後に釜の底のおこげをこそげ取って食べる。'),
    P('全部の駅の釜飯をそろえる旅では、一日で回ろうとすると食べきれないため、何日かに分けて乗る人が多い。旅の記念に、釜の底に駅の印を押してもらうこともできる。')
  ]},'sec-culture');

  /* ---------------- 五線譜プレート ---------------- */
  ins('gosenfu-plate',{ id:'sec-ingredients', title:'料理の組み立て', blocks:[
    P('五線譜プレートに決まった食材はない。曲が先にあり、料理人はその曲の音の高さ、長さ、強さに合わせて、一つひとつの料理を組み立てていく。'),
    { t:'table', headers:['譜面','料理'], rows:[
      ['高い音','酸味のある果実、軽い野菜、泡立てたソースなど。'],
      ['低い音','煮込んだ培養肉、濃いソース、根菜など。'],
      ['長い音符','大きめの一品。ゆっくり味わう。'],
      ['短い音符','ひと口で食べられる小さな料理。'],
      ['休符','水や小さな果実。口を休める。'],
      ['強い音','香辛料や香りの強い料理。']
    ]}
  ]},'sec-score');
  ins('gosenfu-plate',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('一皿の中で、軽いものと重いもの、酸っぱいものと濃いものが曲の流れに沿って入れ替わる。食べ進めるうちに、口の中で味が上がったり下がったりする感覚がある。'),
    P('同じ曲を料理にしても、料理人が違えば味はまったく違う。オルガロンでは、同じ曲の五線譜プレートを別々の店で食べ比べる人もいる。')
  ]},'sec-eating');
  ins('gosenfu-plate',{ id:'sec-history', title:'由来', blocks:[
    P('オルガロンでは、生演奏付きの食事が古くから大切にされてきた。演奏者と料理人が、曲に合わせて料理を出す順番を決めているうちに、料理そのものを譜面に見立てて並べる店が現れたのが始まりとされる。'),
    P('現在では、新しい曲が作られると、その曲の五線譜プレートが同時に作られることもある。料理と曲を一緒に発表する音楽家もいる。')
  ]},'sec-culture');

  /* ---------------- 色のコース ---------------- */
  ins('iro-course',{ id:'sec-ingredients', title:'食材', blocks:[
    P('一皿を一つの色でそろえるため、料理人は色ごとに食材を集める。白なら米や根菜、白身の培養魚肉、赤なら果実や赤い野菜、緑なら葉物や香草というように、同じ色の食材だけで味の組み立てを考える。'),
    P('どうしても色の合わない食材は、色を移したソースや、色のついた生地で包むことで皿の色にそろえる。器もその色のものが使われ、皿全体が一つの色の面になるように盛りつけられる。')
  ]},'sec-order');
  addTo('iro-course','sec-taste',[
    P('赤い皿は甘味と酸味が中心になりやすく、緑の皿は香りとほろ苦さが中心になりやすい。黒や深い紫の皿には、うまみの強い料理が置かれることが多い。それでも、色から想像した味を裏切る皿をどこかに入れるのが、腕のある料理人だとされる。'),
    P('食感も色ごとに工夫される。白い皿の中に、なめらかなもの、ほろりと崩れるもの、歯ごたえのあるものが並び、同じ色の中で違いを感じられるようになっている。')
  ]);
  ins('iro-course',{ id:'sec-eating', title:'食べ方', blocks:[
    P('色のコースでは、皿が出されたとき、すぐには手をつけず、まず色を眺める時間が取られる。客は皿の色について短く言葉を交わしてから食べ始める。'),
    P('コースの最後に、料理人が客の席を回り、その日の色の順番に込めた意味を話す店もある。ただし、意味を語らずに客に考えさせる店の方が、オルガロンでは好まれる傾向がある。')
  ]},'sec-culture');

  /* ---------------- 黄金包み ---------------- */
  ins('ougon-tsutsumi',{ id:'sec-ingredients', title:'材料', blocks:[
    P('生地は小麦粉を練った薄い皮で、具は培養肉、海産物、甘い餡などさまざまである。仕上げに、食べられるよう加工された人工黄金の箔を、生地の外側へ一枚ずつ貼りつける。'),
    P('箔の貼り方は店ごとに違う。全体をすき間なく包む店もあれば、ひだの部分だけに貼って、生地の白と金色の対比を見せる店もある。')
  ]},'sec-pair');
  ins('ougon-tsutsumi',{ id:'sec-make', title:'作り方', blocks:[
    P('具を包んだ生地を、火を使わない加熱で蒸し上げる。蒸し上がった直後の、表面がまだしっとりしているうちに箔を貼る。乾いてからでは箔がうまくつかないため、手早さが求められる。'),
    P('白金包みは、薄い白い生地を何層にも重ねて包み、層の間に香りを閉じ込めるように蒸す。黄金包みよりも手間がかかり、作れる職人は多くない。')
  ]},'sec-taste');
  addTo('ougon-tsutsumi','sec-taste',[
    P('黄金包みの具は味が濃く、肉汁や甘い餡があふれるものが好まれる。白金包みは、層ごとに少しずつ違う香りが重なり、噛むたびに静かに味が変わっていく。')
  ]);
  ins('ougon-tsutsumi',{ id:'sec-eating', title:'食べ方', blocks:[
    P('黄金包みは、ひと口で食べるのがよいとされる。箔は口に入れるとすぐに溶けるため、かじって残すと、金色の部分が崩れてしまうからである。'),
    P('ヴォルグレンの店では、皿の照明を暗くして、黄金包みの金色だけが浮かび上がるように出すこともある。')
  ]},'sec-culture');

  /* ---------------- 賭けまんじゅう ---------------- */
  ins('kake-manju',{ id:'sec-ingredients', title:'材料と作り方', blocks:[
    P('まんじゅうは、ふっくらとした白い生地で餡を包み、火を使わない加熱で蒸し上げる。金貨入りのものも、そうでないものも、見た目と重さが変わらないよう、生地と餡の量が細かく調整されている。'),
    P('金貨は、食べられない包みにしっかりと収めてから餡の中に入れる。割ったときに必ず見えるよう、まんじゅうの中央に置くのが決まりである。')
  ]},'sec-coin');
  ins('kake-manju',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('生地はやわらかく、ほんのりと甘い。餡は黄金区域らしく、蜜を使った濃い甘さのものが多い。白金区域では、甘さを控えた白餡の賭けまんじゅうも売られている。'),
    P('味はどれも同じであるため、食べる人は味ではなく、割った瞬間を楽しむ。金貨が出なかった人も、まんじゅうそのものは美味しく食べられる、というのがこの菓子のよいところだとされる。')
  ]},'sec-eating');
  ins('kake-manju',{ id:'sec-sets', title:'数と組み合わせ', blocks:[
    { t:'table', headers:['組','使われる場面'], rows:[
      ['三個組','二人や三人で遊ぶ小さな組。土産物として最もよく売られる。'],
      ['六個組','家族や友人の集まりで使われる。'],
      ['十二個組','双輝祭やカジノの催しで使われる大きな組。当たる確率が低いぶん、引き当てたときの喜びも大きい。']
    ]},
    P('どの組でも、金貨は一つだけである。全員が同時に割るのが決まりで、先に割った人が出なかったからといって、残りの人の確率が上がることを喜ぶのは、無粋だとされる。')
  ]},'sec-culture');

  /* ---------------- 定刻ボックス ---------------- */
  ins('teikoku-box',{ id:'sec-box', title:'箱', blocks:[
    P('定刻ボックスの箱は、白い四角形で、側面に受け取る研究者の名前と届ける時刻が印字されている。中は仕切りで細かく分けられ、温かいものと冷たいものが混ざらないよう、区画ごとに温度が保たれている。'),
    P('食べ終えた箱は、決まった回収口に戻すと、アンドロイドが回収して洗浄する。同じ箱が何度も使われ、研究者の間では、箱の角の小さな傷で「これは前にも来た箱だ」と分かる人もいるという。')
  ]},'sec-content');
  ins('teikoku-box',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('味付けは、研究者ごとの好みと体調に合わせて調整される。基本は穏やかな味だが、長い実験の後には、少し塩気の強い料理が入れられることもある。'),
    P('研究棟では匂いの強い食べ物が好まれないため、香りは控えめである。季節の食材が入る日は、その食材の香りだけが箱を開けた瞬間にふわりと立つように工夫されている。')
  ]},'sec-outside');
  ins('teikoku-box',{ id:'sec-eating', title:'食べ方', blocks:[
    P('定刻ボックスは、届いた時刻に食べることが前提になっている。研究に没頭して手をつけずにいると、しばらくしてアンドロイドが様子を見に来る。それでも食べないと、次の箱の中身が少し食べやすいものに変わると言われている。'),
    P('研究者の中には、届く時刻を一日の区切りとして使い、箱が届くまでに一つの作業を終わらせることを目標にする人も多い。')
  ]},'sec-culture');

  /* ---------------- 雲綿 ---------------- */
  ins('kumowata',{ id:'sec-ingredients', title:'材料と作り方', blocks:[
    P('雲綿は、色をつけた糖を細い糸状にし、空気を多く含ませながら巻き取って作る。普通の綿菓子よりも糸が細く、空気の量が多いため、手に持つとほとんど重さを感じない。'),
    P('スカイラリスの店先では、職人が巻き取る様子を見ることができる。巻き取りの途中で空気の流れを変えることで、ふくらんだ積雲の形や、薄くのびた巻雲の形を作り分ける。')
  ]},'sec-eating');
  ins('kumowata',{ id:'sec-taste', title:'味・香り・食感', blocks:[
    P('口に入れた瞬間に溶け、軽い甘さと香りだけが残る。香りは店ごとに違い、果実、花、焼き菓子のような香りなどがある。'),
    P('色によって香りを変えている店も多く、朝焼けの色の雲綿は果実の香り、夜空の色の雲綿は深い甘い香りといったように、空の時間帯を香りで表している。')
  ]},'sec-eating');
  ins('kumowata',{ id:'sec-kinds', title:'雲の種類', blocks:[
    { t:'table', headers:['名前','特徴'], rows:[
      ['積雲','丸くふくらんだ形。最もよく売られる。'],
      ['巻雲','細く薄くのばした形。すぐに溶けるため、その場で食べる。'],
      ['夕焼け雲','橙と桃色を重ねた雲綿。外周展望リングの夕方の限定品。'],
      ['夜雲','深い青と紫の雲綿。都市の光を思わせる小さな粒がちりばめられている。']
    ]},
    P('種類の名前は店ごとに勝手につけられているため、同じ名前でも店によって形が違う。それを気にする人は、フーモラにはあまりいない。')
  ]},'sec-culture');

  /* ---------------- 氷室漬け ---------------- */
  ins('himuro-zuke',{ id:'sec-ingredients', title:'材料', blocks:[
    P('氷室漬けには、氷海漁で獲れた魚と、培養肉が使われる。魚は脂の多いものが好まれ、培養肉は赤身の塊が選ばれる。'),
    P('塩をした魚や肉を、香りづけの木の葉で包み、さらに布で巻いて保管庫に入れる。木の葉の種類は家ごとに違い、それが家の氷室漬けの香りになる。')
  ]},'sec-taste');
  ins('himuro-zuke',{ id:'sec-make', title:'作り方', blocks:[
    P('保管庫の中は、氷ブロックの並べ方によって、奥ほど冷たく、入り口に近いほどわずかに温度が高くなる。漬けたものは、最初は奥に置き、時間がたつにつれて少しずつ入り口側へ移していく。'),
    P('いつ、どの棚へ移すかは、家ごとに受け継がれている。急いで移すと味が浅くなり、移し忘れると硬くなりすぎる。ここでも、急がないことがいちばん大切だとされる。')
  ]},'sec-taste');
  addTo('himuro-zuke','sec-taste',[
    P('魚の氷室漬けは、ねっとりとした舌ざわりと、脂の甘みが特徴である。培養肉の氷室漬けは、噛むほどにうまみが出て、包んだ木の葉の香りがかすかに残る。')
  ]);
  addTo('himuro-zuke','sec-eating',[
    P('祝いの席では、何年も寝かせた氷室漬けが出される。年数の違うものを並べて食べ比べ、漬けた年の出来事を話すのが、チリルドの家庭の楽しみ方である。'),
    P('薄く切ったものを、温かい汁に一瞬だけくぐらせて食べる食べ方もある。冷たい身の内側が、少しだけやわらかくなる。')
  ]);

  /* ---------------- 煤干し肉 ---------------- */
  ins('susu-hoshiniku',{ id:'sec-make', title:'作り方', blocks:[
    P('塩をすり込んだ肉の塊を、ボイラー室の天井近くの梁に吊るす。ボイラーが動き続けるかぎり、熱と煙と煤が肉を包み続け、表面から少しずつ乾いていく。'),
    P('干し上がるまでには長い時間がかかる。ボイラーに近い梁ほど早く乾き、遠い梁ほどゆっくり乾くため、家では吊るす場所を変えながら、冬までに食べる分と、冬の間に食べる分とを作り分ける。')
  ]},'sec-fire');
  addTo('susu-hoshiniku','sec-taste',[
    P('噛み続けていると、煤の苦みの奥から、塩と肉のうまみがゆっくり出てくる。ひと切れを長い時間かけて噛むのが普通で、ガルヒューラの人々は、仕事をしながら口の中で煤干し肉を噛んでいることが多い。')
  ]);
  ins('susu-hoshiniku',{ id:'sec-eating', title:'食べ方', blocks:[
    P('煤干し肉は、刃物で薄く削いでそのまま噛むのが一般的である。硬すぎるものは、湯に浸してやわらかくし、汁ごと食べる。'),
    P('食事の時間を決めて食卓を囲むよりも、それぞれが必要なときに、ボイラー室から肉を下ろして削っていく。誰がどれだけ食べたかは、梁に残った肉の大きさで分かる。')
  ]},'sec-life');
  ins('susu-hoshiniku',{ id:'sec-history', title:'由来', blocks:[
    P('煤干し肉の作り方は、ガルヒューラのボイラー集落が受け継いだフロスタン文明の暮らしにさかのぼるとされる。長く厳しい冬を越えるために、ボイラーの熱を暖房にも保存にも使い切る工夫の一つだった。'),
    P('他国で火が禁忌となった後も、ガルヒューラではボイラーの火が消えなかった。そのため煤干し肉は、作り方を変えることなく、今も同じように作られ続けている。')
  ]},'sec-life');
})();
(function(){ [['iro-course','sec-taste'],['ougon-tsutsumi','sec-taste']].forEach(function(p){
  var a=ARTICLES.filter(function(x){return x.id===p[0];})[0]; if(!a) return;
  a.sections.forEach(function(s){ if(s.id===p[1] && s.title==='味') s.title='味・香り・食感'; }); }); })();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（3）
   獣喰い：食べられる骨・豪快食・半ナマ。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  var a = ARTICLES.filter(function(x){return x.id==='kemonogui';})[0]; if(!a) return;
  function P(t){ return { t:'p', text:t }; }
  function idx(id){ var i=-1; a.sections.forEach(function(s,k){ if(s.id===id) i=k; }); return i; }
  /* 食べ方の「骨付き」を書き換える */
  var how = a.sections[idx('sec-howto')];
  if(how){ how.blocks.forEach(function(b){ if(b.t==='list'){ b.items = b.items.map(function(t){
    return t.indexOf('骨付き：')===0 ? '骨付き：骨の形まで再現した肉。骨のまわりの肉を噛み取るのが醍醐味とされる。骨まで食べられるように作られたものもある（後述）。' : t; }); } }); }
  if(idx('sec-bone')<0){
    a.sections.splice(idx('sec-challenge'),0,{ id:'sec-bone', title:'食べられる骨', blocks:[
      P('再現肉の骨付き肉には、骨まで食べられるように調整された種類がある。骨の形と固さの感触は残しながら、中を細かな空洞の多い構造にして、強く噛めば砕けるようにしたものである。'),
      P('噛み砕くとき、ばりっという音と、骨の髄の濃いうまみが口に広がる。肉を噛みちぎり、最後に骨まで噛み砕いて何も残さない食べ方は、獣喰いの中でも特に「獣らしい」とされ、牙を持つアニマルボディの人々に好まれている。'),
      { t:'table', headers:['種類','特徴'], rows:[
        ['ふつうの骨付き','骨は再現した形だけで、食べるのは周りの肉。骨は残す。'],
        ['軟骨仕立て','骨を軟骨に近い固さにしたもの。こりこりとした歯ざわりで、初めての人にも食べやすい。'],
        ['噛み砕き骨','本物の骨に近い固さを残し、強く噛むと砕けるもの。顎に自信のある人向け。']
      ]},
      P('食べられる骨は、獣チャレンジでも使われる。骨まで食べきらなければ完食と認めない店もあり、最も難しい挑戦の一つになっている。')
    ]});
  }
  if(idx('sec-goukai')<0){
    a.sections.splice(idx('sec-fire'),0,{ id:'sec-goukai', title:'豪快食と半ナマ', blocks:[
      P('獣喰いが広まると、生の肉は苦手だが、かぶりつく豪快さは楽しみたいという人々も現れた。そうした人々のあいだで流行しつつあるのが「豪快食」である。肉を焼いたり煮たりはするが、切り分けずに塊のまま、手で持ってかぶりつく。'),
      P('豪快食の代表が、食べられる骨をつけた骨付き肉である。もとは獣喰いのために作られた食べられる骨を、焼いて食べる肉にもつけて売り出したところ、生肉の苦手な人々の間で人気になった。今では肉屋や食料品店でも、焼く用の骨付き肉として並んでいる。'),
      P('生と加熱のあいだを狙ったものもある。外側だけを火を使わない加熱で短く強く焼いてカリッとさせ、中は生のまま残した肉は「半ナマ肉」と呼ばれる。厚く切った塊肉で作る「半ナマステーキ」と、ひき肉をまとめて同じように焼いた「半ナマハンバーグ」がよく知られ、どちらも外の香ばしさと中のひんやりとした生の食感の差が楽しまれている。半ナマステーキは、獣喰い屋でも豪快食の店でも、ナイフを使わずにかぶりつけるよう、骨付きで出されることが多い。'),
      { t:'table', headers:['食べ方','肉','特徴'], rows:[
        ['獣喰い（素）','生','味付けなし。獣チャレンジに使われる。'],
        ['獣喰い（味付き）','生','塩や香草を軽くつける。'],
        ['半ナマ肉（ステーキ・ハンバーグ）','外は焼き、中は生','外はカリッと、中は生。獣喰いの入口として選ばれる。'],
        ['豪快食','焼く・煮る','塊のまま、骨付きのまま手で持ってかぶりつく。生肉が苦手な人向け。']
      ]},
      P('獣喰いを好む人々の中には、豪快食を「火の通った獣喰いはもう獣喰いではない」と言う人もいる。それでも、獣喰い屋の多くは豪快食や半ナマも品書きに並べており、連れの中に生肉の苦手な人がいても一緒に入れる店として喜ばれている。')
    ]});
  }
  var fs = a.sections[idx('sec-fire')];
  if(fs && !fs.blocks.some(function(b){return b.text && b.text.indexOf('豪快食')>=0;})){
    fs.blocks.push(P('一方で、豪快食や半ナマは、整えられた加熱の技術を使いながら、切り分けずにかぶりつくという獣喰いの作法だけを残している。何を残し、何をやめるのか。その選び方の違いが、獣喰いから派生した食べ方を分けている。'));
  }
  var ov = a.sections[idx('sec-overview')];
  if(ov){ ov.blocks.forEach(function(b){ if(b.t==='info' && !b.items.some(function(i){return i.label==='加熱する派生';})) b.items.push({label:'加熱する派生', value:'豪快食・半ナマステーキ・半ナマハンバーグ'}); }); }
  a.updated = UPDATED;
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（4）
   丸ごと魚（豪快食の派生）と、魚の扱い（殺してよいとされる・養殖／漁／釣りが残る）。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function sec(a,id){ return a ? (a.sections||[]).filter(function(s){return s.id===id;})[0] : null; }
  function P(t){ return { t:'p', text:t }; }

  /* ---- 獣喰い：丸ごと魚 ---- */
  var k = art('kemonogui');
  if(k && !sec(k,'sec-fish')){
    var i=-1; k.sections.forEach(function(s,n){ if(s.id==='sec-goukai') i=n; });
    k.sections.splice(i+1,0,{ id:'sec-fish', title:'丸ごと魚', blocks:[
      P('豪快食の流行に乗って、魚を頭から尾まで丸ごと食べる「丸ごと魚」も流行しつつある。使われるのは、骨も頭もひれも食べられるように調整して、魚の形のまま育てた培養魚である。'),
      P('肉の獣喰いが塊にかぶりつくのに対し、丸ごと魚は切り身にも塊にもせず、一匹をそのまま手に取って食べる。焼いても生でも食べられるように作られており、焼けば皮と骨が香ばしく、生ならねっとりとした身と、こりこりとした骨の歯ざわりが楽しめる。'),
      P('なかでも有名になってきているのが、大きなサーモンやマグロの丸ごと魚にかぶりつく食べ方である。ひとりでは到底食べきれない大きさのため、数人で一匹を囲み、頭の側と尾の側から同時にかぶりついていく。食べ進むうちに真ん中で顔を合わせる様子が、SNSで盛んに共有されている。'),
      { t:'table', headers:['種類','食べ方'], rows:[
        ['小魚','頭から一口で。焼いたものは、おやつ代わりにもなる。'],
        ['サーモン','生のまま、皮ごとかぶりつく。脂の甘さと、やわらかい骨の歯ざわり。'],
        ['マグロ','大勢で一匹を囲む。部位ごとに味が変わり、かぶりつく場所を選ぶのも楽しみとされる。']
      ]},
      P('寄生虫の心配がない培養魚だからこそ、大きな魚を生のまま丸ごと口にできる。旧来の生の魚には、食べる前の下処理が欠かせなかった。')
    ]});
    k.sections.forEach(function(s){ if(s.id==='sec-overview'){ s.blocks.forEach(function(b){ if(b.t==='info'){ b.items.forEach(function(it){ if(it.label==='加熱する派生' && it.value.indexOf('丸ごと魚')<0) it.value += '・丸ごと魚'; }); } }); } });
    k.updated = UPDATED;
  }

  /* ---- 工業生産畜産：魚の扱い ---- */
  var lv = art('industrial-livestock');
  if(lv && !sec(lv,'sec-fish')){
    var j=-1; lv.sections.forEach(function(s,n){ if(s.id==='sec-animal') j=n; });
    lv.sections.splice(j+1,0,{ id:'sec-fish', title:'魚の扱い', blocks:[
      P('培養肉の普及によって、食用の動物を殺して肉を得ることは一般的ではなくなった。一方で、魚に対する受け止め方は肉ほど厳しくない。動物を殺すのはまずいという感覚が広まった後も、魚は殺して食べてもよいものとして、多くの人に受け入れられている。'),
      P('そのため、魚の養殖、漁、釣りは今も各地に残っている。タスメニオの漁業やチリルド・アイルツアの氷海漁のように、海とともに暮らしてきた国々では、獲った魚を食べることは伝統そのものである。釣りは趣味としても広く楽しまれている。'),
      P('もっとも、食卓に並ぶ魚の多くは、肉と同じく培養魚である。安く安定して手に入り、骨や皮の固さまで調整できるためである。生きた魚を獲って食べることは、味のためというより、海や川と関わる文化として続いている。'),
      P('ベルネアは例外で、肉も魚もすべて培養によるものを食べる。生物を殺して食べる文化が一般的ではないこの国では、魚もまた共に生きる生命の一つとして扱われている。')
    ]});
    lv.related = lv.related||[]; ['rainbow-fish','kemonogui','tasumenio','chiriludo-ailtsua'].forEach(function(r){ if(lv.related.indexOf(r)<0) lv.related.push(r); });
    lv.updated = UPDATED;
  }

  /* ---- 食文化：味と流行 ---- */
  var fc = art('food-culture'), ft = sec(fc,'sec-taste');
  if(ft && !ft.blocks.some(function(b){return b.text && b.text.indexOf('丸ごと魚')>=0;})){
    ft.blocks.push(P('獣喰いからは、焼いた肉を塊や骨付きのままかぶりつく豪快食や、骨も頭も食べられる培養魚を一匹そのまま食べる丸ごと魚も生まれ、流行しつつある。'));
  }

  /* ---- レインボーフィッシュ：魚の養殖は他にも残っているため表現を合わせる ---- */
  var rf = art('rainbow-fish');
  if(rf){
    var swaps = [
      ['そのため、この魚に関しては今も生きた個体を育てる養殖が続けられており、「培養肉が主流の世界でも、なお生きた魚として残っている数少ない存在」として知られている。',
       'そのため、ほかの多くの魚には培養魚という選択肢があるのに対し、この魚は生きた個体を育てる養殖でしか手に入らない。「培養では作れず、生きた魚からしか得られない数少ない存在」として知られている。'],
      ['培養技術が発達した現在でも、この魚だけは生きた姿のまま育てて味わうものとして、特別な位置を保ち続けている。',
       '培養技術が発達した現在でも、この魚だけは培養で代わりを作ることができず、生きた姿のまま育てて味わうしかないものとして、特別な位置を保ち続けている。']
    ];
    rf.sections.forEach(function(s){ s.blocks.forEach(function(b){ swaps.forEach(function(w){ if(b.text===w[0]) b.text=w[1]; }); }); });
    rf.related = rf.related||[]; if(rf.related.indexOf('industrial-livestock')<0) rf.related.push('industrial-livestock');
  }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（5）
   肉と魚の違い（なぜ魚は殺してよいとされるのか）／丸ごと魚の骨や硬いところ。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }

  var lv = art('industrial-livestock');
  if(lv && !lv.sections.some(function(s){return s.id==='sec-meat-fish';})){
    var j=-1; lv.sections.forEach(function(s,n){ if(s.id==='sec-fish') j=n; });
    lv.sections.splice(j+1,0,{ id:'sec-meat-fish', title:'肉と魚の違い', blocks:[
      P('同じ動物でありながら、なぜ肉は殺してはいけないもので、魚は殺してもよいものなのか。この違いに、はっきりとした決まりがあるわけではない。法で定められた線ではなく、人々の感覚として広まったものである。理由としては、主に次のようなことが挙げられる。'),
      { t:'table', headers:['理由','内容'], rows:[
        ['育てて殺すか、獲るか','従来の畜産は、人が動物を生まれたときから育て、最後に殺して肉にする仕組みだった。培養肉が置き換えたのは、この仕組みそのものである。魚の多くは海や川から獲ってくるもので、人が命を最初から最後まで握っているという感覚が薄かった。'],
        ['生き延びるための漁','再始動期から、海の近くで暮らす人々は漁によって生き延びてきた。タスメニオの海民のように、漁は暮らしと文化そのものであり、「海の恵みをいただく」という言い方が今も残っている。'],
        ['伝わりにくさ','鳴き声を上げず、表情も読み取りにくい魚は、獣に比べて痛みや怖れが人に伝わりにくい。人々の受け止め方の差は、この伝わりにくさから来ているとも言われる。']
      ]},
      P('こうした違いは、どれも「人がどう感じるか」によるもので、魚が獣より苦しまないと分かっているわけではない。ベルネアのように魚も殺さない国があるほか、研究者や一部の人々の中には、魚だけを例外とすることに疑問を持つ人もいる。'),
      P('それでも多くの人にとって、肉は「殺さずに作るもの」になり、魚は「獲ってもよいもの」のまま残った。釣った魚を丸ごと焼いて食べることと、獣を殺さないことは、未来世界の多くの食卓で、矛盾なく並んでいる。'),
      { t:'quote', text:'獣は殺さない。魚は、海からいただく。' }
    ]});
    lv.updated = UPDATED;
  }

  var k = art('kemonogui');
  if(k){ k.sections.forEach(function(s){
    if(s.id!=='sec-fish' || s.blocks.some(function(b){return b.text && b.text.indexOf('パリポリ')>=0;})) return;
    var t=-1; s.blocks.forEach(function(b,n){ if(b.t==='table') t=n; });
    s.blocks.splice(t,0,
      P('丸ごと魚のいちばんの楽しみは、骨や硬いところまで食べられることにある。背骨や小骨、ひれ、頭の硬い部分は、刺さったり口に残ったりしないよう、噛むと細かく砕ける構造に調整されている。'),
      P('焼いた丸ごと魚の骨やひれは、パリポリとした軽い歯ざわりで香ばしく、身よりもそこが好きだという人も多い。生のままでは、骨はこりこりと、頭の軟らかい部分はとろりとしている。ひと口ごとに違う食感が続くことが、切り身では味わえない丸ごと魚の美味しさだとされる。')
    );
    k.updated = UPDATED;
  }); }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（6）
   培養肉の味の設計（霜降りなどを細かく決められる）。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var lv = art('industrial-livestock');
  if(lv && !lv.sections.some(function(s){return s.id==='sec-design';})){
    var j=-1; lv.sections.forEach(function(s,n){ if(s.id==='sec-production') j=n; });
    lv.sections.splice(j+1,0,{ id:'sec-design', title:'美味しさを設計する', blocks:[
      P('生きた動物の肉は、その動物の体調、体の大きさ、育った環境、食べてきたものによって味が変わる。同じ種類の動物でも、一頭ごとに出来が違い、思いどおりの肉が手に入るとは限らなかった。'),
      P('培養肉は、こうしたことに左右されない。生き物の都合ではなく、美味しさだけを目指して作ることができる。脂の入り方、柔らかさ、筋の量、香りまでを細かく決められるため、同じ注文をすれば、いつでも同じ肉が届く。'),
      { t:'table', headers:['決められること','例'], rows:[
        ['霜降り','霜降りの多い肉、少ない肉、赤身だけの肉。脂の筋の細かさまで指定できる。'],
        ['脂の質','口の中ですぐ溶ける脂、噛むと甘みが出る脂など。'],
        ['柔らかさ','箸で切れるほど柔らかい肉から、噛みごたえのある肉まで。'],
        ['筋','煮込み向けに筋を残す、薄切り向けに筋をなくす、など。'],
        ['香り','肉らしい香りを強くする、あるいは抑える。']
      ]},
      P('飲食店では、料理に合わせて肉を指定するのが当たり前になっている。焼き料理には霜降りの多い肉、煮込みには筋を残した肉、カルパッチョには薄く切っても崩れない柔らかい肉というように、一皿ごとに最も合う肉が選ばれる。家庭向けの店でも、霜降りの度合いを何段階かから選んで買うことができる。'),
      P('一方で、あえてこの調整をしない肉もある。もとの動物の筋や血の味、匂いをそのまま再現した再現肉は、獣喰いのために好んで選ばれている。思いどおりの美味しさを作れる世界で、思いどおりにならない味をわざわざ求める人々もいる。')
    ]});
    lv.related = lv.related||[]; ['carpaccio'].forEach(function(r){ if(lv.related.indexOf(r)<0) lv.related.push(r); });
    lv.updated = UPDATED;
  }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（7）
   獣喰いを料理記事（宗教・文化）へ移し、豪快食（半ナマ・丸ごと魚）を独立した料理記事にする。
   ============================================================================ */
(function(){
  var UPDATED = '2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var k = art('kemonogui'); if(!k) return;
  k.cat = 'culture'; k.collection = ['recipe'];
  function take(id){ var s=null; k.sections = k.sections.filter(function(x){ if(x.id===id){ s=x; return false; } return true; }); return s; }
  var goukai = take('sec-goukai'), fish = take('sec-fish');
  if(!art('goukai-shoku') && goukai){
    var gp = goukai.blocks.filter(function(b){return b.t==='p';});
    var gt = goukai.blocks.filter(function(b){return b.t==='table';})[0];
    var fs = k.sections.filter(function(s){return s.id==='sec-fire';})[0];
    var firePara = fs ? fs.blocks.filter(function(b){return b.text && b.text.indexOf('豪快食')>=0;})[0] : null;
    if(fs && firePara) fs.blocks = fs.blocks.filter(function(b){return b!==firePara;});
    ARTICLES.push({
      id:'goukai-shoku', cat:'culture', collection:['recipe'], title:'豪快食',
      aliases:['豪快食い','半ナマ','半ナマ肉','半ナマステーキ','半ナマハンバーグ','丸ごと魚'], updated:UPDATED,
      lede:'焼いたり煮たりした肉を、切り分けずに塊や骨付きのまま手で持ってかぶりつく食べ方。生肉が苦手な人のための獣喰いとして広まりつつあり、外だけを焼いた半ナマや、骨も頭も食べられる培養魚を一匹そのまま食べる丸ごと魚も生まれている。',
      sections:[
        { id:'sec-overview', title:'概要', blocks:[
          gp[0],
          { t:'info', items:[
            { label:'読み', value:'ごうかいしょく' },
            { label:'もとになった食べ方', value:'獣喰い（ベルネア発祥）' },
            { label:'状況', value:'流行しつつある' },
            { label:'肉', value:'焼く・煮る／外だけ焼く（半ナマ）' },
            { label:'主な料理', value:'骨付き肉・半ナマステーキ・半ナマハンバーグ・丸ごと魚' },
            { label:'作法', value:'切り分けず、手で持ってかぶりつく' }
          ]}
        ]},
        { id:'sec-bone', title:'骨付き肉', blocks:[
          gp[1],
          P('骨付き肉の骨は、獣喰いと同じく、ふつうの骨、軟骨仕立て、噛み砕き骨から選べる。焼いた軟骨仕立ての骨はこりこりと香ばしく、骨まで食べきる人も多い。'),
          P('肉の部分は、培養肉らしく霜降りや柔らかさを選んで作られる。獣喰いの再現肉とは違い、豪快食の骨付き肉は、かぶりついたときに美味しいことがいちばんに考えられている。')
        ]},
        { id:'sec-hannama', title:'半ナマ', blocks:[
          gp[2],
          P('半ナマは、外側だけを短く強く焼くことが大切で、中まで熱が通ると半ナマではなくなる。火を使わない加熱技術の中でも、表面だけを一瞬で焼き固める調理器が使われ、家庭向けの小さなものも売られている。'),
          P('生肉が苦手な人が、半ナマで生の食感に慣れ、やがて獣喰いへ進むこともある。そのため獣喰い屋では、半ナマが入口の料理として品書きの最初に置かれていることが多い。')
        ]},
        fish,
        { id:'sec-taste', title:'味・香り・食感', blocks:[
          P('骨付き肉は、焼いた表面の香ばしさと、かぶりついたときにあふれる肉汁が中心になる。切り分けた肉よりも肉汁が逃げにくく、同じ肉でも塊のまま食べる方が美味しいと言う人は多い。'),
          P('半ナマは、外のカリッとした焼き目と、中のひんやりとした生の身の差を楽しむ料理である。半ナマハンバーグは、ひき肉の甘みが生のまま残り、外の香ばしさと口の中で混ざり合う。'),
          P('丸ごと魚は、身のやわらかさ、皮の香ばしさ、骨やひれのパリポリとした歯ざわりが、ひと口ごとに入れ替わる。')
        ]},
        { id:'sec-eating', title:'食べ方', blocks:[
          P('豪快食では、ナイフや箸で切り分けず、手で持ってかぶりつく。店では手を拭く布や、手を洗う小さな器が卓に置かれている。家庭では、休みの日や集まりの日に、ふだんの食事とは違う楽しみとして作られることが多い。'),
          P('大きな骨付き肉や大きな魚は、数人で一つを囲んで食べることもある。誰がどこからかぶりつくかを決めるのも、楽しみの一つになっている。')
        ]},
        { id:'sec-kemonogui', title:'獣喰いとの関係', blocks:[
          gt,
          gp[3],
          P('豪快食や半ナマは、整えられた加熱の技術を使いながら、切り分けずにかぶりつくという獣喰いの作法だけを残している。何を残し、何をやめるのか。その選び方の違いが、獣喰いと、そこから派生した食べ方を分けている。')
        ].filter(Boolean)},
        { id:'sec-culture', title:'食文化として', blocks:[
          P('未来世界の料理は、火を使わない加熱で丁寧に整えられ、肉の霜降りまで思いどおりに作れる。豪快食は、その整った料理を、あえて行儀悪く食べることを楽しむものだと言える。'),
          P('獣喰いほど過激ではないぶん、年齢や好みを問わず楽しめる食べ方として、これから広がっていくと見られている。'),
          { t:'quote', text:'切らずに、かぶりつけ。' }
        ]}
      ].filter(Boolean),
      related:['kemonogui','industrial-livestock','food-culture','carpaccio','fire-alternatives','belnea','rainbow-fish','social-media']
    });
  }
  /* 獣喰いには派生の案内だけ残す */
  if(!k.sections.some(function(s){return s.id==='sec-derived';})){
    var ci=-1; k.sections.forEach(function(s,n){ if(s.id==='sec-challenge') ci=n; });
    k.sections.splice(ci+1,0,{ id:'sec-derived', title:'派生した食べ方', blocks:[
      P('獣喰いの流行から、生肉が苦手な人々のための「豪快食」が生まれた。焼いた肉を塊や骨付きのままかぶりつく食べ方で、外だけを焼いた半ナマステーキや半ナマハンバーグ、骨も頭も食べられる培養魚を一匹そのまま食べる丸ごと魚も、ここから広まりつつある。詳しくは豪快食の項目を参照。')
    ]});
  }
  k.sections.forEach(function(s){ if(s.id==='sec-overview') s.blocks.forEach(function(b){ if(b.t==='info') b.items.forEach(function(it){ if(it.label==='加熱する派生') it.value='豪快食（半ナマ・丸ごと魚など）'; }); }); });
  k.related = k.related||[]; if(k.related.indexOf('goukai-shoku')<0) k.related.unshift('goukai-shoku');
  ['industrial-livestock','food-culture','rainbow-fish'].forEach(function(id){ var a=art(id); if(a){ a.related=a.related||[]; if(a.related.indexOf('goukai-shoku')<0) a.related.push('goukai-shoku'); } });
  /* 食文化の郷土料理の表 */
  var fc=art('food-culture'); if(fc){ fc.sections.forEach(function(s){ if(s.id!=='sec-regional') return; s.blocks.forEach(function(b){ if(b.t!=='table') return;
    [['獣喰い','ベルネア（現在は各地）','再現肉を生のまま塊でかぶりつく。現在流行中。'],['豪快食','各地','焼いた肉や丸ごとの魚を、切らずにかぶりつく。流行しつつある。']].forEach(function(r){ if(!b.rows.some(function(x){return x[0]===r[0];})) b.rows.push(r); }); }); }); }
  k.updated = UPDATED;
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（8）
   未来技術8本：立体映像／香りと味の記録／睡眠技術／動物翻訳機／重力制御／外骨格／光学迷彩／記憶映写
   ============================================================================ */
(function(){
  var U = '2026.10.27';
  function P(t){ return { t:'p', text:t }; }
  function I(items){ return { t:'info', items:items.map(function(x){ return { label:x[0], value:x[1] }; }) }; }
  function T(h, rows){ return { t:'table', headers:h, rows:rows }; }
  function L(items){ return { t:'list', items:items }; }
  function Q(t){ return { t:'quote', text:t }; }
  function S(id, title, blocks){ return { id:id, title:title, blocks:blocks }; }

  var NEW = [

  /* ---------------- 立体映像 ---------------- */
  { id:'hologram', cat:'tech', title:'立体映像', aliases:['ホログラム'], updated:U,
    lede:'空間に光で像を描き、装置を持たない人にも同じように見える映像技術。街の案内、競技の灯、ゲーム、通話、芸術まで、未来世界の景色のあちこちに使われている。ニューロシンクの視界表示とは違い、そこにいる全員が同じものを見る。',
    sections:[
      S('sec-overview','概要',[
        P('立体映像は、空間の一点に光を集めて像を結ばせ、何もない場所に立体的な映像を浮かび上がらせる技術である。画面や眼鏡を必要とせず、その場にいる人なら誰でも、どの方向からでも同じ映像を見ることができる。'),
        P('未来世界では、ニューロシンクによって視界へ情報を重ねて表示することもできる。しかしそれは本人にしか見えない。立体映像は本物の光でできているため、ニューロシンクを使わない人にも、子どもにも、動物にも同じように見える。この「みんなに同じものが見える」ことが、立体映像の最大の役割になっている。'),
        I([['英名','Hologram'],['分類','映像・光学技術'],['見える人','その場にいる全員'],['主な用途','案内・表示・競技・ゲーム・通話・芸術・展示']])
      ]),
      S('sec-compare','ニューロシンクの表示との違い',[
        T(['','立体映像','ニューロシンクの視界表示'],[
          ['見える人','その場にいる全員','装着している本人だけ'],
          ['しくみ','空間に本物の光を集めて像を作る','神経へ伝わる感覚情報に情報を足す'],
          ['向いている用途','案内、看板、催し、共有したい映像','個人向けの通知、道案内、検索結果'],
          ['苦手なこと','明るい屋外ではやや見えにくい','他人と同じものを見ること']
        ]),
        P('このため、公共の場の案内や看板、危険の知らせなど、誰にでも伝わる必要のある表示には立体映像が使われ、個人の情報にはニューロシンクが使われる、という使い分けが定着している。')
      ]),
      S('sec-city','街の中の立体映像',[
        P('街を歩くと、店の看板、交差点の案内、転送港の行き先表示など、多くの立体映像が目に入る。建物そのものに装飾を加えるよりも、立体映像で装いを変える方が手軽なため、季節や催しに合わせて街の見た目を一晩で変えることもできる。'),
        P('一方で、立体映像の看板が増えすぎて景色が見えにくくなった街もあり、多くの都市では、立体映像を出してよい高さや明るさ、時間が決められている。夜になると、住宅地では看板の立体映像がいっせいに暗くなる。')
      ]),
      S('sec-fire','光の炎',[
        P('火が禁忌とされる未来世界では、炎の姿も立体映像で表されることが多い。世界スポーツの日の競技の灯や、催しの篝火、家庭の暖炉の飾りなどは、熱を持たない光の炎である。'),
        P('光の炎は、燃え広がらず、煙も出ない。それでも人々は、揺らめく光を見て、火の記憶を思い出す。火の代わりとなる技術については、火の代替の項目も参照。')
      ]),
      S('sec-uses','さまざまな用途',[
        T(['分野','使われ方'],[
          ['ゲーム','通常型ゲームの画面として、机の上や部屋の中に立体の盤面やキャラクターを映す。'],
          ['スポーツ観戦','遠くの競技場の試合を、家の中に縮小して映す。選手を好きな角度から見られる。'],
          ['通話','相手の姿を等身大で映して話す。離れて暮らす家族の食卓に、相手の姿を座らせることもある。'],
          ['展示','キューマの博物館などで、失われた建物や道具を元の姿で映す。'],
          ['芸術','オルガロンでは、光そのものを素材にした立体映像の作品が多く作られている。'],
          ['医療・教育','身体の内部や生き物の構造を、拡大して立体で見せる。']
        ])
      ]),
      S('sec-limit','技術の限界',[
        P('立体映像は光でできているため、触れることはできない。手を入れれば、そのまま通り抜ける。手で触れた感覚を伴う映像は、ニューロシンクの感覚情報補助と組み合わせて作られる。'),
        P('光で形を作るのではなく、実際に物体を形作る技術としては、ヒューバート独自のユーティリティフォグがある。こちらは分子マシンが実際に集まって形を作るため触れることができるが、立体映像とはまったく別の技術である。'),
        P('また、強い日差しの下では像が薄く見えやすく、屋外の大きな立体映像には、天気に合わせて明るさを変える仕組みが組み込まれている。')
      ]),
      S('sec-culture','社会と立体映像',[
        P('立体映像の普及によって、「誰かと同じものを見る」ことの価値が改めて意識されるようになった。ニューロシンクによって一人ひとりが別々の情報を見るようになった社会で、立体映像は人々が同じ景色を共有するための技術でもある。'),
        Q('同じ光を、同じ場所で見る。それだけのことが、ときどき特別になる。')
      ])
    ],
    related:['neuro-sync','future-games','sports','fire-alternatives','utility-fog','fire-taboo','orgaron','kyuma']
  },

  /* ---------------- 香りと味の記録 ---------------- */
  { id:'scent-taste-record', cat:'tech', title:'香りと味の記録', aliases:['香り記録','味の記録','香りの記録'], updated:U,
    lede:'料理や花、場所の香りと味を読み取ってデータにし、保存したり、人に送ったり、あとで再現したりする技術。SNSで料理を「味ごと」共有する文化や、亡くなった人の手料理の味を残す習慣を生んだ。',
    sections:[
      S('sec-overview','概要',[
        P('香りと味の記録は、食べ物や場所に含まれる香りの成分と味の成分を読み取り、データとして保存する技術である。保存したデータは、あとで再現したり、ほかの人に送ったりすることができる。'),
        P('写真や映像で残せるのは見た目と音だけだった。香りと味を記録できるようになったことで、人々は「どんな料理だったか」だけでなく、「どんな味だったか」を残せるようになった。'),
        I([['分類','感覚情報技術・食品技術'],['記録するもの','香りの成分・味の成分・温度・食感の一部'],['再現の方法','香り再現器・味の再現・ニューロシンクの感覚情報補助'],['主な用途','保存・共有・料理の研究・思い出の味の保存']])
      ]),
      S('sec-record','記録のしかた',[
        P('記録には、小さな読み取り器を使う。料理の上にかざすと、立ちのぼる香りの成分を読み取る。味を記録するときは、ひと口分を読み取り器に乗せて、塩味、甘味、酸味、苦味、うまみの強さや、成分の組み合わせを読み取る。'),
        P('ニューロシンクを使っている人は、自分が食べたときの感じ方をそのまま記録することもできる。こちらは成分ではなく「その人がどう感じたか」の記録であるため、同じ料理でも記録した人によって中身が違う。'),
        T(['記録の種類','内容'],[
          ['成分の記録','読み取り器で香りと味の成分を読み取る。誰が記録しても、同じ料理ならほぼ同じデータになる。'],
          ['感じ方の記録','ニューロシンクで、本人が感じた香りと味を記録する。その人の好みや体調も含まれる。']
        ])
      ]),
      S('sec-replay','再現のしかた',[
        P('記録した香りは、香り再現器で再現できる。成分を組み合わせて同じ香りを作り出す小さな装置で、家庭にも広く普及している。'),
        P('味の再現には二つの方法がある。一つは、記録したデータをもとに、同じ味の小さな試食品を作る方法である。パーフェクト食品会社などの味覚再現技術がこの分野を支えている。もう一つは、ニューロシンクの感覚情報補助を使い、味そのものを神経に伝える方法である。'),
        P('ニューロシンクで再現した味は、口の中に何もないのに味だけがする。どれほど美味しく感じても、お腹は満たされない。そのため「味見」や「思い出すこと」には使われても、食事の代わりにする人はほとんどいない。')
      ]),
      S('sec-sns','味ごと共有する',[
        P('SNSでは、料理の写真に香りと味のデータを添えて投稿することが当たり前になっている。見る人は、写真を見ながら香りを再現し、どんな味だったかを確かめることができる。'),
        P('旅行先の料理の味を家族に送ったり、店が新しい料理の味を先に公開したりすることもある。一方で、データの味と実際の味が違うと言われる店もあり、「データでは美味しいのに」という言葉は、未来世界ではよく聞く悪口の一つになっている。')
      ]),
      S('sec-memory','思い出の味',[
        P('香りと味の記録の使われ方として、最も大切にされているのが、家族の味を残すことである。祖父母や親の手料理を記録しておき、本人がいなくなった後も、その味を確かめられるようにする家庭は多い。'),
        P('記録があれば、同じ味の料理を作り直すこともできる。それでも多くの人は、記録の味と自分で作った味を比べながら、少しずつ自分の味にしていく。記録は答えではなく、たどるための手がかりとして使われている。'),
        Q('この味は、いつでも開ける。でも、あの台所はもうない。')
      ]),
      S('sec-limit','技術の限界',[
        P('香りと味は記録できても、食感や温度、その場の空気までは完全には残せない。同じデータを再現しても、熱々の鍋を囲んだときの味と、ひとりで再現した味は違って感じられる。'),
        P('また、感じ方の記録は本人の感覚に強く結びついているため、ほかの人が再現しても、記録した本人と同じように感じられるとは限らない。')
      ]),
      S('sec-culture','食文化への影響',[
        P('香りと味を記録できるようになっても、人々は料理を作ることも、食べに出かけることもやめなかった。むしろ、記録できるからこそ、その場で食べることの価値がはっきりしたとも言われる。'),
        P('未来世界の食文化を守ってきた「食べることには何の価値があるのか」という問いに、この技術は新しい答えを一つ加えた。味は残せる。けれど、誰とどこで食べたかは、自分で覚えておくしかない。')
      ])
    ],
    related:['neuro-sync','food-culture','perfectfood','social-media','lumo','future-food-seasoning','memory-replay','death-and-funeral']
  },

  /* ---------------- 睡眠技術 ---------------- */
  { id:'sleep-tech', cat:'tech', title:'睡眠技術', aliases:['睡眠ポッド'], updated:U,
    lede:'眠りの深さや長さを整え、短い時間でも疲れを取れるようにする技術。眠りをなくすことはできないが、寿命が約200年ある世界で、人生の三分の一を占める眠りを少しでも良いものにしようとする工夫が重ねられている。',
    sections:[
      S('sec-overview','概要',[
        P('睡眠技術は、眠りの質を高め、必要な睡眠を効率よくとるための技術の総称である。寝具や寝室の環境を整えるものから、ニューロシンクで眠りの深さを導くもの、短時間で深く眠るための睡眠ポッドまで、さまざまな形がある。'),
        P('未来世界の技術でも、眠りそのものをなくすことはできていない。人間の脳と身体は、眠らなければ回復しないからである。睡眠技術が目指しているのは、眠らなくてよくすることではなく、眠りを良いものにすることである。'),
        I([['分類','医療・生活技術'],['主な機器','睡眠ポッド・調整寝具・ニューロシンクの睡眠補助'],['目的','眠りの質の向上・睡眠時間の調整'],['できないこと','眠りを完全になくすこと']])
      ]),
      S('sec-tools','主な機器',[
        T(['機器','内容'],[
          ['調整寝具','体温、寝返り、呼吸を読み取り、硬さや温度を一晩中自動で変える寝具。家庭で最も広く使われている。'],
          ['ニューロシンクの睡眠補助','眠りに入るときに視覚や聴覚の情報を少しずつ弱め、深い眠りへ導く。目覚めの時刻に合わせて、浅い眠りの段階で起こしてくれる。'],
          ['睡眠ポッド','身体を包み込むカプセル型の寝台。光、音、温度、空気を完全に整え、短い時間で深い眠りをとることができる。'],
          ['仮眠室','研究施設や職場、転送港などに置かれた、睡眠ポッドを並べた部屋。']
        ])
      ]),
      S('sec-pod','睡眠ポッドと短い眠り',[
        P('睡眠ポッドを使うと、同じ疲れを取るのに必要な時間を、ふつうの眠りより短くすることができる。研究者の多いヒューバートやセルトシティでは、職場に睡眠ポッドを置いている施設が多く、昼に短く深く眠ってから仕事に戻る人もいる。'),
        P('ただし、短い眠りを毎日続けることは勧められていない。睡眠ポッドで縮められるのは眠りの一部だけで、夢を見る浅い眠りの時間まで削ると、記憶の整理や気分に影響が出ることが分かっている。医師の多くは、睡眠ポッドを「忙しい日のための道具」として使うよう勧めている。')
      ]),
      S('sec-cold','コールドスリープとの違い',[
        P('睡眠ポッドとコールドスリープは、どちらもカプセルの中で眠るため混同されやすい。しかし、睡眠ポッドは毎日の眠りを良くするための機器であり、コールドスリープは身体の時間を長い期間止めておくための技術である。両者はまったく別のものとして扱われている。'),
        P('「ちょっとコールドスリープしてくる」という冗談は、昼寝をするときの決まり文句になっている。')
      ]),
      S('sec-life','長い人生と眠り',[
        P('平均寿命が約200年の世界では、人は一生のうち、六十年以上を眠って過ごすことになる。その時間をどう考えるかは、人によって違う。'),
        P('睡眠ポッドを使って眠りを少しでも縮め、起きている時間を増やそうとする人もいる。一方で、眠ることそのものを楽しみにする人も多い。調整寝具や香り、音にこだわり、眠る時間を一日の中で最も心地よい時間にしようとする「眠りの趣味」も広く知られている。')
      ]),
      S('sec-dream','夢',[
        P('ニューロシンクの記録機能を使えば、眠っている間の脳の活動を残すことはできる。しかし、夢をはっきりとした映像として見返すことは、現在の技術でもできていない。目覚めたあとに思い出した夢を、記憶映写の技術で映すことはできるが、それは夢そのものではなく、思い出した夢である。'),
        P('夢だけは、今も見た本人のものである。'),
        Q('眠りは削れる。夢は、取り出せない。')
      ])
    ],
    related:['neuro-sync','cold-sleep','medical-tech','hubert','sertcity','memory-replay','future-housing']
  },

  /* ---------------- 動物翻訳機 ---------------- */
  { id:'animal-translator', cat:'tech', title:'動物翻訳機', aliases:['動物の翻訳機','ペット翻訳機'], updated:U,
    lede:'動物の鳴き声や仕草、身体の状態を読み取り、その動物が思っていることを人間の言葉にして話す機器。翻訳の精度も、話すときの口調も、作る会社によってまちまちである。動物の本当の気持ちなのか、人間の解釈なのかは、今も議論が続いている。',
    sections:[
      S('sec-overview','概要',[
        P('動物翻訳機は、首輪や小さな札の形をした機器で、動物の鳴き声、仕草、表情、心拍や体温などを読み取る。読み取った情報をAIが分析し、その動物が今どんなことを思っているかを推定して、人間の言葉で話す。'),
        P('たとえば、猫が窓の外を見ながら尾を小さく振っていると、翻訳機は「あの鳥、気になる」と話す。犬が玄関の前で鼻を鳴らしていると、「もうすぐ帰ってくる気がする」と話す。'),
        I([['分類','生体情報解析・AI技術'],['形','首輪型・札型・据え置き型'],['読み取るもの','鳴き声・仕草・表情・心拍・体温など'],['特徴','精度も口調も会社ごとに違う']])
      ]),
      S('sec-how','しくみ',[
        P('動物はニューロシンクを使わないため、翻訳機は神経に直接つながるのではなく、外から読み取れる情報だけを使う。読み取った情報を、その種類の動物の膨大な観察記録と照らし合わせ、最も近い気持ちを選んで言葉にする。'),
        P('使い続けるほど、翻訳機はその動物の癖を覚えていく。同じ「にゃあ」でも、その猫にとっては「ごはん」なのか「なでて」なのかを、何か月もかけて覚えるのである。そのため、新しく買った翻訳機は、最初のうちはよく外れる。')
      ]),
      S('sec-companies','会社ごとの違い',[
        P('動物翻訳機は多くの会社から発売されており、精度も、話すときの口調も、会社によって大きく違う。どの翻訳機を選ぶかは、飼い主がその動物にどう話してほしいかで決まることも多い。'),
        T(['種類','特徴'],[
          ['ていねい型','「お腹がすきました」「少し眠いです」のように、ていねいな言葉で話す。精度が高く、獣医や研究施設でも使われる。'],
          ['子ども口調型','「おなかすいたー！」「あそぼ！」のように話す。精度はそこそこだが、家庭で最も人気がある。'],
          ['気まま型','動物の性格に合わせて口調を変える。同じ機種でも、猫によってえらそうになったり甘えん坊になったりする。'],
          ['単語型','「空腹」「不安」「興味」のように、気持ちを単語だけで表示する。会話にはならないが、余計な解釈を加えないため、研究者に好まれる。']
        ]),
        P('同じ猫に違う会社の翻訳機をつけると、まったく違うことを話すことがある。そのため、二台の翻訳機を同時につけて、どちらが当たっているかを比べる遊びもある。')
      ]),
      S('sec-cats','ヒューバートの猫と翻訳機',[
        P('猫と暮らす文化が根づいたヒューバートでは、動物翻訳機は猫カフェや猫専門施設で広く使われている。猫が話す言葉を聞きながら過ごすことを目当てに、猫カフェを訪れる観光客も多い。'),
        P('一方で、家で暮らす猫には翻訳機をつけない人も多い。「猫が何を考えているか分からないところが猫の良さだ」と考えるヒューバートの猫好きは少なくない。翻訳機が「別に」としか言わない猫もおり、飼い主を落ち込ませることもある。')
      ]),
      S('sec-belnea','ベルネアと翻訳機',[
        P('生き物を観察し、理解することを文化の中心に置くベルネアでは、動物翻訳機への受け止め方は複雑である。研究の補助として単語型を使う研究者は多いが、言葉で話す型の翻訳機には慎重な人が多い。'),
        P('ベルネアの人々は、生き物の気持ちは「見る・待つ・比較する・記録する・変化を読む」ことで少しずつ分かっていくものだと考えている。翻訳機が先に答えを言ってしまうと、観察する目が育たない、というのがその理由である。ベルネアの子どもたちは、まず翻訳機なしで共生体と暮らすことを教わる。')
      ]),
      S('sec-debate','本当の気持ちなのか',[
        P('動物翻訳機が話す言葉は、動物の本当の気持ちなのか、それとも人間がそう思いたいだけなのか。この問いには、今もはっきりとした答えがない。'),
        P('翻訳機は、動物の気持ちを推定して、人間に分かる言葉に置き換えているにすぎない。どの言葉を選ぶか、どんな口調で話すかを決めているのは、作った会社と、それを選んだ飼い主である。翻訳機の言葉に、作った人間の考え方が混ざるのは避けられない。'),
        P('それでも、翻訳機によって動物の体調の変化に早く気づけた、という声は多い。翻訳機の言葉をそのまま信じるのではなく、気づくきっかけとして使うことが、上手な付き合い方だとされている。'),
        Q('言葉にしたのは、機械か、私か。')
      ])
    ],
    related:['cat-culture','hubert','belnea','ai-tech','animal-body','ancient-life-restoration']
  },

  /* ---------------- 重力制御 ---------------- */
  { id:'gravity-control', cat:'tech', title:'重力制御', aliases:['人工重力'], updated:U,
    lede:'物体にかかる重さや、加速によって身体にかかる力を、局所的に弱めたり強めたりする技術。莫大なエネルギーを必要とするため、主に宇宙船や宇宙施設で使われている。地上の暮らしで目にすることはほとんどない。',
    sections:[
      S('sec-overview','概要',[
        P('重力制御は、限られた空間の中で、物体や人にかかる重さを調整する技術である。物を軽くして運びやすくしたり、宇宙船が急に加速したときに乗っている人の身体にかかる力を和らげたりすることができる。'),
        P('ただし、重力制御は非常に多くのエネルギーを使う。調整できる範囲も狭く、時間も限られる。そのため、使われる場所は、ほかの方法では代わりのきかない宇宙の現場が中心となっている。'),
        I([['分類','宇宙技術・物理工学'],['主な用途','宇宙船の加速の緩和・宇宙での荷役・発着・宇宙製造'],['課題','莫大なエネルギー消費・調整できる範囲が狭い'],['地上での利用','ごく限られた施設のみ']])
      ]),
      S('sec-space','宇宙での利用',[
        T(['用途','内容'],[
          ['加速の緩和','宇宙船が大きく加速・減速するとき、乗員の座席や居室にかかる力を和らげる。長距離の宇宙船には欠かせない装備である。'],
          ['発着と係留','宇宙港で宇宙船を受け止め、ゆっくりと所定の位置へ導く。'],
          ['荷役','巨大な資材や鉱石を軽くして、少ない力で動かす。宇宙資源の積み下ろしに使われる。'],
          ['宇宙製造','材料の流れや固まり方を、重さを調整しながら制御する。宇宙工場で特殊な部材を作るときに使われる。'],
          ['医療区画','無重力に慣れた身体を、地上の重さへ少しずつ戻すための区画。']
        ])
      ]),
      S('sec-ring','回転による重力との違い',[
        P('リング型の宇宙ステーションでは、居住区を回転させることで遠心力による人工的な重力を作っている。重力制御があるのに、なぜ回転を使い続けているのかと問われることは多い。'),
        P('答えは、エネルギーと安定である。何千人もが暮らす広い居住区全体に、何十年も途切れずに重さを与え続けるには、重力制御では消費が大きすぎる。いったん回り始めれば回り続けるリングの方が、はるかに安く、安全である。重力制御は、回転では対応できない細かな場面を補う技術として、リングと組み合わせて使われている。'),
        P('火星の都市でも事情は同じで、低重力そのものを重力制御で打ち消すことはしていない。低重力での暮らしは、医療研究や健康管理で支えられている。')
      ]),
      S('sec-ground','地上での利用',[
        P('地上で重力制御が使われるのは、宇宙へ送る大型部材の試験施設や、一部の研究施設、医療施設などに限られる。建設現場で重い資材を運ぶ場合も、多くは外骨格やロボットが使われ、重力制御はほとんど使われない。'),
        P('乗り物や家具、個人の道具に重力制御が組み込まれることは、現在の技術ではまずない。消費するエネルギーに見合わないためである。「空中に浮かぶ家具」は、今のところ娯楽作品の中のものである。')
      ]),
      S('sec-fumora','フーモラ・スカイピルについて',[
        P('成層圏に浮かぶフーモラ・スカイピルは、重力制御で浮いていると思われがちである。しかし、フーモラの浮遊は、現在の人類が使っている重力制御とは別の仕組みによるものとされ、その詳しい仕組みは公開されていない。'),
        P('都市そのものを空に浮かべ続けるだけの重力制御は、今の人類の技術では実現できない。フーモラは、その意味で例外的な存在である。')
      ]),
      S('sec-feel','重さが変わる感覚',[
        P('重力制御の区画に入ると、身体が急に軽くなったり、重くなったりする。初めての人は、足もとがふわりと浮くような感覚に驚き、気分が悪くなることもある。宇宙船の乗員は、訓練でこの感覚に慣れていく。'),
        Q('重さは、変えられる。ただし、高くつく。')
      ])
    ],
    related:['space-development','space-station','space-habitation','mars-development','space-resources','energy-tech','fumora-skypill','tensho','exoskeleton']
  },

  /* ---------------- 外骨格 ---------------- */
  { id:'exoskeleton', cat:'tech', title:'外骨格', aliases:['パワードスーツ','パワーアシストスーツ'], updated:U,
    lede:'身体の外側に着て、筋力や姿勢を補う機械の骨格。建設や災害救助、重い物を扱う仕事、身体の衰えた人の暮らしの補助まで幅広く使われる。身体を作り替えるサイボーグやアニマルボディとは違い、脱げば元の身体に戻る。',
    sections:[
      S('sec-overview','概要',[
        P('外骨格は、身体の外側に装着する機械の骨格で、腕や脚、腰の動きに合わせて力を加え、着ている人の動作を補助する。重い物を持ち上げる、長時間同じ姿勢で作業する、高い場所で身体を支えるといった動作を楽にする。'),
        P('身体に機械を組み込むサイボーグや、身体の形を変えるアニマルボディとは違い、外骨格は「着るもの」である。必要なときに着て、終われば脱ぐ。脱げば元の身体に戻ることが、外骨格の大きな特徴となっている。'),
        I([['英名','Exoskeleton'],['分類','身体補助機器・作業機器'],['主な用途','建設・物流・災害救助・介護・暮らしの補助'],['特徴','着脱でき、身体を変えない']])
      ]),
      S('sec-types','種類',[
        T(['種類','内容'],[
          ['補助型','腰や膝など一部だけを支える軽いもの。服の下に着られるほど薄く、日常生活で使われる。'],
          ['作業型','全身を覆い、重い物の運搬や長時間の作業を支える。建設や物流の現場で使われる。'],
          ['救助型','がれきの撤去や、危険な場所での救助に使われる頑丈なもの。外からの衝撃から着ている人を守る装甲を持つ。'],
          ['宇宙型','宇宙服と一体になったもの。宇宙での建設や修理の作業に使われる。']
        ])
      ]),
      S('sec-work','仕事での利用',[
        P('建設現場や物流の倉庫では、作業型の外骨格を着た作業員が、ロボットと並んで働いている。ロボットは決まった作業を休みなく続けることが得意だが、現場ごとに違う判断や細かな調整は、外骨格を着た人間の方が向いている。'),
        P('災害救助の現場では、救助型の外骨格が欠かせない。重いがれきを持ち上げながら、その下にいる人を傷つけないよう、力の加減は着ている人の判断で行われる。外骨格は人間の力を大きくするが、どこにどれだけ力を使うかを決めるのは人間である。')
      ]),
      S('sec-life','暮らしの補助',[
        P('補助型の外骨格は、暮らしの中でも広く使われている。平均寿命が約200年の世界では、人生の後半に足腰が弱っても、補助型の外骨格を着ることで、それまでと同じように歩き、買い物をし、旅行を楽しむ人が多い。'),
        P('身体改造によって身体そのものを調整する人もいるが、身体を変えずに済む外骨格を選ぶ人も多い。その日の体調に合わせて着たり脱いだりできることが、選ばれる理由になっている。')
      ]),
      S('sec-neuro','操作のしかた',[
        P('多くの外骨格は、着ている人の筋肉の動きや重心の変化を読み取り、動こうとした方向へ自然に力を加える。特別な操作を覚えなくても、ふつうに身体を動かすだけで使える。'),
        P('ニューロシンクと連携すると、より細かな動きや、力の強さの切り替えができるようになる。ただし、ニューロシンクがなくても基本的な補助は使えるため、従来型の端末を使う人でも外骨格は問題なく利用できる。')
      ]),
      S('sec-sports','スポーツでの扱い',[
        P('外骨格は、着れば身体能力を大きく高められるため、スポーツでは厳しく扱われる。生身の部では、医療目的の補助型を含めて、競技中の着用は認められていない。'),
        P('拡張の部では、外骨格を着て競う種目がある。外骨格の性能そのものも勝敗に関わるため、選手と作り手が一体となって競う競技として人気がある。')
      ]),
      S('sec-culture','着る技術として',[
        P('身体を作り替える技術が広まった世界で、外骨格は「変えない」ことを選べる技術でもある。機械の力を借りながら、自分の身体は自分のまま残しておく。その選択ができることが、外骨格が今も広く使われ続けている理由である。'),
        Q('脱げば、いつもの私。')
      ])
    ],
    related:['cyborg','body-modification','animal-body','robot','automation','sports','neuro-sync','gravity-control']
  },

  /* ---------------- 光学迷彩 ---------------- */
  { id:'optical-camouflage', cat:'tech', title:'光学迷彩', aliases:['透明化技術'], updated:U,
    lede:'周りの景色を表面に映し出し、身に着けた人や物を見えにくくする技術。悪用されれば重大な犯罪につながるため、個人での使用は禁じられ、SVHや警察、生き物の観察など、限られた用途だけに許可されている。',
    sections:[
      S('sec-overview','概要',[
        P('光学迷彩は、衣服や覆いの表面に、その向こう側の景色を映し出すことで、身に着けた人や物を周りに溶け込ませる技術である。完全に消えるわけではないが、離れた場所からはほとんど見分けがつかなくなる。'),
        P('便利な技術である一方、悪用されれば、盗みや侵入、人を傷つける犯罪にそのまま使えてしまう。そのため、光学迷彩は未来世界で最も厳しく管理されている技術の一つとなっている。'),
        I([['分類','光学技術・特殊装備'],['しくみ','表面に向こう側の景色を映し出す'],['個人での使用','禁止'],['許可される用途','SVH・警察・生き物の観察・研究など']])
      ]),
      S('sec-how','しくみ',[
        P('光学迷彩の表面には、細かな映像素子がすき間なく並んでいる。周りの景色を読み取り、見る人の位置から見て向こう側にあるはずの景色を、表面に映し出す。'),
        P('ただし、見る方向が一つではないため、すべての方向から完全に見えなくすることは難しい。動いているときや、近くで見たとき、強い光の下では、景色のゆがみとして気づかれることがある。光学迷彩は「見えなくなる」技術ではなく「見つけにくくなる」技術だと言われるのは、このためである。')
      ]),
      S('sec-rules','使用の制限',[
        P('光学迷彩を個人が持つこと、使うことは、多くの国で禁じられている。製造も許可を受けた工房に限られ、作られた装備は一つずつ登録され、どこで誰が使っているかが管理されている。'),
        T(['用途','扱い'],[
          ['SVH','変異体に気づかれずに近づくため、任務に応じて使用が認められている。'],
          ['警察','捜査や監視など、限られた場面で使われる。使用の記録が残される。'],
          ['生き物の観察','野生の生き物を驚かせずに観察するため、許可を受けた研究者が使う。'],
          ['研究・撮影','許可を受けた研究や映像の撮影に限って使われる。'],
          ['個人','禁止。所持しているだけで罪になる国が多い。']
        ])
      ]),
      S('sec-belnea','観察のための光学迷彩',[
        P('光学迷彩の平和な使い道として知られているのが、生き物の観察である。人の姿が見えるだけで行動を変えてしまう生き物は多い。光学迷彩で姿を隠せば、生き物の本来の暮らしをそのまま観察することができる。'),
        P('ベルネアのドームでは、許可を受けた観察者が、光学迷彩の覆いの中でじっと生き物を待つ姿が見られる。「触らない、追わない、待つ」という観察の作法を、最もよく守れる道具だと言われている。')
      ]),
      S('sec-detect','見破る技術',[
        P('光学迷彩が存在する以上、それを見破る技術も発達している。光学迷彩は景色を映すことはできても、熱や重さ、空気の動きまで消すことはできない。警察や重要な施設では、熱や空気の流れを読み取る検知器によって、迷彩を着た人の存在に気づけるようになっている。'),
        P('そのため、光学迷彩を使った犯罪の多くは、すぐに発見される。それでも完全に防げるわけではなく、見えにくくする技術と見破る技術の追いかけっこは、今も続いている。')
      ]),
      S('sec-culture','物語の中の光学迷彩',[
        P('光学迷彩は、娯楽作品では定番の道具である。ゲームや体験型作品の中では、誰でも自由に光学迷彩を使って遊ぶことができる。現実では使えない道具だからこそ、仮想の世界で使うことが楽しまれている。'),
        Q('見えないことは、許されることではない。')
      ])
    ],
    related:['svh','svh-weapons','svh-members','police','crime-and-rehabilitation','belnea','future-games']
  },

  /* ---------------- 記憶映写 ---------------- */
  { id:'memory-replay', cat:'tech', title:'記憶映写', aliases:['記憶の再生','記憶の保存'], updated:U,
    lede:'思い出した記憶を、ニューロシンクを通して映像や感覚として取り出し、保存したり、同意した相手に見せたりする技術。取り出せるのは「思い出した記憶」であり、記憶そのものではない。ライフログが「起きたことの記録」なら、記憶映写は「覚えていることの記録」である。',
    sections:[
      S('sec-overview','概要',[
        P('記憶映写は、人が何かを思い出しているときの脳の活動を、ニューロシンクで読み取り、映像や音、感覚として再構成する技術である。取り出した記憶は保存しておくことも、立体映像やニューロシンクを通して、ほかの人に見せることもできる。'),
        P('ニューロシンクには、記憶の整理や検索を助ける記憶補助の機能がある。記憶映写は、その技術をさらに進めたもので、思い出した場面そのものを外へ取り出せるようにした。'),
        I([['分類','脳情報技術'],['必要な機器','ニューロシンク（対応機能）'],['取り出せるもの','本人が思い出した記憶'],['できないこと','忘れた記憶の復元・記憶の書き換えや削除']])
      ]),
      S('sec-lifelog','ライフログとの違い',[
        T(['','ライフログ','記憶映写'],[
          ['記録するもの','ニューロシンクを使い始めてからの活動履歴やデータ','本人が思い出した記憶'],
          ['正確さ','起きたことをそのまま記録する','本人の覚え方や思い込みが混ざる'],
          ['範囲','使い始めてからの出来事だけ','ニューロシンクを使う前の記憶も、思い出せれば取り出せる'],
          ['向いている用途','事実の確認','思い出を残す、人に伝える']
        ]),
        P('ライフログは使い始める前の出来事を記録できない。しかし記憶映写は、本人が覚えてさえいれば、子どものころの記憶でも取り出すことができる。その代わり、取り出された記憶は、本人がそう覚えているという形のものであり、実際に起きたこととは違う部分を含んでいる。')
      ]),
      S('sec-limit','できないこと',[
        P('記憶映写で取り出せるのは、本人が今思い出せる記憶だけである。完全に忘れてしまった記憶を復元することはできない。ニューロシンクの記憶補助と同じく、あくまで人間の記憶を補助する技術である。'),
        P('また、記憶映写によって記憶を書き換えたり、消したりすることはできない。ニューロシンクは、記憶の改竄や削除、人格の操作が仕様上できないように作られており、記憶映写もその設計を受け継いでいる。取り出すことはできても、戻すことはできない。'),
        P('また、記憶映写で取り出せるのは記憶の映像や感覚であり、その人の意識ではない。意識そのものを専用の仮想環境へ接続する蓬莱とは、まったく別の技術である。'),
        P('思い出すたびに、記憶は少しずつ変わる。同じ人が同じ出来事を何度か映写すると、毎回少しずつ違う映像になる。人々はそれを欠点ではなく、記憶というものの性質だと受け止めている。')
      ]),
      S('sec-law','決まりごと',[
        P('記憶は、その人の最も深い私的な情報である。世界倫理改正法で定められた、神経情報の利用・保存・共有に関する基準のもとで、記憶映写には厳しい決まりがある。'),
        L([
          '記憶を取り出すことも、人に見せることも、本人の同意がなければできない。',
          '取り出した記憶の持ち主は、記憶の本人である。本人はいつでも、保存した記憶を消すことができる。',
          '他人の記憶を、本人に隠れて読み取ることは重大な犯罪とされる。',
          '取り出した記憶は、本人の覚え方が混ざるため、それだけでは裁判の証拠として扱われない。'
        ])
      ]),
      S('sec-uses','使われ方',[
        T(['場面','使われ方'],[
          ['思い出の保存','子どもが生まれた日、旅先の景色など、大切な場面を取り出して残す。'],
          ['伝えること','言葉では説明しにくい景色や出来事を、家族や友人に見せる。'],
          ['医療','本人の同意のもと、つらい記憶との向き合い方を医師と一緒に考えるために使われる。'],
          ['創作','作家や芸術家が、頭の中の景色をそのまま作品の下絵にする。'],
          ['弔い','生前に本人が残した記憶を、葬儀の場で家族が見ることがある。']
        ])
      ]),
      S('sec-long-life','長い人生と記憶',[
        P('平均寿命が約200年の世界では、古い記憶ほど薄れ、混ざり合っていく。百年以上前の記憶を映写すると、人の顔がぼやけていたり、別の日の出来事が混ざっていたりすることも珍しくない。'),
        P('それでも人々は、薄れかけた記憶を取り出して残そうとする。正確でなくても、自分がそう覚えていたということには、意味があるからである。'),
        Q('写っているのは、あの日ではない。あの日を覚えている、私だ。')
      ])
    ],
    related:['neuro-sync','lifelog','world-ethics-revision-law','horai','hologram','death-and-funeral','sleep-tech','scent-taste-record']
  }
  ];

  NEW.forEach(function(a){ if(!ARTICLES.some(function(x){return x.id===a.id;})) ARTICLES.push(a); });

  /* 既存記事の関連項目へ */
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  var REL = {
    'neuro-sync':['hologram','scent-taste-record','sleep-tech','memory-replay'], 'lifelog':['memory-replay'],
    'future-games':['hologram'], 'fire-alternatives':['hologram'], 'sports':['exoskeleton','hologram'],
    'food-culture':['scent-taste-record'], 'social-media':['scent-taste-record'], 'perfectfood':['scent-taste-record'],
    'cold-sleep':['sleep-tech'], 'cat-culture':['animal-translator'], 'hubert':['animal-translator'], 'belnea':['animal-translator','optical-camouflage'],
    'space-development':['gravity-control'], 'space-station':['gravity-control'], 'space-habitation':['gravity-control'],
    'cyborg':['exoskeleton'], 'body-modification':['exoskeleton'], 'robot':['exoskeleton'],
    'svh-weapons':['optical-camouflage'], 'police':['optical-camouflage'], 'world-ethics-revision-law':['memory-replay']
  };
  Object.keys(REL).forEach(function(id){ var a=art(id); if(!a){ console.warn('tech8: no article', id); return; }
    a.related=a.related||[]; REL[id].forEach(function(r){ if(a.related.indexOf(r)<0) a.related.push(r); }); });

  /* ニューロシンクの記憶補助の節に一文 */
  var ns=art('neuro-sync'); if(ns){ ns.sections.forEach(function(s){ if(s.id && s.title==='記憶補助' && !s.blocks.some(function(b){return b.text && b.text.indexOf('記憶映写')>=0;})){
    s.blocks.push(P('思い出した記憶を映像や感覚として取り出す技術については、記憶映写の項目を参照。')); } }); }
  /* 宇宙ステーションのリング型に一文 */
  var st=art('space-station'); if(st){ st.sections.forEach(function(s){ if(s.title==='リング型宇宙ステーション' && !s.blocks.some(function(b){return b.text && b.text.indexOf('重力制御')>=0;})){
    s.blocks.push(P('重力制御の技術も存在するが、広い居住区に長く重さを与え続けるには消費するエネルギーが大きすぎる。そのため居住区には回転による重力が使われ、重力制御は発着や荷役などを補う形で使われている。')); } }); }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（9）
   子陽炉は地球上に9基、9か国が採用（公開設定）。
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var a=art('solar-core'); if(!a) return;
  a.sections.forEach(function(s){
    if(s.id==='sec-overview'){ s.blocks.forEach(function(b){ if(b.t==='info' && !b.items.some(function(i){return i.label==='設置数';})){
      b.items.splice(4,0,{ label:'設置数', value:'地球上に9基（9か国が採用）' }); } }); }
    if(s.id==='sec-operation'){ s.blocks.forEach(function(b){ if(b.text && b.text.indexOf('アナザニウム蓄電設備や他の炉、あるいは他国からの供給')>=0){
      b.text = b.text.replace('アナザニウム蓄電設備や他の炉、あるいは他国からの供給を組み合わせ','アナザニウム蓄電設備に蓄えた電力や、他国の炉からの融通を組み合わせ'); } }); }
    if(s.id==='sec-adoption' && !s.blocks.some(function(b){return b.text && b.text.indexOf('9基')>=0;})){
      s.blocks.unshift(P('子陽炉は、地球上に9基しか存在しない。1つの国に1基ずつ、9か国がそれぞれ自国の子陽炉を保有している。一基で国家規模の電力をまかなえるため、一つの国が複数の炉を持つことはない。'));
      s.blocks.push(P('9基の子陽炉は、互いに電力を融通し合うことで、どこかの炉が点検や停止に入ったときにも世界全体の電力が途切れないよう支え合っている。9基のうち1基でも失われれば、その国だけでなく、その炉から電力を受け取っている国々にも影響が広がる。'));
    }
  });
  a.updated=U;
  var e=art('energy-tech'); if(e){ e.sections.forEach(function(s){ if(s.id==='sec-overview' && !s.blocks.some(function(b){return b.text && b.text.indexOf('9基')>=0;})){
    s.blocks.push(P('子陽炉は地球上に9基あり、9か国がそれぞれ1基ずつ保有している。子陽炉を持たない国は、これらの国から電力を輸入している。')); e.updated=U; } }); }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（10）
   アマテラス教団（神道をルーツとする太陽信仰の教団。神道技／過激派）。
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  function T(h,r){ return { t:'table', headers:h, rows:r }; }
  if(!art('amaterasu-sect')) ARTICLES.push({
    id:'amaterasu-sect', cat:'culture', title:'アマテラス教団', aliases:['神道技','アマテラス'], updated:U,
    lede:'太陽を信仰の中心に置く教団。ルーツは旧時代の日本の神道にあるとされ、その教えは現在、神道技という武道の形で受け継がれている。一方で、一部が過激化し、天照大御神を唯一の真の神として、ほかの信仰や子陽炉を否定するようになっている。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        P('アマテラス教団は、太陽を信仰の中心に置く教団である。そのルーツは、旧時代の日本で信仰されていた神道にあるとされる。神道の神々の中でも、太陽を司る天照大御神を最も尊い存在として祀ってきた。'),
        P('未来世界の多くの宗教は、神を特定の姿や人格を持つ存在としては扱わない。その中で、アマテラス教団は天照大御神という名を持つ神を祀り続けてきた、数少ない教団の一つである。'),
        { t:'info', items:[
          { label:'分類', value:'太陽信仰・神道系の教団' },
          { label:'ルーツ', value:'旧時代の日本の神道とされる' },
          { label:'信仰の対象', value:'天照大御神（太陽）' },
          { label:'受け継がれ方', value:'神道技（武道）' },
          { label:'現在の課題', value:'一部の過激化' }
        ]}
      ]},
      { id:'sec-roots', title:'神道とのつながり', blocks:[
        P('旧時代の日本では、自然のあらゆるものに神が宿ると考える神道が信仰されていた。山、川、木、岩、そして太陽にも神がいるとされ、その中で太陽の神である天照大御神は、神々の中心に位置づけられていた。'),
        P('再始動後、旧時代の信仰の多くは形を変えた。ニポランでは祭礼や民間信仰が再編されて龍教が成立したが、龍教は神道と共通点を持ちながらも、特定の神を祀る宗教にはならなかった。アマテラス教団は、その流れとは別に、神道の神の名と、太陽を拝む作法を守り続けた人々から生まれたとされる。'),
        P('ただし、アマテラス教団が旧時代の神道をどこまで正しく受け継いでいるのかは、はっきりしていない。旧時代の記録は断片的にしか残っておらず、教団の教えにも、後の時代に作られた部分が多く含まれていると考えられている。')
      ]},
      { id:'sec-shintougi', title:'神道技', blocks:[
        P('アマテラス教団の教えは、現在では「神道技（しんとうぎ）」という武道の形で最も広く受け継がれている。神道技は、太陽を拝む作法や祈りの所作を、身体を鍛える型へと変えていったものである。'),
        { t:'table', headers:['教え','内容'], rows:[
          ['日拝（にっぱい）','稽古の始まりに、昇る太陽の方角へ礼をする。屋内の道場では東の壁に向かって行う。'],
          ['禊ぎの呼吸','深く長い呼吸で身体の内側を整える。神道の禊ぎに由来するとされる。'],
          ['型','祈りの所作をもとにした型を繰り返す。相手を倒すことより、自分の身体を正しく保つことが重んじられる。'],
          ['礼','稽古の相手にも、道場にも、太陽にも礼を尽くす。']
        ]},
        P('神道技の道場は世界各地にあり、通っている人の多くは、アマテラス教団の信者ではない。姿勢や呼吸を整える武道として、子どもから年配の人まで幅広く習われている。多くの人にとって、神道技は信仰ではなく、身体と心を整える習い事である。'),
        { t:'quote', text:'日に礼し、息を整え、己を正す。' }
      ]},
      { id:'sec-radical', title:'過激化', blocks:[
        P('近年、アマテラス教団の一部が過激化している。過激派は、天照大御神こそが唯一の真の神であると主張し、龍教やリフィネス教など、ほかの信仰を誤ったものとして否定するようになった。'),
        P('過激派が特に強く否定しているのが、子陽炉である。人工的に極小の恒星反応を維持する子陽炉は、人々から「人の手で灯した太陽」と呼ばれることがある。過激派はこれを「偽りの太陽」と呼び、天に昇る太陽だけが真の太陽であって、人がそれを作り出すことは神への冒涜だと主張している。'),
        T(['','穏健な教団・神道技','過激派'],[
          ['天照大御神','太陽を象徴する尊い神として祀る','唯一の真の神とする'],
          ['ほかの信仰','それぞれの信仰を尊重する','龍教やリフィネス教を誤りとして否定する'],
          ['子陽炉','特に問題にしない','「偽りの太陽」として否定する'],
          ['神道技','身体と心を整える武道','教団の力を示すための修練とする者もいる']
        ])
      ]},
      { id:'sec-relations', title:'ほかの信仰との対立', blocks:[
        P('龍教は特定の神を祀らず、「龍の理」と共に生きることを教える。リフィネス教は、森を神として崇拝するのではなく、自然の循環の一部として生きることを教える。どちらも、自分なりの向き合い方を尊重する信仰である。'),
        P('過激派は、こうした信仰のあり方そのものを「神を失った信仰」として批判している。龍教やリフィネス教の側は、ほとんどの場合、相手にしない姿勢をとっている。龍教には教祖も組織もなく、リフィネス教も宗教団体というより文化的な思想であるため、対立しようにも、向き合う相手がはっきりしないからである。')
      ]},
      { id:'sec-society', title:'社会からの見方', blocks:[
        P('多くの人にとって、アマテラス教団といえば、近所の神道技の道場である。穏健な信者や神道技を習う人々は、過激派と同じに見られることに強い不満を持っており、教団の中でも過激派との距離をめぐって意見が分かれている。'),
        P('一方で、過激派の主張は少しずつ広がっているとも言われ、各国の治安機関は、その動きに注意を払っている。'),
        { t:'quote', text:'空にある太陽は、一つでいい。' }
      ]}
    ],
    related:['dragon-religion','rifinesu-religion','god-and-the-world','solar-core','kogamichurch','niporan','sports','police']
  });

  /* 子陽炉：否定する教団がいること（公開範囲） */
  var sc=art('solar-core'); if(sc){ sc.sections.forEach(function(s){ if(s.id==='sec-adoption' && !s.blocks.some(function(b){return b.text && b.text.indexOf('偽りの太陽')>=0;})){
    s.blocks.push(P('子陽炉を「偽りの太陽」と呼んで否定する人々もいる。アマテラス教団の過激派は、天に昇る太陽だけが真の太陽であるとし、人の手で太陽を作り出すことを神への冒涜だと主張している。')); } });
    sc.related=sc.related||[]; if(sc.related.indexOf('amaterasu-sect')<0) sc.related.push('amaterasu-sect'); }
  /* 神とは何か：宗教との関係 */
  var gw=art('god-and-the-world'); if(gw){ gw.sections.forEach(function(s){ if(s.id==='sec-religion' && !s.blocks.some(function(b){return b.text && b.text.indexOf('アマテラス教団')>=0;})){
    var qi=s.blocks.length-1; s.blocks.splice(qi,0,P('一方で、神道をルーツとするアマテラス教団のように、天照大御神という名を持つ神を祀り続けてきた教団もある。その一部は近年過激化し、自らの神だけを真の神として、ほかの信仰を否定するようになっている。')); } });
    gw.related=gw.related||[]; if(gw.related.indexOf('amaterasu-sect')<0) gw.related.push('amaterasu-sect'); }
  ['dragon-religion','rifinesu-religion'].forEach(function(id){ var a=art(id); if(a){ a.related=a.related||[]; if(a.related.indexOf('amaterasu-sect')<0) a.related.push('amaterasu-sect'); } });
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（11）
   未来世界の宗教は、近代文明の宗教や神話が混ざり合ったものが多い。
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var g=art('god-and-the-world');
  if(g && !g.sections.some(function(s){return s.id==='sec-mixed';})){
    var i=-1; g.sections.forEach(function(s,n){ if(s.id==='sec-religion') i=n; });
    g.sections.splice(i+1,0,{ id:'sec-mixed', title:'混ざり合った信仰', blocks:[
      P('未来世界にある宗教の多くは、近代文明の宗教や神話が混ざり合ってできたものである。人類の再始動のあと、旧時代の信仰はまとまった形では残らず、祭礼の作法、神々の名前、言い伝えの断片などが、ばらばらに受け継がれた。'),
      P('人々はそれらの断片を、暮らしの中で組み合わせ、作り直していった。ある宗教の祈りの言葉と、別の神話の物語と、まったく別の土地の祭りが、一つの信仰の中に同居していることも珍しくない。'),
      { t:'table', headers:['宗教・信仰','混ざり合っているもの'], rows:[
        ['龍教','旧時代の日本の祭礼や民間信仰、神社への参拝、龍の書。神道や仏教と共通点を持つが、明確な関係は確認されていない。'],
        ['アマテラス教団','旧時代の日本の神道を中心に、後の時代に作られた教えや武道の作法が加わっている。'],
        ['古神教会','旧世界以前から語り継がれる神々と、各地の神話・古文書。'],
        ['リフィネス教','森と共に生きる考え方を中心に、各地の自然信仰や季節の祭りの形が重なっている。']
      ]},
      P('そのため、未来世界の人々の多くは、自分の信仰の中のどの部分が、もとはどの宗教や神話から来たものなのかを知らない。祈りの言葉の意味が分からないまま唱えられていたり、祭りの由来が忘れられたまま続いていたりすることもある。施設や計画、商品の名前に、旧時代の神話の名残がそのまま使われていることも多いが、その由来を気にする人はほとんどいない。'),
      P('古神教会のように、混ざり合った信仰を一つずつほどき、もとの神話や宗教をたどろうとする研究も行われている。一方で、混ざり合ったものこそが未来世界の信仰の姿であり、元をたどることにあまり意味はない、と考える人も多い。'),
      { t:'quote', text:'どこから来たかは忘れても、祈りは続いている。' }
    ]});
    g.updated=U;
  }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（12）
   龍教とキリスト教の関係をめぐる研究。
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var d=art('dragon-religion');
  if(d && !d.sections.some(function(s){return s.id==='sec-christianity';})){
    d.sections.push({ id:'sec-christianity', title:'キリスト教との関係をめぐる研究', blocks:[
      P('近代文明の記録の中で、龍教に最もよく似た宗教として知られているのが、キリスト教である。龍教の教典である龍の書には、アダム、エバ、カイン、都市エノク、知恵の実と生命の実、楽園からの離別、最初の殺人など、キリスト教の聖書と共通する人物や物語が数多く登場する。'),
      P('一方で、違いも大きい。聖書の神は龍として語られず、龍の書ではリリスがアダムやエバと並ぶ「始まりの子ら」の一人として語られる。楽園から流れ出る四つの流れも、聖書とは違う名前を持っている。龍の書で十二使徒と呼ばれるのは、人ではなく感情そのものである。'),
      { t:'table', headers:['','龍の書（龍教）','聖書（キリスト教）'], rows:[
        ['神','龍。光であり闇であり、二つにして一つ','人格を持つ唯一の神'],
        ['始まりの人','アダム・エバ・リリス（三枚の羽根から生まれる）','アダムとエバ'],
        ['楽園','すべての中心であり外側。死者は楽園へ還る','エデンの園。人は追放される'],
        ['四つの流れ','ラプラタ・ナイル・ドナウ・ガンジス','エデンから流れ出る四つの川（名前は異なる）'],
        ['十二使徒','深淵エイリアスに在る、感情そのもの','イエスの十二人の弟子'],
        ['カインとエノク','カインが地を歩き、都市エノクを築く','カインが町を建て、エノクと名づける']
      ]},
      P('この関係について、研究者のあいだでは二つの問いが議論されている。一つは、近代文明ではキリスト教が広く信仰されていたのに、なぜ現在の未来世界ではキリスト教ではなく龍教として信仰が残っているのか、という問いである。もう一つは、発掘された古代文明期の記録の中に、聖書ではなく龍の書によく似た記述が見つかっているのはなぜか、という問いである。'),
      P('古代文明は近代文明よりはるか昔の文明である。もし龍教が、近代文明のキリスト教の断片から生まれたものなら、古代の記録に龍の書と似た記述があることは説明がつかない。この時間の順序の食い違いが、研究者たちを悩ませている。'),
      { t:'table', headers:['説','内容','問題点'], rows:[
        ['断片混合説','再始動後、キリスト教の断片が日本の祭礼や民間信仰と混ざり合い、龍教になった。未来世界の多くの宗教と同じ成り立ち。','古代文明の記録に龍の書と似た記述があることを説明できない。'],
        ['共通源流説','龍の書もキリスト教の聖書も、さらに古い一つの伝承から分かれたもの。古代文明の記録は、その源流に近い姿を残している。','その源流がどこにあり、どのように近代文明まで伝わったのかが分からない。'],
        ['源流逆転説','古代の龍の書の伝承が長い時間をかけて形を変え、近代文明でキリスト教の聖書になった。未来世界の龍教は、むしろ元の姿に近い。','古代文明と近代文明のあいだの長い空白を、伝承がどう越えたのかを示す証拠がない。'],
        ['偶然説','人間が世界の始まりを語るとき、似た物語が生まれるのは珍しくない。似ているのは偶然である。','人物の名前や都市の名前まで一致することを、偶然だけで説明するのは難しい。']
      ]},
      P('古神教会や各国の研究機関がこの問題に取り組んでいるが、どの説も決め手を欠いており、答えは出ていない。龍の書を「何らかの事実の記録ではないか」と考える少数の研究者の立場も、この問題から生まれている。'),
      P('当の龍教の人々の多くは、この議論にあまり関心を持っていない。龍教にとって大切なのは、龍の書がどこから来たかではなく、龍の理と共にどう生きるかだからである。'),
      { t:'quote', text:'書がどこから来たかを問う者と、書と共に生きる者がいる。' }
    ]});
    d.related=d.related||[]; ['kogamichurch','ancient-civilization','modern-civilization','god-and-the-world'].forEach(function(r){ if(d.related.indexOf(r)<0) d.related.push(r); });
    d.updated=U;
  }
  /* 龍の書：来歴の節から案内 */
  var b=art('dragon-book'); if(b){ b.sections.forEach(function(s){ if(s.title==='来歴' && !s.blocks.some(function(x){return x.text && x.text.indexOf('キリスト教')>=0;})){
    s.blocks.push(P('龍の書は、近代文明のキリスト教の聖書と共通する人物や物語を数多く含んでいる。古代文明の記録との類似とあわせて、両者の関係をめぐる研究については、龍教の項目を参照。')); b.updated=U; } }); }
  /* 神とは何か：混ざり合った信仰の表の龍教の行 */
  var g=art('god-and-the-world'); if(g){ g.sections.forEach(function(s){ if(s.id!=='sec-mixed') return; s.blocks.forEach(function(x){ if(x.t!=='table') return; x.rows.forEach(function(r){
    if(r[0]==='龍教' && r[1].indexOf('キリスト教')<0) r[1]='旧時代の日本の祭礼や民間信仰、神社への参拝、龍の書。神道や仏教と共通点を持ち、龍の書にはキリスト教の聖書と共通する人物や物語も多い。'; }); }); }); }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（13）
   教義書『龍の理』（初代大司教が龍の書を読み解いてまとめたもの）と、龍の書の本文（抜粋）。
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  var RI_TEXT = [{"t": "h3", "text": "第一章　龍とは何か"}, {"t": "quote", "text": "龍は姿ではない。<br>龍は名でもない。<br>龍とは理である。<br>ある者は龍を竜として見る。<br>ある者は翼ある神として見る。<br>ある者は光を見る。<br>ある者は闇を見る。<br>されど、それらは皆、<br>龍の一端である。<br>ゆえに姿を論ずることは信仰ではない。<br>龍の理を知ることこそ信仰である。"}, {"t": "h3", "text": "第二章　創造について"}, {"t": "quote", "text": "創造とは世界を生むことに限らない。<br>命を育むことも創造。<br>言葉を紡ぐことも創造。<br>絵を描くことも創造。<br>歌を歌うことも創造。<br>誰かを導くことも創造。<br>ゆえに創造あるところ、<br>龍は共に在る。"}, {"t": "h3", "text": "第三章　死について"}, {"t": "quote", "text": "死は滅びではない。<br>魂は楽園へ還る。<br>ゆえに死を望んではならない。<br>また死を恐れてもならない。<br>生ある時を尽くし、<br>還る時を待て。"}, {"t": "h3", "text": "第四章　リリスの戒め"}, {"t": "quote", "text": "愛は尊きものなり。<br>されど愛は、<br>執着となる時、<br>災いとなる。<br>愛することを恐れるな。<br>されど、<br>相手を己のものとするな。"}, {"t": "h3", "text": "第五章　セツの戒め"}, {"t": "quote", "text": "悲しみは罪にあらず。<br>涙もまた罪にあらず。<br>されど、<br>失われしものを取り戻そうとする時、<br>人は理を見失う。<br>死を憎むな。<br>死もまた龍の理である。"}, {"t": "h3", "text": "第六章　カインの戒め"}, {"t": "quote", "text": "罪は消えない。<br>されど罪は終わりでもない。<br>カインは血を流した。<br>それでも人を導いた。<br>ゆえに、<br>過ちを犯した者もまた、<br>新たな道を歩むことができる。"}, {"t": "h3", "text": "第七章　エイリアスについて"}, {"t": "quote", "text": "エイリアスを恐れるな。<br>されど軽んずるな。<br>そこは世界の底であり、<br>創造の影である。<br>人は皆、<br>心の内にエイリアスを持つ。<br>己を知る者のみ、<br>そこより帰ることができる。"}, {"t": "h3", "text": "第八章　龍教の五つの教え"}, {"t": "quote", "text": "龍の理に従う者は、<br>一、生を尊べ。<br>一、創造を絶やすな。<br>一、死を恐れるな。<br>一、執着に囚われるな。<br>一、還る日まで善く生きよ。"}, {"t": "h3", "text": "終章"}, {"t": "quote", "text": "龍の姿を求める者は、<br>ついに龍を見ず。<br>龍の理を求める者は、<br>すでに龍と共に歩んでいる。"}];
  var BOOK_EX = [{"t": "h3", "text": "序　楽園に眠る龍の言葉"}, {"t": "quote", "text": "「案ずるな。<br>我は常に汝の傍に在り。<br>光と闇を抱く者よ。<br>共に還ろう、悠久の地へ。」"}, {"t": "h3", "text": "第一章　悠久の龍"}, {"t": "quote", "text": "はじめに龍は在った。<br>龍は光なり。<br>龍は闇なり。<br>光尽きぬ限り、<br>龍は滅びず。<br>闇失われぬ限り、<br>龍は去らず。<br>龍は神なり。<br>神は龍なり。<br>二つにして一つ。<br>一つにして無数なり。<br>人は龍を見ること能わず。<br>ただ羽根のみが世界へ降る。<br>羽根は見る者に応じて姿を変え、<br>夢を揺らし、<br>記憶を照らす。<br>それを見た者は皆、<br>その美しさを語った。"}, {"t": "h3", "text": "第二章　楽園"}, {"t": "quote", "text": "楽園はすべての中心なり。<br>楽園はすべての外側なり。<br>そこに時は流れず。<br>過去も未来もなく、<br>ただ在るのみ。<br>龍は楽園に眠る。<br>天使たちはその傍らを巡り、<br>静かに見守る。<br>死せる者は楽園へ還る。<br>迷える魂も、<br>傷ついた魂も、<br>最後には楽園へ辿り着く。<br>ゆえに人は言う。<br>「死は終わりにあらず。」<br>「還る時なり。」"}, {"t": "h3", "text": "第九章　龍の理"}, {"t": "quote", "text": "龍は無数に在る。<br>されど真なる龍はただ一つ。<br>楽園に眠る龍のみである。<br>他は皆、<br>その抜け殻なり。<br>抜け殻は滅びず。<br>倒れてもなお現れる。<br>羽根は今も世界へ降り続ける。<br>羽根に触れる者は夢を見る。<br>遠き日の夢を。<br>未だ来ぬ日の夢を。<br>あるいは。<br>悠久の地の夢を。"}, {"t": "h3", "text": "終章　帰郷"}, {"t": "quote", "text": "人は生まれる。<br>人は生きる。<br>人は愛する。<br>人は失う。<br>そして還る。<br>竜もまた還る。<br>獣もまた還る。<br>魂あるものは皆、<br>最後には楽園へ辿り着く。<br>ゆえに恐れるな。<br>死は終わりにあらず。<br>それは帰郷なり。<br>「我は汝であり。<br>汝は我なり。」<br>「光と闇を抱く者よ。」<br>「さあ、帰ろう。」<br>「悠久の地、エターナル・エデンへ。」"}];

  if(!art('ryu-no-ri-doctrine')) ARTICLES.push({
    id:'ryu-no-ri-doctrine', cat:'culture', title:'『龍の理』', aliases:['龍の理（教義書）'], updated:U,
    lede:'初代大司教が龍の書を読み解いてまとめた、龍教の教義書。龍の言葉を書き換えることは許されないとして、新たな神話を一切書かず、龍の書を解き明かすことだけに徹している。龍教の五つの教えは、この書に記されている。',
    sections:[
      { id:'sec-overview', title:'概要', blocks:[
        P('『龍の理』は、龍教の教典である龍の書を読み解き、そこから人がどう生きるべきかをまとめた教義書である。序に続いて八つの章と終章からなり、龍とは何か、創造、死、三つの戒め、エイリアス、そして龍教の五つの教えを語る。'),
        P('この書は、新しい神話を一つも語らない。龍の言葉を書き換えることは許されない、という考えのもとで、龍の書にすでに書かれていることを解き明かすことだけに徹している。龍の書が「何が起きたか」を語る書なら、『龍の理』は「それをどう受け止めて生きるか」を語る書である。'),
        { t:'info', items:[
          { label:'分類', value:'教義書' },
          { label:'まとめた人物', value:'初代大司教（名は伝わっていない）' },
          { label:'もとにした書', value:'龍の書' },
          { label:'構成', value:'序・八章・終章' },
          { label:'中心', value:'龍教の五つの教え' }
        ]},
        { t:'quote', text:'龍の言葉を書き換えることは許されない。<br>ゆえに『龍の理』は新たな神話を書かず、<br>龍の書を解き明かすのみである。' }
      ]},
      { id:'sec-archbishop', title:'初代大司教', blocks:[
        P('『龍の理』をまとめたのは、「初代大司教」と呼ばれる人物である。龍教が成立した統合暦008年ごろ、ニポランの祭礼や民間信仰が龍の書をもとに再編されていく中で、書の言葉を読み解き、人々に伝わる形に整えたとされる。'),
        P('ただし、初代大司教は龍教を開いた教祖ではない。龍教の人々は、龍教を誰かが始めたものとは考えておらず、初代大司教も「龍の書を最初に読み解いた人」として敬われている。名前も、どのような人物だったのかも伝わっていない。'),
        P('「初代」と呼ばれてはいるが、二代目以降の大司教についての確かな記録はない。大司教の位が人々を束ねる組織へ育つことはなく、龍教は今も明確な教祖や宗教組織を持たないままである。現在では「大司教」という言葉は、『龍の理』をまとめた人物その人を指す呼び名として残っている。')
      ]},
      { id:'sec-text', title:'本文', blocks: RI_TEXT },
      { id:'sec-book', title:'龍の書との対応', blocks:[
        { t:'table', headers:['『龍の理』','読み解いている龍の書の箇所'], rows:[
          ['第一章　龍とは何か','第一章「人は龍を見ること能わず」、第九章「龍は無数に在る」'],
          ['第二章　創造について','第四章「一つは創造を芽吹かせ」'],
          ['第三章　死について','第二章「死せる者は楽園へ還る」、終章「死は終わりにあらず」'],
          ['第四章　リリスの戒め','第六章、リリスの愛が歪んだ物語'],
          ['第五章　セツの戒め','第六章、悲しみを受け入れられなかった者の物語'],
          ['第六章　カインの戒め','第六章の最初の殺人と、第七章のカインの歩み'],
          ['第七章　エイリアスについて','第四章・第八章の深淵エイリアス'],
          ['第八章　五つの教え','書全体'],
          ['終章','第一章・第九章']
        ]},
        P('三つの戒めは、龍の書に語られる人物たちの過ちを、そのまま戒めとして読み替えたものである。龍の書がその人物たちを裁かずに語るのと同じように、『龍の理』も彼らを悪として語らず、同じ過ちに人がどう向き合うべきかだけを記している。')
      ]},
      { id:'sec-life', title:'暮らしの中の『龍の理』', blocks:[
        P('龍教の価値観として知られる「生」「創造」「死」「執着」「罪」の考え方は、ほとんどが『龍の理』に由来している。人生の節目に龍の教えを振り返るとき、多くの人が開くのは龍の書よりも、この短い書である。'),
        P('特に終章の言葉は、龍教の外でも広く知られている。龍教を信じているという自覚のない人でも、この言葉だけは聞いたことがある、というニポランの人は多い。'),
        P('『龍の理』そのものは、龍の書とは違って写本ごとの違いがほとんどない。龍の言葉を書き換えないという書の考え方が、この書自身にも守られてきたためだと言われている。')
      ]}
    ],
    related:['dragon-religion','dragon-book','god-and-the-world','tatsu-cha','death-and-funeral']
  });

  /* 龍教：教えの節、概要の情報 */
  var d=art('dragon-religion');
  if(d){
    d.sections.forEach(function(s){
      if(s.id==='sec-overview') s.blocks.forEach(function(b){ if(b.t==='info' && !b.items.some(function(i){return i.label==='教義書';})) b.items.push({ label:'教義書', value:'『龍の理』（初代大司教がまとめたもの）' }); });
      if(s.id==='sec-belief'){
        s.blocks.forEach(function(b){ if(b.text && b.text.indexOf('現在知られている文章も、誰が記したものなのかは分かっていない')===0){
          b.text='現在広く知られている言葉の多くは、初代大司教と呼ばれる人物が龍の書を読み解いてまとめた教義書『龍の理』に由来する。ただし、初代大司教は教祖ではなく、名前も伝わっていない。地域や家庭に伝わる言葉の中には、誰が記したのか分からないものも多く、長い年月の中で語り継がれるうちに少しずつ変化してきたと考えられている。'; } });
        if(!s.blocks.some(function(b){return b.t==='list' && b.items.join('').indexOf('還る日まで善く生きよ')>=0;})){
          var qi=-1; s.blocks.forEach(function(b,n){ if(b.t==='quote') qi=n; });
          var add=[ P('『龍の理』には、龍教の五つの教えが記されている。'), { t:'list', items:['生を尊べ。','創造を絶やすな。','死を恐れるな。','執着に囚われるな。','還る日まで善く生きよ。'] } ];
          if(qi>=0) s.blocks.splice.apply(s.blocks,[qi,0].concat(add)); else s.blocks.push.apply(s.blocks,add);
        }
      }
    });
    d.related=d.related||[]; if(d.related.indexOf('ryu-no-ri-doctrine')<0) d.related.unshift('ryu-no-ri-doctrine');
    d.updated=U;
  }

  /* 龍の書：本文（抜粋） */
  var b=art('dragon-book');
  if(b && !b.sections.some(function(s){return s.id==='sec-text';})){
    var i=-1; b.sections.forEach(function(s,n){ if(s.id==='sec-structure') i=n; });
    b.sections.splice(i+1,0,{ id:'sec-text', title:'本文（抜粋）', blocks:[
      P('ここでは、ニポランで最も広く読まれている写本から、龍教の信仰の中心となる序・第一章・第二章・第九章・終章を載せる。龍とは何か、楽園と死、龍の理、帰郷を語る部分である。ほかの章の内容は、構成の表と「語られる世界」の節を参照。')
    ].concat(BOOK_EX).concat([
      P('龍教の人々が葬儀の席や人生の節目に唱えるのは、主に序と終章の言葉である。これらの言葉をどう生き方に結びつけるかについては、初代大司教の教義書『龍の理』を参照。')
    ])});
    b.related=b.related||[]; if(b.related.indexOf('ryu-no-ri-doctrine')<0) b.related.unshift('ryu-no-ri-doctrine');
    b.updated=U;
  }
})();

/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（14）
   短かった技術記事6本の拡充：テレポーター／クローン技術／建築技術／インベントリ／気象管理／食品配送
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function P(t){ return { t:'p', text:t }; }
  function T(h,r){ return { t:'table', headers:h, rows:r }; }
  function Q(t){ return { t:'quote', text:t }; }
  function L(i){ return { t:'list', items:i }; }
  /* sec を before の前に（無ければ末尾に）入れる */
  function ins(id, sec, before){
    var a=art(id); if(!a){ console.warn('thin: no article', id); return; }
    if(a.sections.some(function(s){return s.id===sec.id;})) return;
    var idx=-1; if(before) a.sections.forEach(function(s,i){ if(s.id===before) idx=i; });
    if(idx<0) a.sections.push(sec); else a.sections.splice(idx,0,sec);
    a.updated=U;
  }
  function addInfo(id, label, value){ var a=art(id); if(!a) return; a.sections.forEach(function(s){ if(s.id==='sec-overview') s.blocks.forEach(function(b){ if(b.t==='info' && !b.items.some(function(i){return i.label===label;})) b.items.push({label:label,value:value}); }); }); }
  function rel(id, ids){ var a=art(id); if(!a) return; a.related=a.related||[]; ids.forEach(function(r){ if(a.related.indexOf(r)<0 && art(r)) a.related.push(r); }); }

  /* ================= テレポーター ================= */
  addInfo('teleporter','開発','ヒューバート（テレパス社）');
  addInfo('teleporter','国際中継','タスメニオ・タハルン');
  addInfo('teleporter','人の転送の普及','統合暦1998年');
  ins('teleporter',{ id:'sec-history', title:'歴史', blocks:[
    P('テレポート技術は、ヒューバートの生命情報解析と空間情報の研究から生まれ、テレパス社によって実用化された。最初に使われたのは人ではなく物だった。'),
    T(['時期','出来事'],[
      ['統合暦1150年頃','タスメニオで、テレポート技術を使った世界規模の中継網の構築実験が始まる。'],
      ['統合暦1350年頃','タハルンを中心とする世界テレポート中継網が完成する。まずは物資の輸送から使われ始める。'],
      ['統合暦1360年頃','中継網を応用した食品配送が広まる。'],
      ['統合暦1420年頃','インベントリが実用化され、個人の持ち物を遠くの保管庫から呼び出せるようになる。'],
      ['統合暦1998年','個人単位で人を転送するテレポーターが、世界規模で実用化される。']
    ]),
    P('物を運ぶテレポートと、人を運ぶテレポートのあいだには、六百年以上の開きがある。人の身体を安全に転送できると認められるまでには、それだけの時間と審査が必要だった。人が日常的に国と国を行き来するようになってから、まだ数十年しか経っていない。')
  ]},'sec-types');
  ins('teleporter',{ id:'sec-how', title:'しくみ', blocks:[
    P('テレパス社の説明によれば、テレポーターは転送する対象の情報を解析し、指定された座標で再び形にすることで、瞬時の移動を実現している。転送には、出発地と到着地の両方に対応する装置が必要で、どこへでも自由に飛べるわけではない。'),
    P('ただし、その詳しい仕組みは公開されていない。テレパス社も、技術が生まれたヒューバートも、原理の核心について多くを語らない。利用者の多くも、仕組みを意識することはほとんどない。テレポーターは、蛇口をひねれば水が出るのと同じように、ただ「使えるもの」として受け入れられている。')
  ]},'sec-inventory');
  ins('teleporter',{ id:'sec-port', title:'転送港と中継', blocks:[
    P('人を転送する大型の設備は、転送港と呼ばれる。各国の首都や大都市に置かれ、出発の受付、本人確認、行き先の確認を経て、転送室へ進む。'),
    P('国と国のあいだの転送は、原則としてタスメニオのタハルンにある巨大な中継施設を経由する。すべての国どうしを直接つなぐよりも、一か所の中継点に集めた方が、座標の管理と設備の維持にかかる費用を大きく抑えられるためである。旅人の多くは、気づかないうちにタスメニオを通っている。'),
    T(['設備','使われ方'],[
      ['転送港','人の転送。国際便は中継施設を経由する。'],
      ['物流転送施設','貨物の大量輸送。物流拠点どうしを結ぶ。'],
      ['家庭用・携帯型の転送装置','インベントリと連携し、登録した保管庫の物品を出し入れする。人は転送できない。']
    ])
  ]},'sec-security');
  ins('teleporter',{ id:'sec-feel', title:'転送の感覚', blocks:[
    P('転送は一瞬で終わる。転送室に入り、合図とともに目を閉じて開けると、そこはもう別の国の転送港である。'),
    P('初めて転送する人や体調のすぐれない人の中には、到着したあとに軽いめまいや、足もとがふわふわする感覚を覚える人がいる。これはテレポート酔いと呼ばれ、多くは数分で治まる。転送港には、到着した人が少し休める長椅子が必ず置かれている。'),
    P('転送先の座標がずれる「誤転送」は、ほとんど起きない。仮に装置が異常を感知した場合は、ただちに元の場所へ戻される。そのため、利用者が誤転送を心配することはまずない。')
  ]},'sec-security');
  ins('teleporter',{ id:'sec-society', title:'社会への影響', blocks:[
    P('テレポーターによって、未来世界から「遠い」という感覚の多くが消えた。国を越えて働くことも、遠くに住む家族に毎週会いに行くことも、特別なことではなくなった。'),
    P('一方で、テレポーターは誰もがいつでも無料で使えるものではない。国際転送には料金がかかり、転送港のない地方の町では、今も鉄道や自動車、航空機が使われている。宇宙でも同じで、テレポーターが使えるのは、すでに転送設備が設置された拠点のあいだだけである。新しい場所へ最初にたどり着くのは、今も宇宙船の役目である。'),
    P('どこへでもすぐに行けるようになった結果、移動の時間そのものを楽しむ旅が、かえって贅沢なものとして好まれるようにもなった。'),
    Q('距離は消えた。道のりは、選べるものになった。')
  ]});
  rel('teleporter',['telepass','tasumenio','inventory','food-delivery','space-development','transportation']);

  /* ================= クローン技術 ================= */
  addInfo('clone-tech','実用化','統合暦1540年頃（臓器・組織の培養）');
  addInfo('clone-tech','規制','ガルタンダ法（統合暦1835年）');
  ins('clone-tech',{ id:'sec-history', title:'歴史', blocks:[
    T(['時期','出来事'],[
      ['統合暦1450年','生命工学革命。ヒューバートを中心に、遺伝子解析や細胞培養の基礎技術が確立される。'],
      ['統合暦1540年頃','クローン技術の実用化。臓器や組織を培養する技術が、医療・研究で使われ始める。'],
      ['統合暦1800年代','人間の遺伝情報を完全に再現する技術が可能になり、大きな倫理的議論が起きる。'],
      ['統合暦1835年','ガルタンダ法の制定。完全な人間のクローンの製造が国際的に禁止される。']
    ])
  ]},'sec-regulation');
  ins('clone-tech',{ id:'sec-medical', title:'医療での利用', blocks:[
    P('クローン技術が最も広く使われているのは医療である。患者自身の細胞から、臓器や組織を培養して作ることができるため、移植に必要な臓器を他人から譲り受ける必要がない。自分の細胞から作った臓器は、身体に拒まれにくい。'),
    P('この技術は再生医療や人工臓器と組み合わされ、重い病気や大きな怪我の多くを回復できるものにした。平均寿命が約200年となった未来世界の医療は、クローン技術なしには成り立たない。')
  ]},'sec-regulation');
  ins('clone-tech',{ id:'sec-difference', title:'似た技術との違い', blocks:[
    P('未来世界には、生き物を「作る」技術がいくつもある。それぞれが何を元にし、何を作るのかによって、扱いは大きく違う。'),
    T(['技術','元にするもの','作るもの'],[
      ['クローン技術','今生きている個体の細胞','同じ遺伝情報を持つ臓器・組織・個体'],
      ['旧時代の生物復元技術','化石、古い遺伝情報、記録','すでに絶滅した生物（推定を含む）'],
      ['工業生産畜産（培養肉）','動物の細胞','食用の肉。生き物の個体ではない'],
      ['再生医療','患者自身の細胞','失われた組織や臓器']
    ]),
    P('すでに絶滅した生き物を蘇らせる研究は、生きている個体を複製するクローン技術ではなく、残された資料から形を推定する生物復元の技術として扱われる。複製できる元の個体が、もう存在しないからである。')
  ]},'sec-regulation');
  ins('clone-tech',{ id:'sec-animals', title:'動物のクローン', blocks:[
    P('ガルタンダ法が禁止しているのは、完全な人間のクローンである。動物のクローンは、研究や希少な生き物の保護のために、国際的な審査を受けた研究機関に限って認められている。'),
    P('一方で、亡くなったペットをクローンで取り戻したいという依頼は、今も後を絶たない。多くの国では、こうした個人の依頼は審査を通らない。同じ遺伝情報を持っていても、生まれてくるのは同じ姿をした別の命であり、いなくなった子が帰ってくるわけではない、という考えが広く共有されているためである。')
  ]},'sec-regulation');
  ins('clone-tech',{ id:'sec-identity', title:'複製と人格', blocks:[
    P('人間のクローンが禁止された理由の一つは、同じ遺伝情報を持つ人間を作ることが、その人の存在そのものを「複製できるもの」として扱うことにつながるからである。'),
    P('同じ遺伝情報を持っていても、記憶も経験も、その人が生きてきた時間も、複製することはできない。生まれつき同じ遺伝情報を持つ双子が別々の人間であるのと同じように、複製された人間もまた、別の一人の人間である。それでも、元になった人の代わりとして生み出されるなら、その存在は誰のものなのか。この問いに、社会は答えを出せなかった。')
  ]});
  var ct=art('clone-tech'); if(ct){ ct.sections.forEach(function(s){ if(s.id==='sec-regulation') s.blocks.forEach(function(b){ if(b.text && b.text.indexOf('「ガルタンダ倫理法」')>=0) b.text=b.text.replace('「ガルタンダ倫理法」','ガルタンダ法'); }); }); }
  rel('clone-tech',['galtanda-law','ancient-life-restoration','industrial-livestock','world-ethics-law']);

  /* ================= 建築技術 ================= */
  ins('architecture',{ id:'sec-history', title:'歴史', blocks:[
    P('未来世界の建築を大きく変えたのは、特殊素材である。統合暦1800年頃に特殊素材工学が成立し、統合暦1840年頃には、ドゥルスニウムやフラマニウムなどの特殊素材が建築に使われるようになった。これにより、超高層建築や大規模施設が数多く建てられるようになった。'),
    P('その後、統合暦1900年頃に合成木材が量産化されると、木の建物も再び身近なものになった。特殊素材の強さと、木の温かさを組み合わせた建物は、現在の未来世界で最もよく見られる形の一つである。')
  ]},'sec-features');
  ins('architecture',{ id:'sec-materials', title:'建材', blocks:[
    T(['素材','主な使われ方'],[
      ['ドゥルスニウム','軽くて非常に強い。超高層建築の骨組みや、大きな屋根を支える梁に使われる。'],
      ['フラマニウム','熱に強い。子陽炉の周辺施設や、高温を扱う工場などに使われる。'],
      ['アナザニウム','電気を蓄える。建物ごとの蓄電設備として、停電に備えるために使われる。'],
      ['合成木材','家具、内装、木造の住宅。硬さやしなやかさを用途に合わせて育て分けられる。'],
      ['従来の素材','石、コンクリート、ガラス、金属なども、今も広く使われている。']
    ])
  ]},'sec-features');
  ins('architecture',{ id:'sec-long', title:'長く使う建物', blocks:[
    P('人が約200年生きる世界では、建物も長く使われることが前提になっている。住宅は、住む人の家族構成や暮らし方が変わるたびに、壁を動かしたり設備を入れ替えたりしながら、何十年、何百年と使われ続ける。'),
    P('ユーレツェアのように、数百年以上使われ続けている工房や家が今も残る国もある。建物を建て替えるより、直しながら使い続けることを好む文化は、多くの国で見られる。')
  ]},'sec-life');
  ins('architecture',{ id:'sec-fire', title:'火を使わない建物', blocks:[
    P('火が禁忌とされる未来世界では、建物の中で火を使うことがほとんどない。調理も暖房も、燃焼を使わない技術で行われるため、近代文明の建物に欠かせなかった煙突や換気のための大きな設備は、多くの建物から姿を消した。'),
    P('その代わりに重視されているのが、電気と熱の安全である。大量の電気を蓄える設備や、熱を生み出す装置が建物の中にあるため、それらが異常を起こしたときに被害を広げない構造が、建物の決まりとして定められている。')
  ]},'sec-life');
  ins('architecture',{ id:'sec-regional', title:'国ごとの建築', blocks:[
    T(['国','特徴'],[
      ['ベルネア','国土を覆う巨大な環境ドーム。中に世界各地の環境を再現する。'],
      ['フーモラ・スカイピル','成層圏に浮かぶ回転型の空中都市。塔と環状の都市が組み合わされている。'],
      ['セルトシティ','閉鎖型の研究都市。内部の環境が一定に保たれる。'],
      ['チリルド・アイルツア','雪を加工した氷で建物や彫刻を作る。家庭には地下氷保管庫がある。'],
      ['ユーレツェア','数百年使われ続ける木造の家や工房。直しながら使い続ける。'],
      ['ガルヒューラ','巨大なボイラーを中心に集落が作られる。']
    ])
  ]},'sec-life');
  ins('architecture',{ id:'sec-build', title:'建てる技術', blocks:[
    P('建設現場では、ロボットと、外骨格を着た作業員が並んで働いている。重く大きな部材の運搬や、決まった手順の繰り返しはロボットが担い、現場ごとに違う判断や細かな調整は人間が担う。'),
    P('大きな建物は、工場であらかじめ作った部材を現場で組み上げる方法が多く使われる。そのため、超高層の建物でも、建設にかかる期間は近代文明よりはるかに短い。'),
    Q('建物は、建てて終わりではない。百年かけて、住む人に合わせていく。')
  ]},'sec-life');
  rel('architecture',['future-housing','exoskeleton','robot','belnea','yuretsuea','fire-taboo','framanium','dulsnium']);

  /* ================= インベントリ ================= */
  addInfo('inventory','実用化','統合暦1420年頃');
  ins('inventory',{ id:'sec-history', title:'歴史', blocks:[
    P('インベントリは、統合暦1350年頃に完成した世界テレポート中継網を、個人の持ち物の保管に応用したものである。統合暦1420年頃に実用化され、遠くの保管庫に預けた物を、必要なときにすぐ受け取れるようになった。'),
    P('人を転送するテレポーターが普及した統合暦1998年よりも五百年以上前から、物の転送は人々の暮らしの一部になっていた。')
  ]},'sec-functions');
  ins('inventory',{ id:'sec-use', title:'使い方', blocks:[
    P('利用者は、ニューロシンクや携帯端末から、保管庫に入っている物の一覧を見ることができる。呼び出したい物を選ぶと、家庭用の転送装置や携帯型の転送装置に、その物が届く。しまうときは、転送装置に物を置いて保管庫を指定するだけでよい。'),
    T(['場面','使われ方'],[
      ['毎日の暮らし','季節外れの服や、たまにしか使わない道具を保管庫に預け、家を広く使う。'],
      ['仕事','仕事道具を保管庫に入れておき、職場でも出張先でも同じ道具を呼び出す。'],
      ['旅','着替えや荷物を持たずに出かけ、旅先で必要な物だけを呼び出す。旅先で買った物は保管庫へ送る。'],
      ['家族','家族で共有する保管庫を作り、誰がいつ何を取り出したかを記録する。']
    ])
  ]},'sec-limits');
  ins('inventory',{ id:'sec-cost', title:'保管庫の大きさと費用', blocks:[
    P('保管庫の利用には料金がかかり、保管できる量によって料金が変わる。小さな保管庫は誰でも手軽に使える一方、家一軒分の荷物を預けられるような大きな保管庫は高価である。'),
    P('長い人生の中で、保管庫の中身は少しずつ増えていく。何十年も前に預けたまま忘れていた物が見つかることもあり、ときどき保管庫を整理する「インベントリ整理」は、多くの家庭の年末の習慣になっている。')
  ]},'sec-limits');
  ins('inventory',{ id:'sec-inherit', title:'受け継がれる保管庫', blocks:[
    P('人が亡くなったあと、その人の保管庫は家族に引き継がれる。保管庫の中には、本人しか知らなかった思い出の品が残されていることも多い。遺された家族が保管庫の一覧を一つずつ開いていく時間は、故人と向き合う時間にもなっている。'),
    Q('呼び出せば、すぐに届く。けれど、何をしまっておいたかは、その人しか知らない。')
  ]});
  rel('inventory',['travel','future-housing','food-delivery','death-and-funeral']);

  /* ================= 気象管理 ================= */
  ins('weather-control',{ id:'sec-history', title:'歴史', blocks:[
    T(['時期','出来事'],[
      ['氷河期のあと','人類は長い寒冷期を越えて再始動したが、各地で不安定な気候が続いた。'],
      ['統合暦1830年頃','異常気象の増加に対応するため、成層圏に無人の観測・気象制御施設が建設される。'],
      ['統合暦1870年代','フーモラ・スカイピルの空中都市機能が確立される。'],
      ['統合暦1905年頃','フーモラ・スカイピルが、国際的な気象安定システムに正式に組み込まれる。成層圏の無人施設に代わり、世界の気象安定化の中心となる。']
    ]),
    P('成層圏の無人施設は、観測には大きな成果を上げたが、気象を整える力には限りがあった。フーモラ・スカイピルが参加して以降、気象安定化は世界規模のサービスとして広がっていった。')
  ]},'sec-functions');
  ins('weather-control',{ id:'sec-service', title:'気象安定サービス', blocks:[
    P('気象安定サービスは、フーモラ・スカイピルと各国との取り決めによって提供されている。各国は、自国の気候に合わせた安定化の内容と度合いを決め、その対価を支払う。'),
    P('そのため、どの国が、どこまで気候を安定させているかは国によって違う。ヒューバートやラリアフルスのように非常に安定した気候を保っている国がある一方、ガルヒューラやマイモックのように、気候が安定化されていない国もある。'),
    P('どのような仕組みで気象を整えているのか、その詳しい技術は公開されていない。フーモラ・スカイピルの住民の多くも、自分たちの国の暮らしを支えるその仕組みを詳しくは知らないと言われている。')
  ]},'sec-limits');
  ins('weather-control',{ id:'sec-debate', title:'空は誰のものか', blocks:[
    P('気象安定サービスが世界に広まるにつれ、世界の空の多くが一つの国の手に委ねられていることを問題視する声も上がった。もしフーモラ・スカイピルがサービスを止めれば、多くの国の農業や暮らしがたちまち影響を受けるからである。'),
    P('一方で、フーモラ・スカイピルは特定の国に肩入れせず、どの国にも同じ条件でサービスを提供することで信頼を保ってきた。空と共に生きることを掲げる自由国家は、空を独占する国としてではなく、空を整える国として受け入れられている。'),
    P('チリルド・アイルツアでは近年、建国以来続いてきた降雪が止まるという異変が起きている。その原因は分かっておらず、気象管理と関係があるのかどうかも、確かめられていない。')
  ]},'sec-impact');
  ins('weather-control',{ id:'sec-life', title:'暮らしと天気', blocks:[
    P('気候が安定した国では、天気予報が外れることはほとんどない。祭りや競技の日程を何か月も前から決められるのも、気象管理のおかげである。'),
    P('それでも、雨の日はなくならない。気象管理は雨を消す技術ではなく、雨が多すぎたり少なすぎたりしないよう整える技術だからである。雨の音を聞くのが好きだという人は、今も多い。'),
    Q('空は、まだ人のものではない。少しだけ、機嫌をうかがえるようになっただけだ。')
  ]});
  rel('weather-control',['rainy-day','chiriludo-ailtsua','garhyura','ice-age']);

  /* ================= 食品配送 ================= */
  addInfo('food-delivery','普及','統合暦1360年頃');
  ins('food-delivery',{ id:'sec-history', title:'歴史', blocks:[
    T(['時期','出来事'],[
      ['統合暦1300年頃','ヲンヘードに、世界中の食材が集まる物流網が完成する。'],
      ['統合暦1310年','世界食の日が制定される。'],
      ['統合暦1350年頃','世界テレポート中継網が完成する。'],
      ['統合暦1360年頃','中継網を応用し、調理済みの料理や生鮮食品を、鮮度を保ったまま短時間で届ける食品配送が広まる。']
    ])
  ]},'sec-system');
  ins('food-delivery',{ id:'sec-flow', title:'届くまで', blocks:[
    P('注文された料理は、店から近くの配送センターへ転送され、そこから自動配送で各家庭や職場へ届けられる。テレポートで運ばれるのは配送センターまでで、最後の短い距離は、地上を走る配送ロボットや小型の飛行機械が運ぶ。'),
    P('家庭へ直接テレポートしないのは、家庭用の転送装置で扱える大きさや重さに限りがあることに加え、温かい料理と冷たい料理を、それぞれの温度のまま届けるための専用の箱や設備が配送センターに集められているためである。'),
    T(['段階','内容'],[
      ['注文','ニューロシンクや端末から注文する。届く時刻を指定することもできる。'],
      ['店から配送センターへ','テレポート物流で運ぶ。国をまたぐ場合も、中継施設を経由して短時間で届く。'],
      ['配送センターから玄関へ','配送ロボットや小型の飛行機械が、温度を保つ専用の箱で届ける。'],
      ['受け取り','玄関の受け取り口や、職場の受け取り棚で受け取る。']
    ])
  ]},'sec-life');
  ins('food-delivery',{ id:'sec-kinds', title:'さまざまな配送', blocks:[
    T(['種類','内容'],[
      ['出前','飲食店の料理を、できたての状態で届ける。遠くの国の店の料理を頼むこともできる。'],
      ['生鮮食品','野菜、培養肉、魚などを届ける。海産物ではフレッシュレッシュ社の流通網が知られている。'],
      ['定期配送','決まった曜日や時刻に、決まった食材や完全栄養食を届ける。'],
      ['研究者向け','セルトシティの定刻ボックスのように、決まった時刻に届けられる食事もある。']
    ])
  ]},'sec-life');
  ins('food-delivery',{ id:'sec-culture', title:'食文化として', blocks:[
    P('世界中の料理がすぐに届くようになっても、人々は店へ食べに出かけることをやめなかった。届いた料理と、店で食べる料理は、同じ料理でも違うものとして楽しまれている。'),
    P('遠くの国の料理を取り寄せて食べることは、旅の代わりにもなる。一方で、本場の味を知った人が、今度は実際にその国へ出かけていく、ということも多い。食品配送は、食べる場所を家に閉じ込めるのではなく、世界の食卓をつなぐものになっている。'),
    Q('世界中の台所が、玄関の向こうにある。')
  ]});
  rel('food-delivery',['food-culture','freshresh','teikoku-box','perfectfood','tasumenio']);
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（15）
   『龍の理』は古代文明の時代の教祖（初代大司教）の言葉。古神教会が発見し、
   古代の解釈と今の龍教の解釈を合わせたものが、現在の龍教の龍の書の読み方となった。
   （前回の「統合暦008年ごろの人物・教祖ではない」という整理を置き換える）
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function sec(a,id){ return a ? a.sections.filter(function(s){return s.id===id;})[0] : null; }
  function P(t){ return { t:'p', text:t }; }
  function swapStart(s, start, text){ if(!s) return false; var hit=false; s.blocks.forEach(function(b){ if(b.text && b.text.indexOf(start)===0){ b.text=text; hit=true; } }); if(!hit) console.warn('ri2: not found', start.slice(0,20)); return hit; }

  /* ---- 『龍の理』 ---- */
  var r=art('ryu-no-ri-doctrine');
  if(r){
    r.lede='古代文明の時代に、龍を信じる人々の教祖であった初代大司教が、龍の書を読み解いて遺した言葉をまとめた教義書。龍の言葉を書き換えることは許されないとして、新たな神話を一切書かず、龍の書を解き明かすことだけに徹している。古神教会が古代文明期の遺跡から発見し、現在の龍教の龍の書の読み方の土台となった。';
    var ov=sec(r,'sec-overview');
    if(ov){ ov.blocks.forEach(function(b){ if(b.t==='info'){ b.items=[
      { label:'分類', value:'教義書' },
      { label:'遺した人物', value:'初代大司教（古代文明の時代の教祖）' },
      { label:'時代', value:'古代文明の時代' },
      { label:'発見', value:'古神教会が古代文明期の遺跡から発見' },
      { label:'もとにした書', value:'龍の書' },
      { label:'構成', value:'序・八章・終章' },
      { label:'中心', value:'龍教の五つの教え' } ]; } });
      swapStart(ov,'『龍の理』は、龍教の教典である龍の書を読み解き','『龍の理』は、龍の書を読み解き、そこから人がどう生きるべきかをまとめた教義書である。書かれたのは古代文明の時代で、龍を信じる人々の教祖であった初代大司教の言葉を伝えている。序に続いて八つの章と終章からなり、龍とは何か、創造、死、三つの戒め、エイリアス、そして龍教の五つの教えを語る。'); }
    var ab=sec(r,'sec-archbishop');
    if(ab){ ab.blocks=[
      P('『龍の理』を遺したのは、「初代大司教」と呼ばれる人物である。古代文明の時代、龍の書を信じる人々の信仰を導いた教祖であり、書の言葉を読み解いて、人々がどう生きるべきかを語った。'),
      P('「初代」という呼び名から、古代の信仰には大司教の位が受け継がれる組織があったと考えられている。しかし、二代目以降の大司教の名や言葉は見つかっておらず、その信仰がどのように終わったのかも分かっていない。初代大司教自身の名前も伝わっていない。'),
      P('古代の信仰と、現在の龍教は同じものではない。未来世界の龍教は、統合暦008年ごろにニポランの祭礼や民間信仰が龍の書をもとに再編されて生まれたもので、今も明確な教祖や宗教組織を持たない。龍教の人々にとって初代大司教は、自分たちを率いる存在ではなく、遠い昔に同じ書を読み、同じ龍を信じた先人として敬われている。')
    ]; }
    if(!sec(r,'sec-discovery')){
      var i=-1; r.sections.forEach(function(s,n){ if(s.id==='sec-archbishop') i=n; });
      r.sections.splice(i+1,0,{ id:'sec-discovery', title:'発見と、今の龍教', blocks:[
        P('『龍の理』は、古代の神々を研究する古神教会が、古代文明期の遺跡から発見した。古代文明の時代にもすでに「龍の書」と呼ばれる書が読まれ、それを信じる人々がいたことは、この発見によって初めて確かめられた。'),
        P('発見された『龍の理』には、古代の人々が龍の書をどう読んでいたのかが記されていた。それは、それまで未来世界の龍教が受け継いできた読み方と、重なるところも、違うところもあった。'),
        P('その後、古代の解釈と、それまでの龍教の解釈は照らし合わされ、両者を合わせた形が、現在の龍教における龍の書の読み方となった。龍教の五つの教えや、「龍の姿を求める者は、ついに龍を見ず」の言葉が広く知られるようになったのも、この時からである。'),
        { t:'table', headers:['','古代の解釈（『龍の理』）','発見前の龍教の解釈'], rows:[
          ['龍の書の位置づけ','教祖が読み解く教典','家や地域ごとに受け継がれる教え'],
          ['人物たちの物語','三つの戒めとして読む','地域ごとの説話として語る'],
          ['組織','大司教のもとにまとまる','教祖も組織も持たない'],
          ['現在の龍教','戒めと五つの教えを受け入れた','組織を持たない暮らしの信仰であり続けた']
        ]},
        P('古代の教えは受け入れられたが、古代の信仰の組織までが受け継がれたわけではない。龍教は、古代の言葉を胸に置きながら、今も家や地域ごとの暮らしの信仰として続いている。')
      ]});
    }
    swapStart(sec(r,'sec-life'),'『龍の理』そのものは、龍の書とは違って写本ごとの違いがほとんどない','『龍の理』そのものは、龍の書とは違って写本ごとの違いがほとんどない。古代の遺跡から見つかった一つの記録をもとに広まったためである。龍の言葉を書き換えないという書の考え方にならい、写す人々も一字も変えずに受け継いできた。');
    r.related=r.related||[]; ['kogamichurch','ancient-civilization'].forEach(function(x){ if(r.related.indexOf(x)<0) r.related.push(x); });
    r.updated=U;
  }

  /* ---- 龍教 ---- */
  var d=art('dragon-religion');
  if(d){
    var o=sec(d,'sec-overview');
    swapStart(o,'明確な開祖や成立年代は分かっておらず','現在の龍教には明確な開祖がいない。古くから日本各地で語り継がれてきた民間信仰が、長い年月を経て現在の形になったと考えられている。一方で、古代文明の時代には、初代大司教と呼ばれる教祖のもとで龍の書を信じる信仰があったことが、教義書『龍の理』の発見によって分かっている。');
    if(o) o.blocks.forEach(function(b){ if(b.t==='info') b.items.forEach(function(it){
      if(it.label==='教祖') it.value='なし（古代の信仰の教祖として初代大司教が知られる）';
      if(it.label==='教義書') it.value='『龍の理』（古代文明の時代の初代大司教の言葉）'; }); });
    var h=sec(d,'sec-history');
    if(h && !h.blocks.some(function(b){return b.text && b.text.indexOf('古神教会')>=0;})){
      h.blocks.splice(2,0,P('その後、古代の神々を研究する古神教会が、古代文明期の遺跡から教義書『龍の理』を発見した。そこに記された古代の龍の書の解釈は、それまでの龍教の解釈と照らし合わされ、両者を合わせた形が、現在の龍教における龍の書の読み方となっている。'));
    }
    swapStart(sec(d,'sec-belief'),'現在知られている文章も、誰が記したものなのか','現在広く知られている言葉の多くは、古代文明の時代の教祖・初代大司教が遺した教義書『龍の理』に由来する。一方、地域や家庭に伝わる言葉の中には、誰が記したのか分からないものも多く、長い年月の中で語り継がれるうちに少しずつ変化してきたと考えられている。');
    var c=sec(d,'sec-christianity');
    if(c && !c.blocks.some(function(b){return b.text && b.text.indexOf('『龍の理』')>=0;})){
      var k=-1; c.blocks.forEach(function(b,n){ if(b.text && b.text.indexOf('古代文明は近代文明よりはるか昔')===0) k=n; });
      c.blocks.splice(k+1,0,P('この食い違いをさらに大きくしたのが、古神教会による『龍の理』の発見である。古代文明の時代の教祖が龍の書を読み解いた言葉が残っていたことで、龍の書が近代文明よりはるか昔から読まれていたことは、ほぼ確かになった。'));
    }
    d.updated=U;
  }

  /* ---- 龍の書：来歴 ---- */
  var b=art('dragon-book');
  if(b){ b.sections.forEach(function(s){ if(s.title!=='来歴') return;
    swapStart(s,'近年は、発掘された古代文明期の記録の中に','古神教会が古代文明期の遺跡から教義書『龍の理』を発見したことで、古代文明の時代にも「龍の書」と呼ばれる書が読まれていたことが分かった。ただし、古代の龍の書そのものは見つかっていない。近年、龍の書と酷似した記述を含む古代文明期の記録があると報告する研究者もいるが、それが古代の龍の書の一部なのか、別の伝承なのかは確認されていない。'); });
    b.updated=U; }

  /* ---- 古神教会 ---- */
  var k=art('kogamichurch');
  if(k){ var a2=sec(k,'sec-activities')||k.sections.filter(function(s){return s.title==='主な活動';})[0];
    if(a2 && !a2.blocks.some(function(x){return x.text && x.text.indexOf('『龍の理』')>=0;})) a2.blocks.push(P('古代文明期の遺跡から、龍教の教義書『龍の理』を発見したことでも知られる。古代の人々が龍の書をどう読んでいたかを伝えるこの発見は、現在の龍教の龍の書の読み方にも大きな影響を与えた。'));
    k.related=k.related||[]; ['ryu-no-ri-doctrine','dragon-religion','dragon-book'].forEach(function(x){ if(k.related.indexOf(x)<0) k.related.push(x); });
    k.updated=U; }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（16）
   光学迷彩の許可を具体化／外骨格とサイボーグの重なり／動物翻訳機の種類は例にすぎない
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function sec(a,id){ return a ? a.sections.filter(function(s){return s.id===id;})[0] : null; }
  function P(t){ return { t:'p', text:t }; }
  function T(h,r){ return { t:'table', headers:h, rows:r }; }

  /* ---------- 光学迷彩：許可の具体化 ---------- */
  var oc=art('optical-camouflage'), rules=sec(oc,'sec-rules');
  if(rules && !rules.blocks.some(function(b){return b.text && b.text.indexOf('許可には三つの種類')>=0;})){
    rules.title='使用の制限と許可';
    rules.blocks=[
      P('光学迷彩を個人が持つこと、使うことは、多くの国で禁じられている。製造も許可を受けた工房に限られ、作られた装備は一つずつ番号をつけて登録される。登録は各国の管理機関が行い、その記録は世界平和協定の国際監視体制のもとで国どうしが共有している。危険な技術の利用を制限するという協定の考え方が、光学迷彩にもあてはめられているのである。'),
      P('許可には三つの種類がある。'),
      T(['許可の種類','内容'],[
        ['常時許可','組織の任務として日常的に光学迷彩を使う機関に与えられる。装備は組織が保管し、持ち出すたびに記録が残る。'],
        ['任務ごとの許可','一つの捜査や作戦に限って与えられる。任務が終われば装備は返却される。'],
        ['期間を限った許可','研究や観察、撮影など、決まった期間・決まった場所でのみ使える。使う場所の外へ持ち出すことはできない。']
      ]),
      P('現在、光学迷彩の使用が認められている主な機関は次のとおりである。'),
      T(['機関','許可の種類','使われ方'],[
        ['世界変異体対策総本部（SVH）','常時許可','封鎖区域での偵察や、変異体に気づかれずに要救助者へ近づく任務に使う。使えるのは、その任務に就く隊員に限られる。'],
        ['各国の警察','任務ごとの許可','重大な事件の捜査や、人質の救出などに限って使われる。使うには、その事件ごとに裁判所の許可が必要で、使用中の記録はすべて保存される。'],
        ['エヴォリオンズ研究所','任務ごとの許可','SVHと連携し、変異体の行動を近くから観察する調査に使う。'],
        ['対オルドレンジ機関','任務ごとの許可','海上や沿岸での出現地点の観測で、観測船や観測者の存在を気づかれないようにするために使う。海底での調査には使われていない。'],
        ['生物保護区ジャングラー','常時許可','ベルネアの保護区で、希少な生き物の暮らしを乱さずに観察・記録するために使う。'],
        ['ベルネアのドーム観察員','期間を限った許可','環境ドームでの長期観察に使う。許可はドームの中に限られる。'],
        ['研究機関・映像の制作','期間を限った許可','野生の生き物の記録映像の撮影や、学術調査に使う。申請のたびに審査がある。'],
        ['各国の防衛組織','常時許可（数に上限あり）','軍事を持つ国でも、配備できる数は世界平和協定の監視のもとで制限されている。軍事を持たない国は保有しない。']
      ]),
      P('一方で、民間の警備会社、報道機関、探偵、娯楽施設などには、光学迷彩の許可は出ない。個人が所持しているだけで罪になる国も多い。'),
      P('許可を受けた機関であっても、使用した時間、場所、使った人物は必ず記録され、あとから第三者が確かめられるようになっている。見えなくなる技術だからこそ、使った事実だけは見えるようにしておく、という考え方である。')
    ];
    oc.related=oc.related||[]; ['evolions','antioldrange','jungler','world-peace-treaty','svh-omega'].forEach(function(x){ if(art(x) && oc.related.indexOf(x)<0) oc.related.push(x); });
    oc.sections.forEach(function(s){ if(s.id==='sec-overview') s.blocks.forEach(function(b){ if(b.t==='info') b.items.forEach(function(it){ if(it.label==='許可される用途') it.value='SVH・警察・変異体や生き物の研究・観察・防衛組織など（登録制）'; }); }); });
    oc.updated=U;
  }

  /* ---------- 外骨格とサイボーグ ---------- */
  var ex=art('exoskeleton');
  if(ex){
    ex.lede='身体の外側に着て、筋力や姿勢を補う機械の骨格。建設や災害救助、重い物を扱う仕事、身体の衰えた人の暮らしの補助まで幅広く使われる。サイボーグ技術の外付け型の拡張機器と近い関係にあり、両者の境目ははっきりしないが、外骨格は身体の外に着て、脱げば元に戻ることを前提としている。';
    var ov=sec(ex,'sec-overview');
    if(ov) ov.blocks.forEach(function(b){ if(b.text && b.text.indexOf('身体に機械を組み込むサイボーグや')===0)
      b.text='外骨格は「着るもの」である。必要なときに着て、終われば脱ぐ。脱げば元の身体に戻ることが、外骨格の大きな特徴となっている。身体を機械で補うという点ではサイボーグ技術と共通するところが多く、とくに外付け型の身体拡張機器とは、技術的にも使われ方の上でも近い関係にある。'; });
    if(!sec(ex,'sec-cyborg')){
      var i=-1; ex.sections.forEach(function(s,n){ if(s.id==='sec-types') i=n; });
      ex.sections.splice(i+1,0,{ id:'sec-cyborg', title:'サイボーグとの関係', blocks:[
        P('外骨格とサイボーグ技術は、どちらも機械によって身体の働きを補ったり広げたりする技術であり、似ているところが多い。サイボーグ技術の身体拡張機器には、必要なときだけ装着する外付け型があり、補助腕や歩行を支える機器などは、外骨格とほとんど区別がつかない。'),
        T(['','外骨格','サイボーグ技術（外付け型の拡張機器）','サイボーグ技術（埋め込み型・置換）'],[
          ['身体との関係','身体の外に着る','身体に取り付ける','身体の中に組み込む・一部を置き換える'],
          ['主な目的','今ある身体の動きを、骨格に沿って全体的に支える','腕や尻尾など、新しい部位や機能を足す','失われた機能を補う・身体の一部になる'],
          ['外したとき','元の身体に戻る','元の身体に戻る','外すことを前提としない'],
          ['操作','身体の動きを読み取る。ニューロシンクで細かく操作できる','同左','神経に接続して身体の一部のように動かす']
        ]),
        P('実際には、外骨格に補助腕を取り付けたものや、外付け型の拡張機器を全身に組み合わせて外骨格のように使うものもあり、両者の境目はあいまいである。そのため、外骨格をサイボーグ技術の一つとして数える人もいれば、身体を変えない別の技術として分けて考える人もいる。'),
        P('どちらとして扱うかで、実際の暮らしが変わる場面もある。スポーツの部門分けでは、外骨格も外付け型の拡張機器も、競技中に身に着ければ同じ「拡張」として扱われる。一方、医療や保険の上では、身体に組み込むかどうかで扱いが分かれることが多い。')
      ]});
    }
    ex.updated=U;
  }
  var cy=art('cyborg'), mount=sec(cy,'sec-mount');
  if(mount && !mount.blocks.some(function(b){return b.text && b.text.indexOf('外骨格')>=0;})){
    mount.blocks.push(P('外付け型の拡張機器は、身体の外に着て筋力や姿勢を補う外骨格と近い関係にあり、両者の境目ははっきりしない。詳しくは、外骨格の項目を参照。'));
    cy.related=cy.related||[]; if(cy.related.indexOf('exoskeleton')<0) cy.related.push('exoskeleton');
    cy.updated=U;
  }

  /* ---------- 動物翻訳機：種類は例にすぎない ---------- */
  var at=art('animal-translator'), co=sec(at,'sec-companies');
  if(co && !co.blocks.some(function(b){return b.text && b.text.indexOf('ほんの一例')>=0;})){
    co.blocks=[
      P('動物翻訳機は数えきれないほどの会社から発売されており、精度も、話すときの口調も、会社や機種によって大きく違う。どの翻訳機を選ぶかは、飼い主がその動物にどう話してほしいかで決まることも多い。'),
      P('以下は、よく知られている型のほんの一例である。実際には会社の数だけ型があり、同じ会社でも機種ごとに話し方が違う。新しい型も毎年のように発売されている。'),
      T(['型の例','特徴'],[
        ['ていねい型','「お腹がすきました」「少し眠いです」のように、ていねいな言葉で話す。精度が高く、獣医や研究施設でも使われる。'],
        ['子ども口調型','「おなかすいたー！」「あそぼ！」のように話す。精度はそこそこだが、家庭で最も人気がある。'],
        ['気まま型','動物の性格に合わせて口調を変える。同じ機種でも、猫によってえらそうになったり甘えん坊になったりする。'],
        ['単語型','「空腹」「不安」「興味」のように、気持ちを単語だけで表示する。会話にはならないが、余計な解釈を加えないため、研究者に好まれる。'],
        ['執事型','「お嬢様がお帰りを待ちわびておられます」のように、動物の気持ちを第三者の立場から伝える。'],
        ['お国言葉型','チリルド・アイルツアの「〜ろ」のように、地域の言い回しで話す。地元の動物には地元の言葉が似合う、と選ばれる。'],
        ['詩人型','「窓の外の鳥が、今日の空を運んでくる」のように、気持ちを詩のような言葉に置き換える。正確さよりも雰囲気を楽しむ型。'],
        ['色と音型','言葉を使わず、首輪の光の色と短い音で気持ちを表す。言葉にすると気持ちがゆがむと考える人に選ばれる。'],
        ['声まね型','動物自身の鳴き声に近い声色のまま、人間の言葉を話す。不思議な聞こえ方が好まれる一方、苦手な人も多い。']
      ]),
      P('声の高さや話す速さ、口ぐせを飼い主が細かく決められる機種も多く、世界に一台だけの話し方を作ることもできる。'),
      P('同じ猫に違う会社の翻訳機をつけると、まったく違うことを話すことがある。そのため、二台の翻訳機を同時につけて、どちらが当たっているかを比べる遊びもある。')
    ];
    at.updated=U;
  }
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（17）
   光学迷彩：国の武装許可を得たTAC（戦闘・防衛企業）／WAR（軍事）企業の扱い
   ============================================================================ */
(function(){
  var U='2026.10.27';
  var a=ARTICLES.filter(function(x){return x.id==='optical-camouflage';})[0]; if(!a) return;
  var s=a.sections.filter(function(x){return x.id==='sec-rules';})[0]; if(!s) return;
  if(s.blocks.some(function(b){return b.text && b.text.indexOf('TAC')>=0;})) return;
  s.blocks.forEach(function(b){
    if(b.t==='table' && b.headers[0]==='機関'){
      var i=-1; b.rows.forEach(function(r,n){ if(r[0]==='各国の防衛組織') i=n; });
      b.rows.splice(i,0,
        ['【WAR】軍事企業','常時許可（数に上限あり）','国家級の武装組織に相当する企業。国家と防衛の契約を結んでいる場合に限り、その国の防衛組織と同じ扱いを受ける。配備できる数は、契約先の国の上限の中に含まれる。'],
        ['【TAC】戦闘・防衛企業','任務ごとの許可','国から武装の許可を得た企業に限る。国や国際機関から委託された任務（重要施設の防衛、要人の警護、封鎖区域の外周警備、SVHの後方支援など）のあいだだけ使える。自社の判断や民間からの依頼では使えない。']
      );
    }
  });
  s.blocks.forEach(function(b){
    if(b.text && b.text.indexOf('一方で、民間の警備会社、報道機関、探偵、娯楽施設などには')===0){
      b.text='一方で、武装の許可を持たない民間の警備会社、報道機関、探偵、娯楽施設などには、光学迷彩の許可は出ない。個人が所持しているだけで罪になる国も多い。';
    }
  });
  var k=-1; s.blocks.forEach(function(b,n){ if(b.text && b.text.indexOf('一方で、武装の許可を持たない')===0) k=n; });
  s.blocks.splice(k,0,{ t:'p', text:'TACやWARの企業が光学迷彩を使うには、まず国から武装組織としての許可を受けていることが前提となる。そのうえで、光学迷彩は企業の持ち物ではなく、委託した国や国際機関の管理する装備として貸し出される形がとられることが多い。任務が終われば装備は返却され、企業の手元には残らない。' });
  a.related=a.related||[]; if(a.related.indexOf('corporate-types')<0) a.related.push('corporate-types');
  a.updated=U;
})();
/* ============================================================================
   ARTICLES-EXPAND — 2026.10.27（18）公開前の整合チェックによる修正
   ・テレポーター：1998年以前に人の転送が全くなかったように読める書き方を改める
   ・重力制御：フーモラの浮遊構造と天翔の浮遊技術の関係を明記
   ============================================================================ */
(function(){
  var U='2026.10.27';
  function art(id){ for(var i=0;i<ARTICLES.length;i++){ if(ARTICLES[i].id===id) return ARTICLES[i]; } return null; }
  function sec(a,id){ return a ? a.sections.filter(function(s){return s.id===id;})[0] : null; }
  function swap(s, start, text){ if(!s) return; var hit=false; s.blocks.forEach(function(b){ if(b.text && b.text.indexOf(start)===0){ b.text=text; hit=true; } }); if(!hit) console.warn('audit: not found', start.slice(0,16)); }
  var t=art('teleporter'), h=sec(t,'sec-history');
  swap(h,'テレポート技術は、ヒューバートの生命情報解析','テレポート技術は、ヒューバートの生命情報解析と空間情報の研究から生まれ、テレパス社によって実用化された。最初に広く使われたのは、人ではなく物の輸送だった。');
  swap(h,'物を運ぶテレポートと、人を運ぶテレポートのあいだには','人の転送は、長いあいだ限られた施設と用途にとどまっていた。人の身体を扱う転送には、物の転送よりもはるかに厳しい審査と安全確認が求められたためである。誰もが日常的に転送港を使って国と国を行き来できるようになったのは、個人単位のテレポーターが世界規模で実用化された統合暦1998年以降のことで、まだ数十年しか経っていない。');
  if(h) h.blocks.forEach(function(b){ if(b.t==='table') b.rows.forEach(function(r){ if(r[0]==='統合暦1998年') r[1]='個人単位で人を転送するテレポーターが、世界規模で実用化される。人の転送が日常のものになる。'; }); });
  if(t) t.updated=U;
  var g=art('gravity-control'), f=sec(g,'sec-fumora');
  if(f) f.blocks=[
    { t:'p', text:'成層圏に浮かぶフーモラ・スカイピルは、重力制御で浮いていると思われがちである。しかし、フーモラの浮遊は、現在の人類が使っている重力制御とは別の仕組みによるものとされている。' },
    { t:'p', text:'フーモラの浮遊構造の維持や都市内の設備には、天翔の浮遊技術が使われている。ただし、それは空中に浮かぶ構造を保ち、整えるための技術であり、都市そのものを空に浮かべている根本の仕組みについては、詳しく公開されていない。' },
    { t:'p', text:'都市そのものを空に浮かべ続けるだけの重力制御は、今の人類の技術では実現できない。フーモラは、その意味で例外的な存在である。' }
  ];
  if(g){ g.related=g.related||[]; if(g.related.indexOf('tensho')<0) g.related.push('tensho'); g.updated=U; }
})();
